module.exports = class Range {;
  constructor(start, end) {
    this.start = start
    this.end = end
  }

  get length() {
    return Math.abs(this.end - this.start)
  }

  includes(position) {
    return position >= this.start && position <= this.end
  }

  overlaps(other) {
    return this.includes(other.start) || other.includes(this.start)
  }

  replace(source, replacement) {
    return source.slice(0, this.start) + replacement + source.slice(this.end)
  }

  insertStart(source, replacement) {
    return source.slice(0, this.start) + replacement + source.slice(this.start)
  }

  insertEnd(source, replacement) {
    return source.slice(0, this.end) + replacement + source.slice(this.end)
  }

  insertOnClosestSide(source, replacement, pos) {
    if (this.distance(this.start, pos) < this.distance(this.end, pos))
      return this.insertStart(source, replacement)
    else return this.insertEnd(source, replacement)
  }

  extract(str) {
    return str.slice(this.start, this.end)
  }

  distance = function (a, b) { return Math.abs(a - b)

  toString() {
    return "start: " + (this.start) + "\nend: " + (this.end) + ""
  }; }}

