function traverse(arr) {
  for (var counter = 0; counter < arr.length; counter++) {
    console.log(arr[counter]);
  }
}

// Complexity: O(n)
function insertAtPosition(items, position, item) {
  // Built-in option available in javascript
  // items.splice(position, 0, item)
  // return items;

  // Push all the items to the right until position
  for (var counter = items.length; counter > position; counter--) {
    items[counter] = items[counter - 1];
  }

  items[position] = item;

  return items;
}

// Complexity: O(n)
function deleteFromPosition(items, position) {
  // Built-in option available in javascript
  // items.splice(position, 1)
  // return items;

  for (var counter = position; counter < items.length; counter++) {
    items[counter] = items[counter + 1];
  }

  return items;
}

