 function deleteMessage(chatId, messageId)
 {
   var data = {
     method: "post",
     payload: {
       method: "deleteMessage",
       chat_id: String(chatId),
       message_id: String(messageId)
     }
   };
   UrlFetchApp.fetch('https://api.telegram.org/bot' + token + '/', data);
 }


