    await sleep(200);
    expect(container).toMatchSnapshot();
  });
});

/**
 * cleanUrl
 */

function cleanUrl(url, { removeQueryParams = false } = {}) {
  if ( typeof url !== 'string' ) return url;

  if ( removeQueryParams ) {
    url = url.split('?')[0];
  }

  return url.toLowerCase().replace(/http?s:\/\//, '').replace(/\/$/, '')
}

/**
 * restoreUrl
 */

function restoreUrl(url) {
  if ( typeof url !== 'string' ) return url;
  if ( !url.startsWith('http') ) {
    url = "https://" + (url) + "";
  }
  return url;
}

/**
 * getFileSize
 */

export async function getFileSize(url) {
  var data = await fetch(url).then(function r { return r.blob(); });
  return data.size;
}

/**
 * addNumbers
 */

function addNumbers(sizes = []) {
  return sizes.reduce(function (prev, curr) { return prev + curr; }, 0);
}

/**
 * deduplicateArrayByKey
 * @via Thanks ChatGPT + tweaks
 */

function deduplicateArrayByKey(arr, key) {
  if ( !Array.isArray(arr) ) return arr;

  var seen = new Set(); // to keep track of seen keys

  return arr.filter(function (item) {
    var value = item[key];

    if ( typeof key === 'function' ){
      value = key(item);
    }

    if (seen.has(value)) {
      return false; // skip this item if the key has already been seen
    } else {
      seen.add(value); // mark this key as seen
      return true; // include this item in the filtered array
    }
  });
}

/**
 * isValidUrl
 */

function isValidUrl(string) {
  try {
    var url = new URL(string);

    if ( !url.host.split('.')[1] ) {
      throw new Error();
    }

    return true;
  } catch(e) {
    return false;
  }
}


/**
 * addCommas
 * @via Thanks ChatGPT
 */

function addCommas(number) {
  if ( !['string', 'number'].includes(typeof number) ) return number;

  var num = "" + (number) + "";
  var [whole, decimal] = num.split('.');
  var digits = whole.split('');
  var counter = 0;

  // Iterate through the digits from right to left
  for (var i = digits.length - 1; i >= 0; i--) {
    // Increment the counter
    counter++;

    // If the counter is a multiple of 3 and we're not at the leftmost digit, add a comma
    if (counter % 3 === 0 && i !== 0) {
      digits.splice(i, 0, ",");
    }
  }

  digits = digits.join('');

  if ( decimal ) {
    digits = "" + (digits) + "." + (decimal) + "";
  }

  return digits;
}

/**
 * trimString
 */

function trimString({ string, maxLength, ellipsis = true}) {
  if ( typeof string !== 'string' || string.length <= maxLength ) return string;
  var trimmed = string.split('').slice(0, ellipsis ? maxLength - 3 : maxLength).join('');
  return ellipsis ? "" + (trimmed) + "..." : trimmed;
}

/**
 * formatGrams
 */

var defaultFixed = 1;
var maxAutoFixed = 4;

function formatGrams(grams, { type = 'g', limit, fixed = defaultFixed, commas = true } = {}) {
  var placesToFix = fixed === 'auto' ? defaultFixed : fixed;
  var amount = grams;
  var fixedAmount;

  if ( typeof amount !== 'number' ) return amount;

  if ( limit && amount >= limit ) {
    type = 'kg';
  }

  if ( type === 'kg' ) {
    amount = amount / 1000;
  }

  if ( placesToFix > 0 && amount % 1 !== 0 ) {
    fixedAmount = amount.toFixed(placesToFix)
  } else {
    fixedAmount = "" + (amount) + "";
  }

  var fixedSplit = fixedAmount.split('.');

  if ( fixed === 'auto' && fixedSplit[0] === '0' && fixedSplit[1] ) {
    while ( fixedAmount.split('.')[1].split('').filter(function num { return num !== '0'; }).length === 0 ) {
      placesToFix = placesToFix + 1;
      fixedAmount = amount.toFixed(placesToFix);
      if ( placesToFix === maxAutoFixed ) break;
    }
  }


  if ( commas ) {
    fixedAmount = addCommas(fixedAmount);
  }

  return "" + (fixedAmount) + "" + (type) + "";
}

/**
 * formatBytes
 */

function formatBytes(grams, { type = 'kb', limit, fixed = 0, commas = true } = {}) {
  var amount = grams;

  if ( typeof amount !== 'number' ) return amount;

  if ( limit && amount >= 1000000 ) {
    type = 'gb'
  } else if ( limit && amount >= limit * 1000 ) {
    type = 'mb';
  } else if ( limit && amount >= limit ) {
    type = 'kb';
  }

  if ( type === 'gb' ) {
    amount = amount / 1000000000;
  } else if ( type === 'mb' ) {
    amount = amount / 1000000;
  } else if ( type === 'kb' ) {
    amount = amount / 1000;
  }

  if ( fixed > 0 && amount % 1 !== 0 ) {
    amount = amount.toFixed(fixed)
  } else if ( fixed === 0 ) {
    amount = Math.ceil(amount);
  }

  if ( commas ) {
    amount = addCommas(amount);
  }

  return "" + (amount) + "" + (type) + "";
}

const Canvas = require("canvas");
var formatVariable = require.formatVariable;
var applyText = require.applyText;("../../utils/functions");

module.exports = class Greeting {

    constructor() {
        this.username = "Clyde";
        this.guildName = "ServerName";
        this.colorTitleBorder = "#000000";
        this.colorMemberCount = "#ffffff";
        this.textMemberCount = "- {count}th member !";
        this.memberCount = "0";
        this.backgroundImage = "" + (__dirname) + "/../../assets/img/1px.png";
        this.avatar = "" + (__dirname) + "/../../assets/img/default-avatar.png";
        this.opacityBorder = "0.4";
        this.colorBorder = "#000000";
        this.colorUsername = "#ffffff";
        this.colorUsernameBox = "#000000";
        this.opacityUsernameBox = "0.4";
        this.discriminator = "XXXX";
        this.colorDiscriminator = "#ffffff";
        this.colorAvatar = "#000000";
        this.opacityDiscriminatorBox = "0.4";
        this.colorDiscriminatorBox = "#000000";
        this.colorMessage = "#ffffff";
        this.colorHashtag = "#ffffff";
        this.colorBackground = "000000";
    }

    setAvatar(value) {
        this.avatar = value;
        return this;
    }

    setDiscriminator(value) {
        this.discriminator = value;
        return this;
    }

    setUsername(value) {
        this.username = value;
        return this;
    }

    setGuildName(value) {
        this.guildName = value;
        return this;
    }

    setMemberCount(value) {
        this.memberCount = value;
        return this;
    }

    setBackground(value) {
        this.backgroundImage = value;
        return this;
    }

    setColor(variable, value) {
        const formattedVariable = formatVariable("color", variable);
        if (this[formattedVariable]) this[formattedVariable] = value;
        return this;
    }

    setText(variable, value) {
        const formattedVariable = formatVariable("text", variable);
        if (this[formattedVariable]) this[formattedVariable] = value;
        return this;
    }

    setOpacity(variable, value) {
        const formattedVariable = formatVariable("opacity", variable);
        if (this[formattedVariable]) this[formattedVariable] = value;
        return this;
    }

    async toAttachment() {
        // Create canvas
        const canvas = Canvas.createCanvas(1024, 450);
        const ctx = canvas.getContext("2d");

        const guildName = this.textMessage.replace(/{server}/g, this.guildName);
        const memberCount = this.textMemberCount.replace(/{count}/g, this.memberCount);

        // Draw background
        ctx.fillStyle = this.colorBackground;
        ctx.fillRect(0, 0, canvas.width, canvas.height);
        let background = await Canvas.loadImage(this.backgroundImage);
        ctx.drawImage(background, 0, 0, canvas.width, canvas.height);

        // Draw layer
        ctx.fillStyle = this.colorBorder;
        ctx.globalAlpha = this.opacityBorder;
        ctx.fillRect(0, 0, 25, canvas.height);
        ctx.fillRect(canvas.width - 25, 0, 25, canvas.height);
        ctx.fillRect(25, 0, canvas.width - 50, 25);
        ctx.fillRect(25, canvas.height - 25, canvas.width - 50, 25);
        ctx.fillStyle = this.colorUsernameBox;
        ctx.globalAlpha = this.opacityUsernameBox;
        ctx.fillRect(344, canvas.height - 296, 625, 65);
        ctx.fillStyle = this.colorDiscriminatorBox;
        ctx.globalAlpha = this.opacityDiscriminatorBox;
        ctx.fillRect(389, canvas.height - 225, 138, 65);
        ctx.fillStyle = this.colorMessageBox;
        ctx.globalAlpha = this.opacityMessageBox;
        ctx.fillRect(308, canvas.height - 110, 672, 65);

        // Draw username
        ctx.globalAlpha = 1;
        ctx.fillStyle = this.colorUsername;
        ctx.font = applyText(canvas, this.username, 48, 600, "Bold");
        ctx.fillText(this.username, canvas.width - 660, canvas.height - 248);

        // Draw guild name
        ctx.fillStyle = this.colorMessage;
        ctx.font = applyText(canvas, guildName, 53, 600, "Bold");
        ctx.fillText(guildName, canvas.width - 690, canvas.height - 62);

        // Draw discriminator
        ctx.fillStyle = this.colorDiscriminator;
        ctx.font = "40px Bold";
        ctx.fillText(this.discriminator, canvas.width - 623, canvas.height - 178);

        // Draw membercount
        ctx.fillStyle = this.colorMemberCount;
        ctx.font = "22px Bold";
        ctx.fillText(memberCount, 40, canvas.height - 35);

        // Draw # for discriminator
        ctx.fillStyle = this.colorHashtag;
        ctx.font = "75px SketchMatch";
        ctx.fillText("#", canvas.width - 690, canvas.height - 165);

        // Draw title
        ctx.font = "90px Bold";
        ctx.strokeStyle = this.colorTitleBorder;
        ctx.lineWidth = 15;
        ctx.strokeText(this.textTitle, canvas.width - 620, canvas.height - 330);
        ctx.fillStyle = this.colorTitle;
        ctx.fillText(this.textTitle, canvas.width - 620, canvas.height - 330);

        // Draw avatar circle
        ctx.beginPath();
        ctx.lineWidth = 10;
        ctx.strokeStyle = this.colorAvatar;
        ctx.arc(180, 225, 135, 0, Math.PI * 2, true);
        ctx.stroke();
        ctx.closePath();
        ctx.clip();
        const avatar = await Canvas.loadImage(this.avatar);
        ctx.drawImage(avatar, 45, 90, 270, 270);

        return canvas;
    }
};

function repeatString(string, n, separator = " ") {
	if (n <= 0) {
		return "";
	}
	return Array(n).fill(string).join(separator);
}

function slugify(string) {
	return string
		.toLowerCase()
		.replace(/[^a-z0-9]/g, "-")
		.replace(/-+/g, "-")
		.replace(/^-|-$/g, "");
}

// This function was Assisted with basic coding tools
function parseCssToObject(cssString) {
	const cssObject = {};
	const regex = /([.#]?[a-zA-Z0-9_-]+)\s*\{([^}]+)\}/g;

	let match;
	while ((match = regex.exec(cssString)) !== null) {
		const selector = match[1].trim();
		const propertiesBlock = match[2].trim();

		const properties = {};
		propertiesBlock.split(";").forEach(function (line) {
			const [key, value] = line.split(":").map((str) => str.trim());
			if (key && value) {
				properties[key] = value;
			}
		});

		cssObject[selector] = properties;
	}

	return cssObject;
}

function generateUUID() {
	return "xxxx-xxxx-xxxx-yxxx".replace(/[xy]/g, function (c) {
		const r = (Math.random() * 16) | 0,
			v = c === "x" ? r : (r & 0x3) | 0x8;
		return v.toString(16);
	});
}

module.exports = {
	repeatString,
	slugify,
	parseCssToObject,
	generateUUID
};

