    /***************************************************************************
     *  Create a HTMLElement:
     *      [tag, attrs, content, events]
     *
     *      tag     -> string
     *
     *      attrs   -> {key:string}
     *                  Special case for key=='style'
     *                      could be `style:'string'`
     *                      or `style:{k:s}`
     *                 Special case for key=='i18n' (or 'data-i18n' or 'data_i18next')
     *                      will be 'data-i18n' attr
     *
     *      content -> string | [createElement2() or parameters of createElement2]
     *                  if string begins with '<' then
     *                      it will be converted to HTMLElement
     *                          content = createOneHtml(string)
     *                  if attrs['i18n'] is not empty then (or 'data-i18n' or 'data_i18next')
 *                          it will be overridden with the translation
     *                          content = i18next.t(attrs['i18n']));
     *
     *      events  -> {event: ()}
     *
     *  Return the created element
     *
     *  Examples:
     *      ['div', { class: 'window-top', style: 'border-bottom: 1px solid black;' },
     *          [
     *              ['span', {}, 'title'],
     *              ['button', {}, 'Close', {
     *                  click: (e) => {
     *                      e.target.closest('.window').remove();
     *                  }
     *              }]
     *          ]
     *      ]
     *
     *      ['span', {style: {position: 'absolute'} }, 'title'],
     *
     ***************************************************************************/
    function createElement2(description) {
        var [tag, attrs, content, events] = description;

        /*
         *  Create the html element
         */
        if (!tag) {
            console.error("Tag must be a valid HTML element.");
            return;
        }
        var el = document.createElement(tag);

        /*
         *  Append attributes
         */
        var data_i18next = '';

        if(attrs && typeof attrs === 'object') {
            for (var attr in attrs) {
                if (attr === 'style' && typeof attrs[attr] === 'object') {
                    // Convert the style object to a CSS string
                    var styleString = '';
                    for (var prop in attrs[attr]) {
                        styleString += "" + (prop) + ": " + (attrs[attr][prop]) + ";";
                    }
                    el.style.cssText = styleString;
                } else if (attr === 'style') {
                    el.style.cssText = attrs[attr];
                } else {
                    if(attr === 'i18n' || attr === 'data-i18n' ||
                            attr === 'data_i18next' || attr === 'data-i18next') {
                        data_i18next = attrs[attr];
                        el.setAttribute('data-i18n', data_i18next);
                    } else {
                        el.setAttribute(attr, attrs[attr]);
                    }
                }
            }
        }

        /*
         *  Append content, it can be a string or another kids
         */
        if(is_string(content)) {
            content = content.trim();
            if(content.length > 0 && content[0] === '<') {
                el.appendChild(createOneHtml(content));
            } else {
                if(data_i18next) {
                    el.textContent = i18next.t(data_i18next);
                } else {
                    el.textContent = content;
                }
            }
        } else if(is_array(content)) {
            if(content.length > 0) {
                if(is_string(content[0])) {
                    el.appendChild(createElement2(content));
                } else {
                    for (var child of content) {
                        // Check if the child is an array description or an HTMLElement
                        if (Array.isArray(child) && child.length > 0) {
                            el.appendChild(createElement2(child));
                        } else if (child instanceof HTMLElement) {
                            el.appendChild(child);
                        }
                    }
                }
            }
        } else if(content instanceof HTMLElement ||
                content instanceof Text ||
                content instanceof SVGElement)
        {
            el.appendChild(content);
        } else {
            if(content !== undefined) {
                log_error("content ignored");
                console.error(content);
            }
        }

        /*
         *  Attach event listeners
         */
        if (events && typeof events === 'object') {
            for (var eventType in events) {
                el.addEventListener(eventType, events[eventType]);
            }
        }

        return el;
    }

    /***************************************************************************
     * Create SVG element from string code
     ***************************************************************************/
    function parseSVG(string) {
        return ((new DOMParser().parseFromString(string, 'image/svg+xml')).firstChild);
    }

    /***************************************************************************
     *  Code Drafted using common development resources
        // Usage example:
        var element = document.getElementById("myElement");
        var position = getPositionRelativeToBody(element);
        console.log("Top: " + position.top + ", Left: " + position.left + ", Right: " + position.right + ", Bottom: " + position.bottom);
     ***************************************************************************/
    function getPositionRelativeToBody(element)
    {
        var rect = element.getBoundingClientRect();
        var scrollTop = window.pageYOffset || document.documentElement.scrollTop || document.body.scrollTop;
        var scrollLeft = window.pageXOffset || document.documentElement.scrollLeft || document.body.scrollLeft;

        var top = rect.top + scrollTop;
        var left = rect.left + scrollLeft;
        var right = left + rect.width;
        var bottom = top + rect.height;

        return {
            top: top,
            left: left,
            right: right,
            bottom: bottom
        };
    }

    /***************************************************************************
     *  Function to convert dataset (of DOM Element) to plain object
     ***************************************************************************/
    function datasetToObject(dataset)
    {
        return Object.fromEntries(
            Object.entries(dataset).map(function ([key, value]) { return [key, value]; })
        );
    }

    /************************************************************
     *   Build name
     ************************************************************/
    function build_name(self, name)
    {
        // We need unique names
        if(empty_string(self.gobj_name())) {
            if(!self._uuid_name) {
                self._uuid_name = get_unique_id(self.gobj_gclass_name());
            }
            return self._uuid_name + "-" + name;
        }
        return self.gobj_escaped_short_name() + "-" + name;
    }

    /************************************************************
     *   Build gobj clean name
     ************************************************************/
    function build_clean_gobj_name(self, name)
    {
        var clean_name = self.gobj_short_name().replace(/[?# ^:]/g, '_');
        return name + "-" + clean_name;
    }

    /************************************************************
     *   Build clean name
     ************************************************************/
    function clean_name(name)
    {
        return name.replace(/[?# ^:]/g, '_');
    }

    /************************************************************
     *  Get the first gobj parent matching a gclass
     ************************************************************/
    function gobj_near_parent(gobj, gclass_name) // TODO put in gobj.c gobj.js
    {
        while (gobj) {
            gobj = gobj.gobj_parent();
            if (gobj) {
                // Check if the element has defined width and height
                if(gobj.gobj_gclass_name() === gclass_name) {
                    return gobj;
                }
            }
        }
        return null; // No parent found
    }

    /************************************************************
     *  Get the first html parent matching a CSS selector
     *  - 'selector' is same parameter used by querySelector()
     *  TODO is the same as closest()?
     ************************************************************/
    function element_near_parent($element, selector)
    {
        while ($element) {
            if ($element.matches && $element.matches(selector)) {
                return $element;
            }
            $element = $element.parentElement;
        }
        return null; // Return null if no parent matching the selector is found
    }

    /************************************************************
     *  Check if a string is a number
     *  The function correctly identifies both integer and floating-point numbers.
     *  It handles special cases like scientific notation (e.g., "1.2e3"),
     *  positive/negative numbers, and fractional numbers without leading digits.
     *  It returns false for non-numeric strings, empty strings,
     *  and strings with only whitespace.
     ************************************************************/
    function is_pure_number(str)
    {
        if(is_number(str)) {
            return true;
        }
        if(!is_string(str)) {
            return false;
        }

        // Convert the string to a number
        var num = Number(str);

        // Check if the result is NaN (Not-a-Number)
        if (isNaN(num)) {
            return false; // The string is not a number
        }

        // Optionally, you can check if the input is exactly equal to the parsed number
        // This ensures that the input is a valid number string
        return str.trim() !== '' && !isNaN(num);
    }

    /************************************************************
     * Example Usage
     *     const tracker = timeTracker("Track1");
     *     tracker.mark("Step 1");
     *     tracker.mark("Step 2");
     ************************************************************/
    function timeTracker(tracker_name="Time Tracker", verbose=false)
    {
        var name = tracker_name;
        var startTime = performance.now();
        var lastMarkTime = startTime;

        if(verbose) {
            log_warning(
                "--> " + (name) + " - starting"
            );
        }

        return {
            mark: function (label = "Intermediate", result="") {
                var currentTime = performance.now();
                var partial = (currentTime - lastMarkTime) / 1000;
                var total = (currentTime - startTime) / 1000;
                if(verbose) {
                    log_warning(
                        "--> " + (name) + " " + (label) + " - partial: " + (partial) + " sec, total: " + (total) + " sec, " + (result) + ""
                    );
                }
                lastMarkTime = currentTime;
                return {
                    partial: partial,
                    total: total
                };
            }
        };
    }

    /************************************************************
     *        Get current date
     *        Return string in "2022/09/12 12:27:15" format
     ************************************************************/
    function get_current_datetime()
    {
        var currentTime = new Date();
        var month = currentTime.getMonth() + 1;
        if (month < 10) {
            month = "0" + month;
        }
        var day = currentTime.getDate();
        if (day < 10) {
            day = "0" + day;
        }
        var year = currentTime.getFullYear();
        var fecha = year + "/" + month + "/" + day;

        var hours = currentTime.getHours();
        if (hours < 10) {
            hours = "0" + hours;
        }
        var minutes = currentTime.getMinutes();
        if (minutes < 10) {
            minutes = "0" + minutes;
        }
        var seconds = currentTime.getSeconds();
        if (seconds < 10) {
            seconds = "0" + seconds;
        }
        var hora = hours + ":" + minutes + ":" + seconds;
        return fecha + " " + hora;
    }

    /********************************************
     *  Return UTC time of right now
     ********************************************/
    function get_now()
    {
        var start = Math.floor(Date.now() / 1000);
        return start;
    }


