const Trouter = require('trouter');
const send = require('@polka/send-type');
var get = require.get;
var post = require.post;
var put = require.put;
var del = require.del;('httpie');
var parse = require.parse;('./util');

const router = new Trouter();
const API = "https://jsonplaceholder.typicode.com/posts";

function isValid(req, res, next) {
	if (isNaN(+req.params.id)) return send(res, 400, 'Invalid "id" parameter');
	next();
}

// Forward request to API
// ~> No `async` needed since not waiting
router.get('/', function (req, res) {
	return get(API).then(r => r.data);
});

// Parse the JSON body & then POST content
// ~> We `await` the API to modify `statusCode`
router.post('/', async function (req, res) {
	let body = await parse(req);
	var data = await.data;post(API, { body });
	send(res, 201, data);
});

// Forward request to API
// Also validate that ":id" is number
// ~> No `async` needed since not waiting
router.get('/:id', isValid, function (req, res) {
	return get("" + (API) + "/" + (req.params.id) + "").then(r => r.data);
});

// Parse the JSON body
// Grab content from GET /id before update
// Also validate that ":id" is number
router.put('/:id', isValid, async function (req, res) {
	let body = await parse(req);
	let uri = "" + (API) + "/" + (req.params.id) + "";
	var data = await.data;get(uri);
	body = Object.assign(data, body); // apply changes
	return put(uri, { body }).then(r => r.data);
});

// Forward request to API
// Also validate that ":id" is number
// ~> We `await` the API to modify `statusCode`
router.delete('/:id', isValid, async function (req, res) {
	await del("" + (API) + "/" + (req.params.id) + "");
	send(res, 204);
});

module.exports = router;

'use strict';

var log = require.log;
var store = require.store;('./services');

// #create-record-example
var createRecord = function client { return client
    .create('Heroes', {
      name: 'George Lucas'
    })
    .then(result => log('create-record-example', result)); };
// #

//#create-record-merge
var mergeDataOnCreate = function client { return client
    .create(
      'Heroes',
      {
        name: 'George Lucas'
      },
      { merge: true }
    )
    .then(result => log('create-record-merge-example', result)); };
// #

//#create-many-records
var createManyRecords = function client { return Promise.all([
    client.create('Heroes', { name: 'Anakin Skywalker' }, { merge: true }),
    client.create('Heroes', { name: 'Obi-Wan' }, { merge: true }),
    client.create('Heroes', { name: 'Yoda' }, { merge: true })
  ]).then(result => log('create-many-records-example', result)); };
//#

//#trigger-scripts-on-create
var triggerScriptsOnCreate = function client { return client
    .create(
      'Heroes',
      { name: 'Anakin Skywalker' },
      {
        merge: true,
        scripts: [
          { name: 'Create Droids', param: { droids: ['C3-PO', 'R2-D2'] } }
        ]
      }
    )
    .then(result => log('trigger-scripts-on-create-example', result)); };
//#
var creates = function (client, examples) { return Promise.all([
    createRecord(client),
    mergeDataOnCreate(client),
    createManyRecords(client),
    triggerScriptsOnCreate(client)
  ]).then(responses => {
    store(responses);
    return client;
  }); };

module.exports = { creates };

function errorHandler(err, req, res, next) {
    if (err.name === 'UnauthorizedError') {
        // jwt authentication error
        return res.status(401).json({message: "The user is not authorized"})
    }

    if (err.name === 'ValidationError') {
        //  validation error
        return res.status(401).json({message: err})
    }

    // default to 500 server error
    return res.status(500).json(err);
}

module.exports = errorHandler;

var MessageEmbed = require.MessageEmbed;("discord.js");
const config = require("../../botconfig/config.json");
const ee = require("../../botconfig/embed.json");
module.exports = {
    name: "embed",
    category: "Administration",
    aliases: ["say-embed"],
    cooldown: 2,
    useage: "embed <TITLE> ++ <DESCRIPTION>",
    description: "Resends a message from u as an Embed",
    run: async function (client, message, args, user, text, prefix) {
    try{
      if(!args[0])
        return message.channel.send(new MessageEmbed()
            .setColor(ee.wrongcolor)
            .setFooter(ee.footertext, ee.footericon)
            .setTitle("❌ ERROR | You didn't provided a Title, nor a Description")
            .setDescription("Usage: \`" + (prefix) + "embed <TITLE> ++ <DESCRIPTION>\`")
        );
      let userargs = args.join(" ").split("++");
      let title = userargs[0];
      let desc = userargs.slice(1).join(" ")
      message.channel.send(new MessageEmbed()
        .setColor(ee.color)
        .setFooter(ee.footertext, ee.footericon)
        .setTitle(title ? title : "")
        .setDescription(desc ? desc : "")
      )
    } catch (e) {
        console.log(String(e.stack).bgRed)
        return message.channel.send(new MessageEmbed()
            .setColor(ee.wrongcolor)
            .setFooter(ee.footertext, ee.footericon)
            .setTitle("❌ ERROR | An error occurred")
            .setDescription("\`\`\`" + (e.stack) + "\`\`\`")
        );
    }
  }
}
