DIS.log = {

	/**
	 * Forcibly crash the game.
	 * @param {string} error
	 */
	crash: function(error){
		var day = new Date();
		var file = "user/log/crashlog_" + day.getFullYear() + "_" + day.getMonth() + "_" + day.getDate() + "_" + day.getHours() + "_" + day.getMinutes()
