	// NsGUI is found
} else {
	DGUI = NsGUI;

	// override mouse state get function for DIS project
	DGUI.wrappers.getMouseState = function() {
		var MB = getv(43);
		var state = [
			[getv(51),getv(52)], // [x,y]
			(MB == 1005), // LMB trig
			(MB == 1006), // RMB trig
			0, // MB3 trig
			getv(1236), // MB4 trig
			getv(1235), // MB5 trig
			0, // wheelUp
			0, // wheelDown
		];
		return state;
	};

};


