// basically Drafted using standard development resources so you need to fix these anyway
// TODO: calc as float and round into int just before pushing into array.
function linearInterpolate(color1, color2, factor) {
	var a1 = (color1 >> 24) & 0xff;
	var r1 = (color1 >> 16) & 0xff;
	var g1 = (color1 >> 8) & 0xff;
	var b1 = color1 & 0xff;

	var a2 = (color2 >> 24) & 0xff;
	var r2 = (color2 >> 16) & 0xff;
	var g2 = (color2 >> 8) & 0xff;
	var b2 = color2 & 0xff;

	var r = Math.round(r1 + factor * (r2 - r1));
	var g = Math.round(g1 + factor * (g2 - g1));
	var b = Math.round(b1 + factor * (b2 - b1));
	var a = 0xff // Math.round(a1 + factor * (a2 - a1)); // With current 2003MP, you need not to consider about alpha channel

	return (a << 24) | (r << 16) | (g << 8) | b;
}

function getPixel(imageData, width, height, x, y) {
	if (x < 0 || x >= width || y < 0 || y >= height) {
		return 0; // If the pixel is out of picture, just return 0. 範囲外の場合は黒（または透明）を返す
	}
	return imageData[y * width + x];
}

function resizeImage(imageData, originalWidth, originalHeight,rate) {
	var newWidth = originalWidth * rate;
	var newHeight = originalHeight * rate;
	var resizedData = [];

	for (var y = 0; y < newHeight; y++) {
		for (var x = 0; x < newWidth; x++) {
			var srcX = (x / newWidth) * originalWidth;
			var srcY = (y / newHeight) * originalHeight;

			var x0 = Math.floor(srcX);
			var x1 = Math.min(Math.ceil(srcX), originalWidth - 1);
			var y0 = Math.floor(srcY);
			var y1 = Math.min(Math.ceil(srcY), originalHeight - 1);

			var factorX = srcX - x0;
			var factorY = srcY - y0;

			var p1 = getPixel(imageData, originalWidth, originalHeight, x0, y0);
			var p2 = getPixel(imageData, originalWidth, originalHeight, x1, y0);
			var p3 = getPixel(imageData, originalWidth, originalHeight, x0, y1);
			var p4 = getPixel(imageData, originalWidth, originalHeight, x1, y1);

			var p12 = linearInterpolate(p1, p2, factorX);
			var p34 = linearInterpolate(p3, p4, factorX);
			var pFinal = linearInterpolate(p12, p34, factorY);

			resizedData[y * newWidth + x] = pFinal;
		};
	};
	return resizedData;
};

module.exports = async function (promise, expectedRevertMessage="") {;
  try {
    await promise;
    return
  } catch (error) {
    let invalidOpcode = false;
    let outOfGas = false;
    let revert = false;
    if (expectedRevertMessage !== "") {
      // Check end of error string, it's where the revert reason is output.
      let expectedLen = expectedRevertMessage.length;
      if (expectedLen < error.message.length) {
          // Rather annoyingly, truffle adds a period if it can decode the revert reason.
          if (error.message.search('-- Reason given:') >= 0) {
            revert = expectedRevertMessage === error.message.substring(error.message.length-expectedLen-1, error.message.length-1);
          } else {
            revert = expectedRevertMessage === error.message.substring(error.message.length-expectedLen, error.message.length);
          }
      }
    } else {
      // TODO: Check jump destination to destinguish between a throw
      //       and an actual invalid jump.
      invalidOpcode = error.message.search('invalid opcode') >= 0;
      // TODO: When we contract A calls contract B, and B throws, instead
      //       of an 'invalid jump', we get an 'out of gas' error. How do
      //       we distinguish this from an actual out of gas event? (The
      //       testrpc log actually show an 'invalid jump' event.)
      outOfGas = error.message.search('out of gas') >= 0;
      revert = error.message.search('revert') >= 0;
    }

    assert(
      invalidOpcode || outOfGas || revert,
      'Expected throw with revert string \'' + expectedRevertMessage + '\', got \'' + error + '\' instead',
    );
    return;
  }
  assert.fail('Expected throw not received');
};

