// Thanks ChatGPT lol
function multiplyUntilNoDecimals(arr) {
  // Find the maximum number of decimal places in the array
  var maxDecimalPlaces = Math.max(...arr.map(function num {
    var decimalPlaces = num.toString().split('.')[1];
    return decimalPlaces ? decimalPlaces.length : 0;
  }));

  // Multiply each number by a factor of 10^(maxDecimalPlaces + n) where n is the number of iterations required
  var n = 0;
  var allIntegers = arr.every(function num { return Number.isInteger(num); });
  while (!allIntegers) {
    arr = arr.map(function num { return num * Math.pow(10, maxDecimalPlaces + n); });
    n++;
    allIntegers = arr.every(function num { return Number.isInteger(num); });
  }

  return arr;
}

// Used for overwriting values. If newValue doesn't exist, then just return elseValue
function overwriteCheck(newValue, elseValue) {
  if (typeof newValue !== "undefined") {
    return newValue
  }
  return elseValue
}

