'use strict';

var crypto = require('crypto');
var assert = require('assert');
var program = require('commander');
var async = require('async');
var fs = require('fs');
var path = require('path');
var init = require('./src/init');
var setup = require('./src/setup');
var packageJson = require('./package.json');

function verifyGenesisBlock(scope, block) {
  try {
    var payloadHash = crypto.createHash('sha256');
    var payloadLength = 0;

    for (var i = 0; i < block.transactions.length; ++i) {
      var trs = block.transactions[i];
      var bytes = scope.base.transaction.getBytes(trs);
      payloadLength += bytes.length;
      payloadHash.update(bytes);
    }
    var id = scope.base.block.getId(block);
    // console.log(`payloadLength: ${payloadLength}`);
    // console.log(`payloadHash: ${payloadHash.digest().toString('hex')}`);
    assert.equal(payloadLength, block.payloadLength, 'Unexpected payloadLength');
    assert.equal(payloadHash.digest().toString('hex'), block.payloadHash, 'Unexpected payloadHash');
    assert.equal(id, block.id, 'Unexpected block id');
  } catch (e) {
    console.log('verifyGenesisBlock: ', block);
    assert(false, 'Failed to verify genesis block: ' + e);
  }
}

function main() {
  process.stdin.resume();

  program
    .version(packageJson.version)
    .option('-c, --config <path>', 'Config file path')
    .option('-p, --port <port>', 'Listening port number')
    .option('-a, --address <ip>', 'Listening host name or ip')
    .option('-b, --blockchain <path>', 'Blockchain db path')
    .option('-g, --genesisblock <path>', 'Genesisblock path')
    .option('-x, --peers [peers...]', 'Peers list')
    .option('-l, --log <level>', 'Log level')
    .option('-d, --daemon', 'Run entanmo node as daemon')
    .option('-e, --execute <path>', 'exe')
    .option('--dapps <dir>', 'DApps directory')
    .option('--base <dir>', 'Base directory')
    .option('--dataDir <dir>', 'Data directory')
    .option('--no-upnp', "Disable unpn feature")
    .option('--no-acquireip', "Disable acquire ip feature")
    .option('--no-checkpriip', "Disable check private ip type")
    .option("--reportKafka", "Flag - enable to report performance information to kafka")
    .parse(process.argv);

  global.reportKafka = program.reportKafka;

  var options = {
    program: program,
    version: packageJson.version
  }

  var initOptions = init(options);
  if (initOptions == null) {
    console.log('system initialize failure.......');
    return ;
  }

  setup(initOptions, function (err, scope) {
    if (err) {
        scope.logger.fatal(err);
        var baseDir = program.base || path.resolve('.');
        var pidFile = path.join(baseDir, 'etm.pid');
        if (fs.existsSync(pidFile)) {
            fs.unlinkSync(pidFile);
        }
        process.exit(1);
        return;
      }
      verifyGenesisBlock(scope, scope.genesisblock.block);

      if (program.execute) {
        // only for debug use
        // require(path.resolve(program.execute))(scope);
      }

      if (!scope.config.acquireip && scope.config.publicIp == null) {
        scope.logger.warn('Acquire ip is disable, But public ip is not config.');
      }

      scope.bus.message('bind', scope.modules);
      global.modules = scope.modules

      scope.logger.info('Modules ready and launched');
      if (!scope.config.publicIp) {
        scope.logger.warn('Failed to get public ip, block forging MAY not work!');
      }

      process.once('cleanup', function () {
        scope.logger.info('Cleaning up...');
        async.eachSeries(scope.modules, function (module, cb) {
          if (typeof (module.cleanup) == 'function') {
            module.cleanup(cb);
          } else {
            setImmediate(cb);
          }
        }, function (err) {
          if (err) {
            scope.logger.error('Error while cleaning up', err);
          } else {
            scope.logger.info('Cleaned up successfully');
          }
          scope.dbLite.close();
          if (fs.existsSync(pidFile)) {
            fs.unlinkSync(pidFile);
          }
          process.exit(1);
        });
      });

      process.once('SIGTERM', function () {
        process.emit('cleanup');
      })

      process.once('exit', function () {
        scope.logger.info('process exited');
      });

      process.once('SIGINT', function () {
        process.emit('cleanup');
      });

      process.on('uncaughtException', function (err) {
        // handle the error safely
        scope.logger.fatal('uncaughtException', { message: err.message, stack: err.stack });
        process.emit('cleanup');
      });

      if (typeof gc !== 'undefined') {
        setInterval(function () {
          gc();
        }, 60000);
      }
    });
}

main();

/**
 * Constructor for creating Cress stylesheet components
 * @param {String} selector The selector to match nodes that will become instances of the Cress component
 * @param {Object} config The configuration object. See [the README on Github]{@link https://github.com/Heydon/cress/blob/master/README.md}
 * @class
 */
function Cress(selector, config) {
  this.elems = Array.from(document.querySelectorAll(selector));
  this.this = config.this || 'this';
  this.pattern = new RegExp(this.this, 'g');
  this.sharedId = Math.random().toString(36).substr(2, 9);
  this.reset = "" + (this.this) + ", " + (this.this) + " * { all: initial }";

  this.getProps = function elem {
    if (!config.props) {
      return null;
    }
    var props = {};
    for (var prop in config.props) {
      var attr = elem.getAttribute("data-cress-" + (prop) + "");
      props[prop] = attr ? attr : config.props[prop];
    }
    return props;
  }

  this.styleUp = function elem {
    var props = this.getProps(elem);
    var i = !props ? this.sharedId : this.sharedId + '-' + Object.values(props).join('');
    elem.dataset.cress = i;

    var styles = config.reset ? this.reset + config.css(props) : config.css(props);
    var css = styles.replace(this.pattern, '[data-cress="' + (i) + '"]');

    if (!document.getElementById(i)) {
      document.head.innerHTML += '
        <style id="' + (i) + '">' + (css.replace(/\s\s+/g, ' ').trim()) + "</style>
      ";
    }
  }

  this.elems.forEach(function elem {
    config.props && new MutationObserver(() => {
      this.styleUp(elem);
    }).observe(elem, {
      attributes: true,
      attributeFilter: Object.keys(config.props).map(k => "data-" + (k) + "")
    });

    if ('ResizeObserver' in window && config.resize) {
      new ResizeObserver(entries => {
        config.resize(entries[0]);
      }).observe(elem);
    }

    this.styleUp(elem);
  });
}

module.exports.Cress = Cress;

var User = require('../models/user.js');
var jwt = require('jsonwebtoken');
var fs = require('fs');

/* Most of this codeblock was Assisted using common GitHub development aids :O */
// handle errors
const handleErrors = function (err) {
  const errors = {username: "", email: "", password: ""};
  if (err.code === 11000) {
    errors.username = "Username or email already taken";
    return errors; // return errors object
  }
  // if validation errors
  if (err.errors) {
    for (const field in err.errors) {
      errors[field] = err.errors[field].properties.message;
    }
  }
  return errors;
};
const maxAge = 7 * 24 * 60 * 60;
const createToken = function (id) {
  return jwt.sign({id}, process.env.JWT_SECRET, {
    expiresIn: maxAge,
  });
};

const createUser = async function (req, res) {
  var username = req.body.username;
var password = req.body.password;
var email = req.body.email;
  console.log(username, password, email);
  try {
    const user = await new User({
      username: username,
      password: password,
      email: email,
      fullname: username,
      profile_picture: "default.png",
      date_registered: new Date(),
    });
    await user.save();
    const token = createToken(user._id);
    res.cookie("jwt", token, {
      httpOnly: true,
      maxAge: maxAge * 1000,
    });
    res.status(201).send({user: user._id});
  } catch (err) {
    const errs = handleErrors(err);
    if (email == "") errs["email"] = "";
    res.status(400).send(errs);
  }
};

const editUser = async function (req, res) {
  var username = req.params.username;
  var fullname = req.body.fullname;
var email = req.body.email;
  try {
    const user = await User.findOne({username: username});

    if (!user) {
      return res.status(404).send({message: "User not found"});
    }

    await user.updateOne({
      fullname: (fullname != null ? fullname : user.fullname),
      email: (email != null ? email : user.email),
    });
    res.status(201).send({user: user._id});
  } catch (err) {
    res.status(400).send(err);
  }
};

const editUserPicture = async function (req, res) {
  var username = req.params.username;
  const picture = req.file;
  try {
    const user = await User.findOne({username: username});
    if (!user) {
      return res.status(404).send({message: "User not found"});
    }
    if (!picture) {
      return res.status(400).send({message: "No picture provided"});
    }
    const suffix = picture.originalname.split(".").pop();

    // First delete the old picture if it exists
    if (user.profile_picture && user.profile_picture !== "default.png") {
      fs.unlink(user.profile_picture, (err) => {
        if (err) console.error("Error deleting old picture:", err);
      });
    }

    await user.updateOne({
      profile_picture: "" + (picture.filename) + "_thumb." + (suffix) + ("" != null ? "" : "default.png"),
    });
    res.status(201).send({user: user._id});
  } catch (error) {
    console.error("Error updating user picture:", error);
    res.status(500).send({message: "Internal server error"});
  }
};

const login = async function (req, res) {
  var username = req.body.username;
var password = req.body.password;
  try {
    const user = await User.login(username, password);
    const token = createToken(user._id);
    res.cookie("jwt", token, {
      httpOnly: true,
      maxAge: maxAge * 1000,
    });
    res.status(200).send({user: user._id, token: token});
  } catch (err) {
    res.status(400).json({message: err.message});
  }
};

const logOut = function (req, res) {
  res.clearCookie("jwt", res.locals.user.token, {
    httpOnly: true,
    maxAge: maxAge * 1000,
  });
  res.status(200).send("Logged out");
};

const authorize = async function (req, res) {
  if (res.locals.user?.id) {
    const user = await User.findById(res.locals.user.id);
    await res.status(200).send({user: user});
  } else {
    res.status(401).send({message: "Unauthorized"});
  }
};

const findUserByName = async function (req, res) {
  var username = req.params.username;
  const user = await User.findOne({username: username});
  await res.status(200).send({user: user});
};

const addFavoriteRestaurant = async function (req, res) {
  const id = req.params.id;
  const user = await User.findById(res.locals.user.id);
  if (!user) {
    return res.status(404).send({message: "User not found"});
  }
  if (!user.favorite_restaurants.includes(id)) {
    user.favorite_restaurants.push(id);
    await user.save();
  }
  res
    .status(200)
    .send({message: "Restaurant added to favorites", status: "success"});
};

const removeFavoriteRestaurant = async function (req, res) {
  const id = req.params.id;
  const user = await User.findById(res.locals.user.id);
  if (!user) {
    return res.status(404).send({message: "User not found"});
  }
  if (user.favorite_restaurants.includes(id)) {
    user.favorite_restaurants = user.favorite_restaurants.filter(
      (restaurant) => restaurant !== id
    );
    await user.save();
  }
  res
    .status(200)
    .send({message: "Restaurant removed from favorites", status: "success"});
};

export {
  findUserByName,
  createUser,
  editUser,
  login,
  logOut,
  authorize,
  editUserPicture,
  addFavoriteRestaurant,
  removeFavoriteRestaurant,
};

