    <style>pre{font-size: 14px}a{text-decoration: none}h4{color:#697f22;}</style>
</head>
<body>
    <h4>' + (header) + "</h4>
    <pre>" + (logs.map((r) => highlight(r)).join("\n")) + "</pre>
</body>
</html>");
});

