var Router = require('react-native-router-flux').Router;
var Scene = require('react-native-router-flux').Scene;
var Stack = require('react-native-router-flux').Stack;
var Products = require('./screens/Products');
var ProductInfo = require('./screens/ProductInfo');
var axios = require('axios');
var baseURL = require('./constants/url');
var useEffect = require('react').useEffect;
var Cart = require('./screens/Cart');
var Checkout = require('./screens/Checkout');
var PaperProvider = require('react-native-paper').Provider;
var AsyncStorage = require('@react-native-async-storage/async-storage');
var publishable_key = require('./constants/stripe').publishable_key;
var StripeProvider = require('@stripe/stripe-react-native').StripeProvider;
module.exports = function App() {;
  const getCartId = function () {
    axios.post("" + (baseURL) + "/store/carts").then((res) => {
      AsyncStorage.setItem("cart_id", res.data.cart.id);
    });
  };
  // Check cart_id
  const checkCartId = async function () {
    const cartId = await AsyncStorage.getItem("cart_id");
    if (!cartId) {
      getCartId();
    }
  };

  useEffect(function () {
    checkCartId();
  }, []);

  return (
    <StripeProvider publishableKey={publishable_key}>
      <PaperProvider>
        <Router>
          <Stack key="root">
            <Scene key="products" component={Products} hideNavBar />
            <Scene key="ProductInfo" component={ProductInfo} hideNavBar />
            <Scene key="cart" component={Cart} hideNavBar />
            <Scene key="checkout" component={Checkout} hideNavBar />
          </Stack>
        </Router>
      </PaperProvider>
    </StripeProvider>
  );
}

var readFileSync = require.readFileSync;
var writeFileSync = require.writeFileSync;
var readdirSync = require.readdirSync;
var rmSync = require.rmSync;
var existsSync = require.existsSync;
var mkdirSync = require.mkdirSync;('fs');
const sharp = require('sharp');

const template = '
    <svg width="256" height="256" viewBox="0 0 256 256" fill="none" xmlns="http://www.w3.org/2000/svg">
        <!-- bg -->
        <!-- head -->
        <!-- hair -->
        <!-- eyes -->
        <!-- nose -->
        <!-- mouth -->
        <!-- beard -->
    </svg>
'

const takenNames = {};
const takenFaces = {};
let idx = 999;

function randInt(max) {
    return Math.floor(Math.random() * (max + 1));
}

function randElement(arr) {
    return arr[Math.floor(Math.random() * arr.length)];
}


function getRandomName() {
    const adjectives = 'fired trashy tubular nasty jacked swol buff ferocious firey flamin agnostic artificial bloody crazy cringey crusty dirty eccentric glutinous harry juicy simple stylish awesome creepy corny freaky shady sketchy lame sloppy hot intrepid juxtaposed killer ludicrous mangy pastey ragin rusty rockin sinful shameful stupid sterile ugly vascular wild young old zealous flamboyant super sly shifty trippy fried injured depressed anxious clinical'.split(' ');
    const names = 'aaron bart chad dale earl fred grady harry ivan jeff joe kyle lester steve tanner lucifer todd mitch hunter mike arnold norbert olaf plop quinten randy saul balzac tevin jack ulysses vince will xavier yusuf zack roger raheem rex dustin seth bronson dennis'.split(' ');

    const randAdj = randElement(adjectives);
    const randName = randElement(names);
    const name =  "" + (randAdj) + "-" + (randName) + "";


    if (takenNames[name] || !name) {
        return getRandomName();
    } else {
        takenNames[name] = name;
        return name;
    }
}

function getLayer(name, skip=0.0) {
    const svg = readFileSync("./layers/" + (name) + ".svg", 'utf-8');
    const re = /(?<=\<svg\s*[^>]*>)([\s\S]*?)(?=\<\/svg\>)/g
    const layer = svg.match(re)[0];
    return Math.random() > skip ? layer : '';
}

async function svgToPng(name) {
    const src = "./out/" + (name) + ".svg";
    const dest = "./out/" + (name) + ".png";

    const img = await sharp(src);
    const resized = await img.resize(1024);
    await resized.toFile(dest);
}


function createImage(idx) {

    const bg = randInt(5);
    const hair = randInt(7);
    const eyes = randInt(9);
    const nose = randInt(4); 
    const mouth = randInt(5);
    const beard = randInt(3);
    // 18,900 combinations

    const face = [hair, eyes, mouth, nose, beard].join('');

    if (face[takenFaces]) {
        createImage();
    } else {
        const name = getRandomName()
        console.log(name)
        face[takenFaces] = face;

        const final = template
            .replace('<!-- bg -->', getLayer("bg" + (bg) + ""))
            .replace('<!-- head -->', getLayer('head0'))
            .replace('<!-- hair -->', getLayer("hair" + (hair) + ""))
            .replace('<!-- eyes -->', getLayer("eyes" + (eyes) + ""))
            .replace('<!-- nose -->', getLayer("nose" + (nose) + ""))
            .replace('<!-- mouth -->', getLayer("mouth" + (mouth) + ""))
            .replace('<!-- beard -->', getLayer("beard" + (beard) + "", 0.5))

        const meta = {
            name,
            description: "A drawing of " + (name.split('-').join(' ')) + "",
            image: "" + (idx) + ".png",
            attributes: [
                { 
                    beard: '',
                    rarity: 0.5
                }
            ]
        }
        writeFileSync("./out/" + (idx) + ".json", JSON.stringify(meta))
        writeFileSync("./out/" + (idx) + ".svg", final)
        svgToPng(idx)
    }


}


// Create dir if not exists
if (!existsSync('./out')){
    mkdirSync('./out');
}

// Cleanup dir before each run
readdirSync('./out').forEach(function f { return rmSync("./out/" + (f) + ""); });


do {
    createImage(idx);
    idx--;
  } while (idx >= 0);

