'use strict';

var user = require('../user');
var topics = require('../topics');
var posts = require('../posts');
var meta = require('../meta');
var privileges = require('../privileges');

var apiHelpers = require('./helpers');

var doTopicAction = apiHelpers.doTopicAction;

var websockets = require('../socket.io');
var socketHelpers = require('../socket.io/helpers');

var topicsAPI = module.exports;

topicsAPI.get = async function (caller, data) {
    var [userPrivileges, topic] = await Promise.all([
        privileges.topics.get(data.tid, caller.uid),
        topics.getTopicData(data.tid),
    ]);
    if (
        !topic ||
        !userPrivileges.read ||
        !userPrivileges['topics:read'] ||
        !privileges.topics.canViewDeletedScheduled(topic, userPrivileges)
    ) {
        return null;
    }

    return topic;
};

topicsAPI.create = async function (caller, data) {
    if (!data) {
        throw new Error('[[error:invalid-data]]');
    }

    var payload = { ...data };
    payload.tags = payload.tags || [];
    apiHelpers.setDefaultPostData(caller, payload);
    var isScheduling = parseInt(data.timestamp, 10) > payload.timestamp;
    if (isScheduling) {
        if (await privileges.categories.can('topics:schedule', data.cid, caller.uid)) {
            payload.timestamp = parseInt(data.timestamp, 10);
        } else {
            throw new Error('[[error:no-privileges]]');
        }
    }

    await meta.blacklist.test(caller.ip);
    var shouldQueue = await posts.shouldQueue(caller.uid, payload);
    if (shouldQueue) {
        return await posts.addToQueue(payload);
    }

    var result = await topics.post(payload);
    await topics.thumbs.migrate(data.uuid, result.topicData.tid);

    socketHelpers.emitToUids('event:new_post', { posts: [result.postData] }, [caller.uid]);
    socketHelpers.emitToUids('event:new_topic', result.topicData, [caller.uid]);
    socketHelpers.notifyNew(caller.uid, 'newTopic', { posts: [result.postData], topic: result.topicData });

    return result.topicData;
};

// Instructed to add by ChatGPT to fulfill testing purposes, code Drafted using common development resources
// Set up API to resolve topic
topicsAPI.resolve = async function (caller, data) {
    await doTopicAction('resolve', 'event:topic_resolved', caller, {
        tids: data.tids,
    });
};

topicsAPI.reply = async function (caller, data) {
    if (!data || !data.tid || (meta.config.minimumPostLength !== 0 && !data.content)) {
        throw new Error('[[error:invalid-data]]');
    }
    var payload = { ...data };
    apiHelpers.setDefaultPostData(caller, payload);

    await meta.blacklist.test(caller.ip);
    var shouldQueue = await posts.shouldQueue(caller.uid, payload);
    if (shouldQueue) {
        return await posts.addToQueue(payload);
    }

    var postData = await topics.reply(payload); // postData seems to be a subset of postObj, refactor?
    var postObj = await posts.getPostSummaryByPids([postData.pid], caller.uid, {});

    var result = {
        posts: [postData],
        'reputation:disabled': meta.config['reputation:disabled'] === 1,
        'downvote:disabled': meta.config['downvote:disabled'] === 1,
    };

    user.updateOnlineUsers(caller.uid);
    if (caller.uid) {
        socketHelpers.emitToUids('event:new_post', result, [caller.uid]);
    } else if (caller.uid === 0) {
        websockets.in('online_guests').emit('event:new_post', result);
    }

    socketHelpers.notifyNew(caller.uid, 'newPost', result);

    return postObj[0];
};

topicsAPI.delete = async function (caller, data) {
    await doTopicAction('delete', 'event:topic_deleted', caller, {
        tids: data.tids,
    });
};

topicsAPI.restore = async function (caller, data) {
    await doTopicAction('restore', 'event:topic_restored', caller, {
        tids: data.tids,
    });
};

topicsAPI.purge = async function (caller, data) {
    await doTopicAction('purge', 'event:topic_purged', caller, {
        tids: data.tids,
    });
};

topicsAPI.pin = async function (caller, data) {
    await doTopicAction('pin', 'event:topic_pinned', caller, {
        tids: data.tids,
    });
};

topicsAPI.unpin = async function (caller, data) {
    await doTopicAction('unpin', 'event:topic_unpinned', caller, {
        tids: data.tids,
    });
};

topicsAPI.lock = async function (caller, data) {
    await doTopicAction('lock', 'event:topic_locked', caller, {
        tids: data.tids,
    });
};

topicsAPI.unlock = async function (caller, data) {
    await doTopicAction('unlock', 'event:topic_unlocked', caller, {
        tids: data.tids,
    });
};

topicsAPI.follow = async function (caller, data) {
    await topics.follow(data.tid, caller.uid);
};

topicsAPI.ignore = async function (caller, data) {
    await topics.ignore(data.tid, caller.uid);
};

topicsAPI.unfollow = async function (caller, data) {
    await topics.unfollow(data.tid, caller.uid);
};

require("dotenv").config()
const Web3 = require('web3');
var ChainId = require.ChainId;
var Token = require.Token;
var TokenAmount = require.TokenAmount;
var Pair = require.Pair;('@uniswap/sdk');
const abis = require('./abis');
const { mainnet: addresses } = require('./addresses');
const Flashloan = require('./build/contracts/Flashloan.json');

const web3 = new Web3(
  new Web3.providers.WebsocketProvider(process.env.QUIK_URL)
);
const { address: admin } = web3.eth.accounts.wallet.add(process.env.PRIVATE_KEY);

const kyber = new web3.eth.Contract(
  abis.kyber.kyberNetworkProxy,
  addresses.kyber.kyberNetworkProxy
);

const ONE_WEI = web3.utils.toBN(web3.utils.toWei('1'));
const AMOUNT_DAI_WEI = web3.utils.toBN(web3.utils.toWei('20000'));
const DIRECTION = {
  KYBER_TO_UNISWAP: 0,
  UNISWAP_TO_KYBER: 1
};

const init = async function () {
  const networkId = await web3.eth.net.getId();
  const flashloan = new web3.eth.Contract(
    Flashloan.abi,
    Flashloan.networks[networkId].address
  );

  let ethPrice;
  const updateEthPrice = async () => {
    const results = await kyber
      .methods
      .getExpectedRate(
        '0xeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeee',
        addresses.tokens.dai,
        1
      )
      .call();
    ethPrice = web3.utils.toBN('1').mul(web3.utils.toBN(results.expectedRate)).div(ONE_WEI);
  }
  await updateEthPrice();
  setInterval(updateEthPrice, 15000);

  web3.eth.subscribe('newBlockHeaders')
    .on('data', async block => {
      console.log("New block received. Block # " + (block.number) + "");

      const [dai, weth] = await Promise.all(
        [addresses.tokens.dai, addresses.tokens.weth].map(tokenAddress => (
          Token.fetchData(
            ChainId.MAINNET,
            tokenAddress,
          )
      )));
      const daiWeth = await Pair.fetchData(
        dai,
        weth,
      );

      const amountsEth = await Promise.all([
        kyber
          .methods
          .getExpectedRate(
            addresses.tokens.dai,
            '0xeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeee',
            AMOUNT_DAI_WEI
          )
          .call(),
        daiWeth.getOutputAmount(new TokenAmount(dai, AMOUNT_DAI_WEI)),
      ]);
      const ethFromKyber = AMOUNT_DAI_WEI.mul(web3.utils.toBN(amountsEth[0].expectedRate)).div(ONE_WEI);
      const ethFromUniswap = web3.utils.toBN(amountsEth[1][0].raw.toString());

      const amountsDai = await Promise.all([
        kyber
          .methods
          .getExpectedRate(
            '0xeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeee',
            addresses.tokens.dai,
            ethFromUniswap.toString()
          )
          .call(),
        daiWeth.getOutputAmount(new TokenAmount(weth, ethFromKyber.toString())),
      ]);
      const daiFromKyber = ethFromUniswap.mul(web3.utils.toBN(amountsDai[0].expectedRate)).div(ONE_WEI);
      const daiFromUniswap = web3.utils.toBN(amountsDai[1][0].raw.toString());

      ////////////////////////////////////////////////////////////////////////////////////////
      //var [gasPriceTest] = await Promise.all([
      //  web3.eth.getGasPrice(),
        //tx.estimateGas({from: admin}),
      //]);
      //console.log("<------------------Estimated Gas Price----------------------->");
      //console.log(gasPriceTest);
      ////////////////////////////////////////////////////////////////////////////////////////

      console.log("Kyber -> Uniswap. Dai input / output: " + (web3.utils.fromWei(AMOUNT_DAI_WEI.toString())) + " / " + (web3.utils.fromWei(daiFromUniswap.toString())) + "");
      console.log("Uniswap -> Kyber. Dai input / output: " + (web3.utils.fromWei(AMOUNT_DAI_WEI.toString())) + " / " + (web3.utils.fromWei(daiFromKyber.toString())) + "");

      if(daiFromUniswap.gt(AMOUNT_DAI_WEI)) {
        const tx = flashloan.methods.initiateFlashloan(
          addresses.dydx.solo,
          addresses.tokens.dai,
          AMOUNT_DAI_WEI,
          DIRECTION.KYBER_TO_UNISWAP
        );
        const [gasPrice, gasCost] = await Promise.all([
          web3.eth.getGasPrice(),
          tx.estimateGas({from: admin}),
        ]);

        console.log("<------------------Using Gas Price:----------------------->");
        console.log(web3.utils.toBN(gasPrice));
        const txCost = web3.utils.toBN(gasCost).mul(web3.utils.toBN(gasPrice)).mul(ethPrice);
        const profit = daiFromUniswap.sub(AMOUNT_DAI_WEI).sub(txCost);

        if(profit > 0) {
          console.log('Arb opportunity found Kyber -> Uniswap!');
          console.log("Expected profit: " + (web3.utils.fromWei(profit)) + " Dai");
          const data = tx.encodeABI();
          const txData = {
            from: admin,
            to: flashloan.options.address,
            data,
            gas: gasCost,
            gasPrice
          };
          const receipt = await web3.eth.sendTransaction(txData);
          console.log("Transaction hash: " + (receipt.transactionHash) + "");
        }
      }

      if(daiFromKyber.gt(AMOUNT_DAI_WEI)) {
        const tx = flashloan.methods.initiateFlashloan(
          addresses.dydx.solo,
          addresses.tokens.dai,
          AMOUNT_DAI_WEI,
          DIRECTION.UNISWAP_TO_KYBER
        );
        const [gasPrice, gasCost] = await Promise.all([
          web3.eth.getGasPrice(),
          tx.estimateGas({from: admin}),
        ]);
        const txCost = web3.utils.toBN(gasCost).mul(web3.utils.toBN(gasPrice)).mul(ethPrice);
        const profit = daiFromKyber.sub(AMOUNT_DAI_WEI).sub(txCost);

        if(profit > 0) {
          console.log('Arb opportunity found Uniswap -> Kyber!');
          console.log("Expected profit: " + (web3.utils.fromWei(profit)) + " Dai");
          const data = tx.encodeABI();
          const txData = {
            from: admin,
            to: flashloan.options.address,
            data,
            gas: gasCost,
            gasPrice
          };
          const receipt = await web3.eth.sendTransaction(txData);
          console.log("Transaction hash: " + (receipt.transactionHash) + "");
        }
      }
    })
    .on('error', error => {
      console.log(error);
    });
}
init();

