/**
 * Class for rendering charts in Obsidian.
 * To be used with DataviewJS, Obsidian Charts and CustomJS plugins
 * @author Olivier C <olo06@hotmail.fr>
 */
 class DvCharts {

    /**
     * Render a chart on a daily basis with a custom attribute extracted from dailies pages
     * @param {object} args - object to pass containing properties used
     * @param {object} args.dv - dataview object to perform queries
     * @param {object} args.context - context to be set to **this**, used to render chart in place
     * @param {string} args.daysPath - path to Daily notes
     * @param {string} args.dayFormat - format of daily pages in Moment format
     * @param {string} args.attr - attribute to query and render the value
     * @param {string} args.label - label to display in chart for corresponding attr
     * @param {number} args.limit - numbers of last pages containing values to display
     */
    renderSingleAttrChart(args) {

        var dv = args.dv;
var context = args.context;
var daysPath = args.daysPath;
var dayFormat = args.dayFormat;
var attr = args.attr;
var label = args.label;
var limit = args.limit;

        var days = dv.pages(daysPath)
            .where(function p { return p[attr] && moment(p.file.name, dayFormat).isValid(); })
            .sort(function p { return p.file.name; })
            .filter(function (p, i, arr) { return i >= arr.length - limit; });

        var dates = [], attrData = [];
        days.forEach(function p {
            dates.push(p.file.name);
            attrData.push(p[attr]);
        });

        var chartData = {
            type: 'line',
            data: {
                labels: dates,
                datasets: [{
                    label,
                    data: attrData,
                    backgroundColor: 'rgba(85, 174, 229, 0.2)',
                    borderColor: 'rgba(85, 174, 229, 1)',
                    borderWidth: 1,
                    fill: true,
                    tension: 0.2
                }],
            }
        }

        window.renderChart(chartData, context.container);
    }

    /**
     * Render a chart on a weekly basis from the specified date
     * @param {object} args - object to pass containing properties used
     * @param {object} args.dv - dataview object to perform queries
     * @param {object} args.context - context to be set to **this**, used to render chart in place
     * @param {string} args.daysPath - path to Daily notes
     * @param {string} args.dayFormat - format of daily pages in Luxon format
     * @param {string} args.attributes - object with keys as attributes to query and values as metadatas
     * @param {object} args.template - default template for completing datasets metadatas
     * @param {string} args.type - set it to **'average'** to display average data in chart
     * @param {string} args.date - date in YYYY-MM-DD format from which weekly days will be retrieved
     */
    renderWeeklyChart(args) {

        var {
            dv,
            context,
            daysPath = '""',
            dayFormat = 'yyyy-MM-dd',
            template = {
                label: "Default",
                backgroundColor: 'rgba(255, 99, 132, 0.2)',
                borderColor: 'rgba(255, 99, 132, 1)',
                borderWidth: 1,
                fill: true,
                tension: 0.2
            },
            attributes,
            type,
            date
        } = args;

        var datasets = (function () {
            var startOfWeek = dv.date("sow");
            var getWeeklyDay = dayNum => dv.pages('"' + (daysPath) + '"').find(
                p => p.file.name == startOfWeek.plus({ days: dayNum }).toFormat(dayFormat));
            var weeklydays = Array.from({ length: 7 }, (c, i) => getWeeklyDay(i) || 0);
            var getData = (attr, props) => weeklydays.map(p =>
                (type == 'average') ? (p[attr] / props.average * 100) || 0 : p[attr]);
            var datasets = {};

            for (var [attr, props] of Object.entries(attributes)) {
                datasets[attr] = Object.assign({}, template, props, {data: getData(attr, props)});
            }

            return Object.values(datasets);
        })();

        var chartData = {
            type: 'line',
            data: {
                labels: ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"],
                datasets,
            }
        }

        window.renderChart(chartData, context.container);
    }
}

// Forward Azure Monitor Logs to Syslog (via Event Hub)
// Developed as a sample for testing purpuses
// https://github.com/miguelangelopereira/azuremonitor2syslog
// miguelp@microsoft.com

module.exports = function (context, myEventHubMessage) {
    context.log("JavaScript eventhub trigger function called for message array " + (myEventHubMessage) + "");
    // initializing syslog
    try{
        var syslog = require("syslog-client");
    } catch (e) {
        throw e;
    }    


    // getting environment variables
    var SYSLOG_SERVER = GetEnvironmentVariable("SYSLOG_SERVER");
    var SYSLOG_PROTOCOL;
    if (GetEnvironmentVariable("SYSLOG_PROTOCOL")=="TCP") {
        SYSLOG_PROTOCOL = syslog.Transport.Tcp;
    } else {
        SYSLOG_PROTOCOL = syslog.Transport.Udp;
    }

    var SYSLOG_HOSTNAME;
    if (GetEnvironmentVariable("SYSLOG_HOSTNAME")==null) {
        SYSLOG_HOSTNAME = "azurefunction"
    } else {
        SYSLOG_HOSTNAME = GetEnvironmentVariable("SYSLOG_HOSTNAME");
    }

    var SYSLOG_PORT = GetEnvironmentVariable("SYSLOG_PORT");

    var SYSLOG_FACILITY;
    if (GetEnvironmentVariable("SYSLOG_FACILITY")==null) {
        SYSLOG_FACILITY = syslog.Facility.Local0;
    } else {
        SYSLOG_FACILITY = GetEnvironmentVariable("SYSLOG_FACILITY");
    }

    // options for syslog connection
    var options = {
        syslogHostname: SYSLOG_HOSTNAME,
        transport: SYSLOG_PROTOCOL,    
        port: SYSLOG_PORT,
        facility: SYSLOG_FACILITY
    };

    // log connection variables
    context.log('SYSLOG Server: ', SYSLOG_SERVER);
    context.log('SYSLOG Port: ', SYSLOG_PORT);
    context.log('SYSLOG Protocol: ', SYSLOG_PROTOCOL);
    context.log('SYSLOG Hostname: ', SYSLOG_HOSTNAME);
    context.log('SYSLOG Facility: ', SYSLOG_FACILITY);

    if ((SYSLOG_SERVER == null) || (SYSLOG_PORT == null) || (SYSLOG_PROTOCOL == null) || (SYSLOG_HOSTNAME == null)) {
        throw "Please setup environment variables. "
    }

    // log received message from event hub
    context.log("Event Hubs trigger function processed message:  " + (myEventHubMessage) + "");
    context.log('EnqueuedTimeUtc =', context.bindingData.enqueuedTimeUtc);
    context.log('SequenceNumber =', context.bindingData.sequenceNumber);
    context.log('Offset =', context.bindingData.offset);

    // create syslog client
    var client = syslog.createClient(SYSLOG_SERVER, options);

    // cycle through eventhub messages and send syslog
    myEventHubMessage.forEach(function (message, index) {
        if(typeof message === 'object'){

            var msg = JSON.parse(JSON.stringify(message));
            msg.records.forEach((m1, i) => {
                client.log(JSON.stringify(m1), options, function(error) {        
                    if (error) {
                        context.log("error sending message");
                        context.log(error);
                    } else {
                        context.log("sent message successfully");
                    }
                });
            });

        }
    });


      context.log("completed sending all messages");

    context.done();
};

function GetEnvironmentVariable(name)
{
    return process.env[name];
}

