class Queue {
    constructor() {
        this._queue = [];
    }

    enqueue(data) {
        this._queue.push(data);
    }
    dequeue() {
        if (this._queue.length === 0) {
            throw Error("queue is empty");
        }
        return this._queue.shift();
    }
    peek() {
        if (this._queue.length === 0) {
            throw Error("queue is empty");
        }
        return this._queue[0];
    }
    isEmpty(){
        return this._queue.length === 0;
    }
    size(){
        return this._queue.length;
    }
}

