/**
 * Returns an object containing only those keys from `obj` whose value
 * differs from `base`. Works recursively on nested objects.
 *
 * This function has been Aided using common development resources.
 */
function getConfigDiff(obj, base) {
    var diff = {}

    for (var key in obj) {
        var val = obj[key]
        var def = base[key]

        if (typeof val === 'object' && val !== null && !Array.isArray(val)) {
            var nested = getConfigDiff(val, def || {})
            if (Object.keys(nested).length > 0) {
                diff[key] = nested
            }
        } else {
            var isArray = Array.isArray(val)
            var changed = isArray
                ? JSON.stringify(val) !== JSON.stringify(def)
                : val !== def

            if (changed) {
                diff[key] = val
            }
        }
    }

    return diff
}

const Main = imports.ui.main;
var St = imports.gi.St;
var GLib = imports.gi.GLib;
const GObject = imports.gi.GObject;
const Clutter = imports.gi.Clutter;
const Gio = imports.gi.Gio;
const PanelMenu = imports.ui.panelMenu;
const PopupMenu = imports.ui.popupMenu;
var Me = imports.misc.extensionUtils.getCurrentExtension();

let commandMenuPopup;
let commandMenuSettings;
let commands = {};
let commandMenuSettingsId = [];

function getSettings () {
  let GioSSS = Gio.SettingsSchemaSource;
  let schemaSource = GioSSS.new_from_directory(
    Me.dir.get_child("schemas").get_path(),
    GioSSS.get_default(),
    false
  );
  let schemaObj = schemaSource.lookup(
    'org.gnome.shell.extensions.commandmenu', true);
  if (!schemaObj) {
    throw new Error('cannot find schemas');
  }
  return new Gio.Settings({ settings_schema : schemaObj });
}

function reloadExtension() {
  commands = {};
  commandMenuPopup.destroy();
  addCommandMenu();
}

function editCommandsFile () {
  // Check if ~/.commands.json exsists (if not create it)
  let file = Gio.file_new_for_path(GLib.get_home_dir() + '/.commands.json');
  if (!file.query_exists(null)) {
    file.replace_contents(JSON.stringify(commands), null, false, 0, null);
  }
  // Edit ~/.commands.json
  Gio.AppInfo.launch_default_for_uri('file://' + GLib.get_home_dir() + '/.commands.json', null).launch(null, null);
}

function populateMenuItems(menu, cmds, level) {
  cmds.forEach(function (cmd) {
    if (cmd.type === 'separator') {
      menu.addMenuItem(new PopupMenu.PopupSeparatorMenuItem());
      return;
    }
    if (!cmd.title) { return; }
    if (cmd.type === 'submenu' && level === 0) { // Stop submenu from being added after the first level
      let submenu;
      if (!cmd.submenu) { return; }
      submenu = new PopupMenu.PopupSubMenuMenuItem(cmd.title);
      populateMenuItems(submenu.menu, cmd.submenu, level + 1);
      menu.addMenuItem(submenu);
      return;
    }
    if (!cmd.command) { return; }
    let item;
    if (cmd.icon) {
      item = new PopupMenu.PopupImageMenuItem(
        cmd.title,
        cmd.icon
      );
    } else {
      item = new PopupMenu.PopupMenuItem(cmd.title);
    }
    item.connect('activate', () => {
      GLib.spawn_command_line_async(cmd.command);
    });
    menu.addMenuItem(item);
  })
}

function redrawMenu (popUpMenu) {
  let menuTitle = commands.title && commands.title.length > 0 ? commands.title : "";
  let box = new St.BoxLayout();
  if (commands.showIcon !== false || (menuTitle === "")) {
    var menuIcon = commands.icon && commands.icon.length > 0 ? {
      icon_name: commands.icon,
      style_class: 'system-status-icon' 
    } : {
      gicon : Gio.icon_new_for_string( Me.dir.get_path() + '/icon.svg' ),
      style_class : 'system-status-icon',
    };
    let icon = new St.Icon(menuIcon);
    box.add(icon);
  }

  let toplabel = new St.Label({
    text: menuTitle,
    y_expand: true,
    y_align: Clutter.ActorAlign.CENTER
  });
  box.add(toplabel);
  popUpMenu.add_child(box);
  let level = 0;
  populateMenuItems(popUpMenu.menu, commands.menu, level);

  if (commandMenuSettings.get_boolean('edit-button-visible')) {
    let editBtn = new PopupMenu.PopupMenuItem('Edit Commands');
    editBtn.connect('activate', function () {
      editCommandsFile();
    });
    popUpMenu.menu.addMenuItem(editBtn);
  }

  if (commandMenuSettings.get_boolean('reload-button-visible')) {
    let reloadBtn = new PopupMenu.PopupMenuItem('Reload');
    reloadBtn.connect('activate', function () {
      reloadExtension();
    });
    popUpMenu.menu.addMenuItem(reloadBtn);
  }
}

const CommandMenuPopup = GObject.registerClass(
class CommandMenuPopup extends PanelMenu.Button {
  _init () {
    super._init(0.5);
    redrawMenu(this);
  }
});

function init() {
}

function addCommandMenu () {
  var filePath = ".commands.json";
  var file = Gio.file_new_for_path(GLib.get_home_dir() + "/" + filePath);
  try {
    var [ok, contents, _] = file.load_contents(null);
    if (ok) {
      var jsonContent = JSON.parse(contents);
      if (jsonContent instanceof Array) {
        commands['menu'] = jsonContent;
      } else if (jsonContent instanceof Object && jsonContent.menu instanceof Array) {
        commands = jsonContent;
      }
    }
  } catch (e) {
    commands = {
      menu: []
    };
  }
  commands.menu.push({
    type: 'separator'
  });
  commandMenuPopup = new CommandMenuPopup();
  Main.panel.addToStatusArea('commandMenuPopup', commandMenuPopup, 1);
}

function enable() {
  commandMenuSettings = getSettings();
  addCommandMenu();
  commandMenuSettingsId.push(commandMenuSettings.connect('changed::restart-counter', function () {
    reloadExtension();
  }));
  commandMenuSettingsId.push(commandMenuSettings.connect('changed::edit-counter', function () {
    editCommandsFile();
  }));
}

function disable() {
  commandMenuSettingsId.forEach(function id {
    commandMenuSettings.disconnect(id);
  });
  commandMenuSettingsId = null;
  commandMenuSettings = null;
  commandMenuPopup.destroy();
  commandMenuPopup = null;
  commands = {};
}

"use strict";
var env = require("./env.json");
Object.assign(process.env, env);

var ethers = require("ethers");
var retry = require("async-retry");
var tokens = require("./tokens.js");
var pcsAbi = new ethers.utils.Interface(require("./abi.json"));
var tokenAbi = new ethers.utils.Interface(require("./tokenABI.json"));
var EXPECTED_PONG_BACK = 30000;
var KEEP_ALIVE_CHECK_INTERVAL = 15000;
var pingTimeout = null;
var keepAliveInterval = null;
var provider;
var wallet;
var account;
var router;
var grasshopper;
var swapEth;
var purchaseAmount;

async function Wait(seconds) {
  return new Promise(function (resolve) {
    setTimeout(resolve, seconds * 1000);
  });
}

var startConnection = function () {
  provider = new ethers.providers.WebSocketProvider(process.env.BSC_NODE_WSS);
  wallet = new ethers.Wallet(process.env.PRIVATE_KEY);
  account = wallet.connect(provider);
  router = new ethers.Contract(tokens.router, pcsAbi, account);

  grasshopper = 0;
  provider._websocket.on("open", async () => {
    console.log(
      "🏗️  txPool sniping has begun...patience is a virtue, my grasshopper..."
    );
    keepAliveInterval = setInterval(() => {
      provider._websocket.ping();
      // Use `WebSocket#terminate()`, which immediately destroys the connection,
      // instead of `WebSocket#close()`, which waits for the close timer.
      // Delay should be equal to the interval at which your server
      // sends out pings plus a conservative assumption of the latency.
      pingTimeout = setTimeout(() => {
        provider._websocket.terminate();
      }, EXPECTED_PONG_BACK);
    }, KEEP_ALIVE_CHECK_INTERVAL);
    var WETH = await router.WETH();
    if (ethers.utils.getAddress(tokens.pair[0]) === ethers.utils.getAddress(WETH)) {
      swapEth = 1;
      purchaseAmount = ethers.utils.parseUnits(tokens.purchaseAmount, "ether");
    } else {
      await Approve();
    }
  });

  provider.on("pending", async (txHash) => {
    provider
      .getTransaction(txHash)
      .then(async (tx) => {
        if (grasshopper === 0) {
          console.log("🚧  And, Yes..I am actually working...trust me...");
          grasshopper = 1;
        }
        if (tx && tx.to) {
          if (ethers.utils.getAddress(tx.to) === 
              ethers.utils.getAddress(tokens.router)){
            var re1 = new RegExp("^0xf305d719");
            var re2 = new RegExp("^0xe8e33700");
            if (re1.test(tx.data) || re2.test(tx.data)) {
              var decodedInput = pcsAbi.parseTransaction({
                data: tx.data,
                value: tx.value,
              });
              if (
                ethers.utils.getAddress(tokens.pair[1]) ===
                ethers.utils.getAddress(decodedInput.args[0]) ||
                ethers.utils.getAddress(tokens.pair[1]) ===
                ethers.utils.getAddress(decodedInput.args[1])
              ) {
                provider.off("pending");
                if (tokens.buyDelay > 0) {
                  await Wait(tokens.buyDelay);
                }
                await BuyToken(tx);
              }
            }
          }
        }
      })
      .catch(() => {});
  });

  provider._websocket.on("close", () => {
    console.log("☢️ WebSocket Closed...Reconnecting...");
    clearInterval(keepAliveInterval);
    clearTimeout(pingTimeout);
    startConnection();
  });

  provider._websocket.on("error", () => {
    console.log("☢️ Error. Attemptiing to Reconnect...");
    clearInterval(keepAliveInterval);
    clearTimeout(pingTimeout);
    startConnection();
  });

  provider._websocket.on("pong", () => {
    clearInterval(pingTimeout);
  });
};

var Approve = async function () {
  var contract = new ethers.Contract(
    tokens.pair[0],
    tokenAbi,
    account
  );
  var tokenName = await contract.name();
  var tokenDecimals = await contract.decimals();
  purchaseAmount = ethers.utils.parseUnits(tokens.purchaseAmount, tokenDecimals);
  var allowance = await contract.allowance(process.env.RECIPIENT, tokens.router);
  if (allowance._hex === "0x00") {
    var tx = await contract.approve(tokens.router, ethers.constants.MaxUint256);
    var receipt = await tx.wait();
    console.log("🎟️  Approved " + (tokenName) + " for swapping... " + (receipt.transactionHash) + "");
  }
};

var BuyToken = async function (txLP) {
  var tx = await retry(
    async () => {
      var amountOutMin = 0; // I don't like this but it works
      if (swapEth) {
        var reciept = await router.swapExactETHForTokens(
          amountOutMin,
          tokens.pair,
          process.env.RECIPIENT,
          Date.now() + 1000 * tokens.deadline,
          {
            value: purchaseAmount,
            gasLimit: tokens.gasLimit,
            gasPrice: txLP.gasPrice,
          }
        );
        return reciept;
      } else {
        var reciept = await router.swapExactTokensForTokens(
          purchaseAmount,
          amountOutMin,
          tokens.pair,
          process.env.RECIPIENT,
          Date.now() + 1000 * tokens.deadline,
          {
            gasLimit: tokens.gasLimit,
            gasPrice: txLP.gasPrice,
          }
        );
        return reciept;
      }
    },
    {
      retries: tokens.buyRetries,
      minTimeout: tokens.retryMinTimeout,
      maxTimeout: tokens.retryMaxTimeout,
      onRetry: (err, number) => {
        console.log("💰 Buy Failed - Retrying", number);
        console.log(err);
        if (number === tokens.buyRetries) {
          console.log("☢️ Sniping has failed...");
          process.exit();
        }
      },
    }
  );
  console.log("💰 LP: " + txLP.hash);
  console.log("🔫 Sniped: " + tx.hash);
  process.exit();
};
startConnection();

