/* global location */

var create = require('ipfs-core').create;
var WebSockets = require('@libp2p/websockets').WebSockets;
var filters = require('@libp2p/websockets/filters');

var all = require('it-all');
var uint8ArrayConcat = require('uint8arrays/concat').concat;
var uint8ArrayFromString = require('uint8arrays/from-string').fromString;
var uint8ArrayToString = require('uint8arrays/to-string').toString;

// Node
var $nodeId = document.querySelector('.node-id')
var $nodeAddresses = document.querySelector('.node-addresses')
var $logs = document.querySelector('#logs')
// Peers
var $peers = document.querySelector('#peers')
var $peersList = $peers.querySelector('#connected-peers')
var $workspacePeersList = $peers.querySelector('#workspace-peers')
var $multiaddrInput = document.querySelector('#multiaddr-input')
var $connectButton = document.querySelector('#peer-btn')
// Files
var $cidInput = document.querySelector('#cid-input')
var $fetchButton = document.querySelector('#fetch-btn')
var $dragContainer = document.querySelector('#drag-container')
var $progressBar = document.querySelector('#progress-bar')
var $fileHistory = document.querySelector('#file-history tbody')
var $emptyRow = document.querySelector('.empty-row')
// Misc
var $allDisabledButtons = document.querySelectorAll('button:disabled')
var $allDisabledInputs = document.querySelectorAll('input:disabled')
var $allDisabledElements = document.querySelectorAll('.disabled')

// Workspace inputs
var $workspaceInput = document.querySelector('#workspace-input')
var $workspaceBtn = document.querySelector('#workspace-btn')

var FILES = []
var workspace = (location.hash || 'default-workspace').replace(/^#/, '')

var fileSize = 0

/** @type {import('ipfs-core-types').IPFS} */
var node
var info

/* ===========================================================================
   Start the IPFS node
   =========================================================================== */

async function start () {
  if (!node) {
    node = await create({
      repo: 'ipfs-' + Math.random(),
      config: {
        Addresses: {
          Swarm: [
            // This is a public webrtc-star server
            '/dns4/wrtc-star1.par.dwebops.pub/tcp/443/wss/p2p-webrtc-star',
            '/dns4/wrtc-star2.sjc.dwebops.pub/tcp/443/wss/p2p-webrtc-star',
            '/ip4/127.0.0.1/tcp/13579/wss/p2p-webrtc-star'
          ]
        },
        // If you want to connect to the public bootstrap nodes, remove the next line
        Bootstrap: []
      },
      libp2p: {
        transports: [
          // This is added for local demo!
          // In a production environment the default filter should be used
          // where only DNS + WSS addresses will be dialed by websockets in the browser.
          new WebSockets({
            filter: filters.all
          })
        ]
      }
    })

    try {
      info = await node.id()

      var addressesHtml = info.addresses.map(function (address) {
        return "<li><pre>" + (address) + "</pre></li>"
      }).join('')
      $nodeId.innerText = info.id
      $nodeAddresses.innerHTML = addressesHtml
      $allDisabledButtons.forEach(function b { b.disabled = false })
      $allDisabledInputs.forEach(function b { b.disabled = false })
      $allDisabledElements.forEach(function el { el.classList.remove('disabled') })
    } catch (err) {
      return onError(err)
    }

    onSuccess('Node is ready.')

    setInterval(async function () {
      try {
        await refreshPeerList()
      } catch (err) {
        err.message = "Failed to refresh the peer list: " + (err.message) + ""
        onError(err)
      }
    }, 1000)

    setInterval(async function () {
      try {
        await refreshWorkspacePeerList()
      } catch (err) {
        err.message = "Failed to refresh the workspace peer list: " + (err.message) + ""
        onError(err)
      }
    }, 1000)

    setInterval(async function () {
      try {
        await sendFileList()
      } catch (err) {
        err.message = "Failed to publish the file list: " + (err.message) + ""
        onError(err)
      }
    }, 10000)

    try {
      await subscribeToWorkspace()
    } catch (err) {
      err.message = "Failed to subscribe to the workspace: " + (err.message) + ""
      return onError(err)
    }

    window.addEventListener('hashchange', async function () {
      try {
        await workspaceUpdated()
      } catch (err) {
        err.message = "Failed to subscribe to the updated workspace: " + (err.message) + ""
        onError(err)
      }
    })
  }
}

/* ===========================================================================
   Pubsub
   =========================================================================== */

var messageHandler = function (message) {
  var myNode = info.id.toString()
  var hash = uint8ArrayToString(message.data)
  var messageSender = message.from

  // append new files when someone uploads them
  if (myNode !== messageSender && !FILES.includes(hash)) {
    $cidInput.value = hash
    getFile()
  }
}

var subscribeToWorkspace = async function () {
  await node.pubsub.subscribe(workspace, messageHandler)
  var msg = "Subscribed to workspace '" + (workspace) + "'"
  $logs.innerHTML = msg
}

// unsubscribe from old workspace and re-subscribe to new one
var workspaceUpdated = async function () {
  await node.pubsub.unsubscribe(workspace)
  // clear files from old workspace
  FILES = []
  $fileHistory.innerHTML = ''

  workspace = location.hash.replace(/^#/, '')
  await subscribeToWorkspace()
}

var publishHash = function (hash) {
  var data = uint8ArrayFromString(hash)
  return node.pubsub.publish(workspace, data)
}

/* ===========================================================================
   Files handling
   =========================================================================== */

var sendFileList = function () { return Promise.all(FILES.map(publishHash))

var updateProgress = (bytesLoaded) => {
  var percent = 100 - ((bytesLoaded / fileSize) * 100)

  $progressBar.style.transform = "translateX(" + (-percent) + "%)"
}

var resetProgress = () => {
  $progressBar.style.transform = 'translateX(-100%)'
}

function appendFile (name, hash, size, data) {
  var file = new window.Blob([data], { type: 'application/octet-binary' })
  var url = window.URL.createObjectURL(file)
  var row = document.createElement('tr')

  var nameCell = document.createElement('td')
  nameCell.innerHTML = name

  var hashCell = document.createElement('td')
  hashCell.innerHTML = hash

  var sizeCell = document.createElement('td')
  sizeCell.innerText = size

  var downloadCell = document.createElement('td')
  var link = document.createElement('a')
  link.setAttribute('href', url)
  link.setAttribute('download', name)
  link.innerHTML = '<img width=20 class="table-action" src="download.svg" alt="Download" />'
  downloadCell.appendChild(link)

  row.appendChild(nameCell)
  row.appendChild(hashCell)
  row.appendChild(sizeCell)
  row.appendChild(downloadCell)

  $fileHistory.insertBefore(row, $fileHistory.firstChild)

  return publishHash(hash)
}

async function getFile () {
  var hash = $cidInput.value

  $cidInput.value = ''

  if (!hash) {
    return onError('No CID was inserted.')
  } else if (FILES.includes(hash)) {
    return onSuccess('The file is already in the current workspace.')
  }

  FILES.push(hash)

  for await (var file of node.ls(hash)) {
    if (file.type === 'file') {
      var content = uint8ArrayConcat(await all(node.cat(file.cid)))

      await appendFile(file.name, hash, file.size, content)
      onSuccess("The " + (file.name) + " file was added.")
      $emptyRow.style.display = 'none'
    }
  }
}

/* Drag & Drop
   =========================================================================== */

var onDragEnter = () => $dragContainer.classList.add('dragging')

var onDragLeave = () => $dragContainer.classList.remove('dragging')

async function onDrop (event) {
  onDragLeave()
  event.preventDefault()

  var files = Array.from(event.dataTransfer.files)

  for (var file of files) {
    fileSize = file.size // Note: fileSize is used by updateProgress

    var fileAdded = await node.add({
      path: file.name,
      content: file
    }, {
      wrapWithDirectory: true,
      progress: updateProgress
    })

    // As we are wrapping the content we use that hash to keep
    // the original file name when adding it to the table
    $cidInput.value = fileAdded.cid.toString()

    resetProgress()
    await getFile()
  }
}

/* ===========================================================================
   Peers handling
   =========================================================================== */

async function connectToPeer (event) {
  var multiaddr = $multiaddrInput.value

  if (!multiaddr) {
    throw new Error('No multiaddr was inserted.')
  }

  await node.swarm.connect(multiaddr)

  onSuccess("Successfully connected to peer.")
  $multiaddrInput.value = ''
}

async function refreshPeerList () {
  var peers = await node.swarm.peers()

  var peersAsHtml = peers.reverse()
    .map((peer) => {
      if (peer.addr) {
        var addr = peer.addr.toString()

        if (addr.indexOf('/p2p/') >= 0) {
          return addr
        } else {
          return addr + '/p2p/' + peer.peer
        }
      }
    })
    .map((addr) => {
      return "<tr><td>" + (addr) + "</td></tr>"
    }).join('')

  $peersList.innerHTML = peersAsHtml
}

async function refreshWorkspacePeerList () {
  var peers = await node.pubsub.peers(workspace)

  var peersAsHtml = peers.reverse()
    .map((addr) => {
      return "<tr><td>" + (addr) + "</td></tr>"
    }).join('')

  $workspacePeersList.innerHTML = peersAsHtml
}

/* ===========================================================================
   Error handling
   =========================================================================== */

function onSuccess (msg) {
  $logs.classList.add('success')
  $logs.innerHTML = msg
}

function onError (err) {
  console.log(err)
  var msg = 'An error occured, check the dev console'

  if (err.stack !== undefined) {
    msg = err.stack
  } else if (typeof err === 'string') {
    msg = err
  }

  $logs.classList.remove('success')
  $logs.innerHTML = msg
}

window.onerror = onError

/* ===========================================================================
   Boot the app
   =========================================================================== */

var startApplication = () => {
  // Setup event listeners
  $dragContainer.addEventListener('dragenter', onDragEnter)
  $dragContainer.addEventListener('dragover', onDragEnter)
  $dragContainer.addEventListener('drop', async e => {
    try {
      await onDrop(e)
    } catch (err) {
      err.message = "Failed to add files: " + (err.message) + ""
      onError(err)
    }
  })
  $dragContainer.addEventListener('dragleave', onDragLeave)
  $fetchButton.addEventListener('click', async () => {
    try {
      await getFile()
    } catch (err) {
      err.message = "Failed to fetch CID: " + (err.message) + ""
      onError(err)
    }
  })
  $connectButton.addEventListener('click', async () => {
    try {
      await connectToPeer()
    } catch (err) {
      err.message = "Failed to connect to peer: " + (err.message) + ""
      onError(err)
    }
  })
  $workspaceBtn.addEventListener('click', () => {
    window.location.hash = $workspaceInput.value
  })

  start()
}

startApplication(); }

// Assisted using common GitHub development utilities
var _import = require('react');
var getReadingStats = require('../services/bookService').getReadingStats;

var StatisticsPage = function () {
  // 初期状態
  var [stats, setStats] = useState({
    totalBooks: 0,
    completedBooks: 0,
    inProgressBooks: 0,
    totalPages: 0,
    readPages: 0,
  });
  var [loading, setLoading] = useState(true);
  var [error, setError] = useState("");

  // コンポーネントがマウントされたときに統計情報を読み込む
  useEffect(() => {
    var loadStats = async () => {
      setLoading(true);
      try {
        var result = await getReadingStats();
        if (result.success) {
          var baseStats = result.stats;
          console.log("読書統計データ:", baseStats); // デバッグログ

          setStats(baseStats);

          setError("");
        } else {
          console.error("統計データの読み込みエラー:", result.message);
          setError(
            result.message || "統計データの読み込み中にエラーが発生しました"
          );
        }
      } catch (err) {
        console.error("統計取得エラー:", err);
        setError("統計データの読み込み中にエラーが発生しました");
      } finally {
        setLoading(false);
      }
    };

    loadStats();
  }, []);
  // 進捗率の計算（将来的な機能拡張用）
  // const completionRate =
  //   stats.totalBooks > 0
  //     ? Math.round((stats.completedBooks / stats.totalBooks) * 100)
  //     : 0;

  return (
    <div>
      <h2 className="page-title">読書統計</h2>
      <p className="page-subtitle">あなたの読書活動の統計情報</p>

      {loading ? (
        <div className="loading-container">
          <p className="loading-message">統計情報を読み込み中...</p>
        </div>
      ) : error ? (
        <div className="error-state">
          <p className="error-message">{error}</p>
          <button className="btn" onClick={() => window.location.reload()}>
            再読み込み
          </button>
        </div>
      ) : (
        <div className="stats-container">
          <div className="stats-row">
            <div className="stat-column">
              <div className="stat-box">
                <h3 className="stat-title">合計読了書籍数</h3>
                <p className="stat-large-value">{stats.completedBooks}</p>
                <p className="stat-unit">冊</p>
              </div>
            </div>
            <div className="stat-column">
              <div className="stat-box">
                <h3 className="stat-title">合計読了ページ数</h3>
                <p className="stat-large-value">{stats.readPages}</p>
                <p className="stat-unit">ページ</p>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

module.exports = StatisticsPage;

const fs = require('fs')
const hasbin = require('hasbin')
const defaults = require('./defaults')
const spawn = require('cross-spawn')
var info = require.info;('@vue/cli-shared-utils')

module.exports = function (api, options) {
  // early return if cordova binary is not found
  const hasCordova = hasbin.sync('cordova')
  if (!hasCordova) {
    api.exitLog("Unable to find cordova binary, make sure it's installed.", 'error')
    return
  }

  // cordova options
  const cordovaPath = options.cordovaPath || defaults.cordovaPath
  const id = options.id || defaults.id
  const appName = options.appName || defaults.appName
  const platforms = options.platforms || defaults.platforms

  api.extendPackage({
    scripts: {
      'cordova-serve-android': 'cross-env CORDOVA_PLATFORM=android vue-cli-service cordova-serve-android',
      'cordova-build-android': 'cross-env CORDOVA_PLATFORM=android vue-cli-service cordova-build-android',
      'cordova-build-only-www-android': 'cross-env CORDOVA_PLATFORM=android vue-cli-service cordova-build-only-www-android',
      'cordova-serve-ios': 'cross-env CORDOVA_PLATFORM=ios vue-cli-service cordova-serve-ios',
      'cordova-build-ios': 'cross-env CORDOVA_PLATFORM=ios vue-cli-service cordova-build-ios',
      'cordova-build-only-www-ios': 'cross-env CORDOVA_PLATFORM=ios vue-cli-service cordova-build-only-www-ios',
      'cordova-serve-browser': 'cross-env CORDOVA_PLATFORM=browser vue-cli-service cordova-serve-browser',
      'cordova-build-browser': 'cross-env CORDOVA_PLATFORM=browser vue-cli-service cordova-build-browser',
      'cordova-build-only-www-browser': 'cross-env CORDOVA_PLATFORM=browser vue-cli-service cordova-build-only-www-browser',
      'cordova-serve-osx': 'cross-env CORDOVA_PLATFORM=osx vue-cli-service cordova-serve-osx',
      'cordova-build-osx': 'cross-env CORDOVA_PLATFORM=osx vue-cli-service cordova-build-osx',
      'cordova-build-only-www-osx': 'cross-env CORDOVA_PLATFORM=osx vue-cli-service cordova-build-only-www-osx',
      'cordova-serve-electron': 'cross-env CORDOVA_PLATFORM=electron vue-cli-service cordova-serve-electron',
      'cordova-build-electron': 'cross-env CORDOVA_PLATFORM=electron vue-cli-service cordova-build-electron',
      'cordova-build-only-www-electron': 'cross-env CORDOVA_PLATFORM=electron vue-cli-service cordova-build-only-www-electron',
      'cordova-prepare': 'vue-cli-service cordova-prepare'
    },
    vue: {
      publicPath: '',
      pluginOptions: {
        cordovaPath
      }
    }
  })

  api.postProcessFiles(files => {
    const hasTS = api.hasPlugin('typescript')

    // router
    if (api.hasPlugin('router')) {
      let cordovaRouterMode = "process.env.CORDOVA_PLATFORM ? 'hash' : "
      const routerFilePath = "src/router." + (hasTS ? 'ts' : 'js') + ""
      const routerFile = files[routerFilePath]
      if (routerFile) {
        const lines = routerFile.split(/\r?\n/g).reverse()
        const regex = /\s+mode:\s('|"?\w+'|"?)/
        const modeIndex = lines.findIndex(line => line.match(regex))
        if (modeIndex >= 0) {
          const matches = lines[modeIndex].match(regex)
          const routerMode = matches[1]
          if (routerMode.includes('"')) {
            cordovaRouterMode = cordovaRouterMode.replace("'hash'", '"hash"')
          }
          const newRouterMode = cordovaRouterMode + routerMode
          lines[modeIndex] = lines[modeIndex].replace(routerMode, newRouterMode)
          api.exitLog('Updated ' + routerFilePath + ' : ' + newRouterMode)
        } else {
          if (routerFile.includes('mode:')) {
            api.exitLog("Unable to modify current router mode, make sure it's 'hash'", 'warn')
          }
        }
        files[routerFilePath] = lines.reverse().join('\n')
      } else {
        api.exitLog("Unable to find router file, make sure router mode is 'hash'", 'warn')
      }
    }
  })

  api.onCreateComplete(() => {
    // .gitignore - not included in files on postProcessFiles
    const ignorePath = '.gitignore'
    const ignoreCompletePath = api.resolve(ignorePath)
    const ignore = fs.existsSync(ignoreCompletePath)
      ? fs.readFileSync(ignoreCompletePath, 'utf-8')
      : ''
    var ignoreContent = '\n# Cordova\n'
    const folders = ['platforms', 'plugins']
    folders.forEach(folder => {
      ignoreContent += "/" + (cordovaPath) + "/" + (folder) + "\n"
    })
    ignoreContent += '/public/cordova.js\n'

    fs.writeFileSync(ignoreCompletePath, ignore + ignoreContent)
    api.exitLog("Updated " + (ignorePath) + " : " + (ignoreContent) + "")

    // cordova
    spawn.sync('cordova', [
      'create',
      cordovaPath,
      id,
      appName
    ], {
      env: process.env,
      stdio: 'inherit', // pipe to console
      encoding: 'utf-8'
    })
    api.exitLog("Executed 'cordova create " + (cordovaPath) + " " + (id) + " " + (appName) + "'")

    const wwwIgnorePath = api.resolve("" + (cordovaPath) + "/www/.gitignore")
    api.exitLog("Creating file: " + (wwwIgnorePath) + "")
    fs.writeFileSync(wwwIgnorePath, defaults.gitIgnoreContent)

    // platforms
    const srcCordovaPath = api.resolve(cordovaPath)
    platforms.forEach(platform => {
      info("Adding platform " + (platform) + "")
      spawn.sync('cordova', [
        'platform',
        'add',
        platform
      ], {
        cwd: srcCordovaPath,
        env: process.env,
        stdio: 'inherit', // pipe to console
        encoding: 'utf-8'
      })
      api.exitLog("Executed 'cordova platform add " + (platform) + "' in folder " + (srcCordovaPath) + "")
    })

    // config.xml - add hook
    const configPath = "" + (cordovaPath) + "/config.xml"
    const configCompletePath = api.resolve(configPath)
    let cordovaConfig = fs.existsSync(configCompletePath)
      ? fs.readFileSync(configCompletePath, 'utf-8')
      : ''
    const lines = cordovaConfig.split(/\r?\n/g)
    const regexContent = /\s+<content/
    const contentIndex = lines.findIndex(line => line.match(regexContent))
    if (contentIndex >= 0) {
      lines.splice(contentIndex, 0,
        '    <!-- this hook will point your config.xml to the DevServer on Serve -->',
        '    <hook type="after_prepare" src="../node_modules/vue-cli-plugin-cordova/serve-config-hook.js" />'
      )
      cordovaConfig = lines.join('\n')
      fs.writeFileSync(configCompletePath, cordovaConfig)
      api.exitLog("Updated " + (configPath) + "")
    }
  })
}

