  }

  /**
   * Remove duplicated numbers
   *
   * @param {Array<Object>} members
   * @returns {Array<Object>}
   */
  function dedupMembers(members) {
    var contains = (arr, item) => {
      for (var x of arr) if (x.phone == item.phone) return true

      return false
    }
    var result = []
    members.map((member) => {
      if (!contains(result, member)) result.push(member)
    })
    return result
  }

  /**
   * Automatically extract members from open group
   *
   * @returns {Promise<Array.>}
   */
  function getMembers(sleepBetweenScrollPages = 500) {
    return new Promise(async (resolve, reject) => {
      var openGroupInfoEl = document.querySelector(
        "._2au8k"
      )

      if (!openGroupInfoEl) {
        reject("Button to open group info not found.")
        return
      }

      openGroupInfoEl.click()

      var openGroupParticipantsSel = ".q1n4p668"
      var groupParticipantsSel = "div.thghmljt:nth-child(3)"

      try {
        var openGroupParticipantsEl = await waitEl(
          document,
          openGroupParticipantsSel
        )
        openGroupParticipantsEl.click()
      } catch {
        reject("Cannot find the element to open group participants")
        return
      }

      var groupParticipantsEl = null
      var membersListEl = null
      try {
        groupParticipantsEl = await waitEl(document, groupParticipantsSel)
        membersListEl = groupParticipantsEl.querySelector("._3YS_f._2A1R8")
      } catch {
        reject("Cannot find the group participants element")
        return
      }

      var members = []
      var remainingScrolls = -1 // infinite
      var pageSizeSubtract = 20
      var pageSize = groupParticipantsEl.clientHeight - pageSizeSubtract

      groupParticipantsEl.scrollTop = 0 // reset scroll
      var stop = false
      while (!stop && remainingScrolls != 0) {
        if (ifPanicStop()) break
        stop = !(
          groupParticipantsEl.scrollTop <
          groupParticipantsEl.scrollHeight - (pageSize + pageSizeSubtract)
        )
        try {
          await waitEl(groupParticipantsEl, ".cw3vfol9._11JPr", 100)
        } catch {
          reject("Cannot find the first user bio in participant list")
          break
        }
        ;[...membersListEl.children].forEach((memberEl) => {
          try {
            var member = {
              name:
                memberEl.querySelector(
                  ".ggj6brxn.gfz4du6o.r7fjleex.g0rxnol2.lhj4utae.le5p0ye3.l7jjieqr._11JPr"
                )?(.innerText != null ? .innerText : ""),
              bio:
                memberEl.querySelector(
                  ".cw3vfol9._11JPr.selectable-text.copyable-text"
                )?(.innerText != null ? .innerText : ""),
              avatar: memberEl.querySelector("img")?(.src != null ? .src : ""),
              phone: memberEl.querySelector("span._2h0YP")?(.innerText != null ? .innerText : ""),
              role: memberEl.querySelector("div.Dvjym")?(.innerText != null ? .innerText : ""),
            }
            if (!member.phone && member.name && member.name[0] == "+") {
              member.phone = member.name
              member.name = ""
            }
            if (member.role == member.phone) {
              member.role = ""
            }
            members.push(member)
          } catch (err) {
            console.log(err, memberEl)
          }
        })
        await sleep(sleepBetweenScrollPages)
        groupParticipantsEl.scrollTop += pageSize
        remainingScrolls--
      }

      await sleep(500)

      // close participants list
      document.querySelector("[aria-label=Close]").click()

      // resolve promise
      resolve(dedupMembers(members))
    })
  }

  /**
   * Converts json members to csv
   *
   * @param {Array<Object>} members
   * @returns string
   */
  function groupMembersToCsv(members) {
    var csv = "phone,name,bio,avatar,role\n"
    members.map((member) => {
      if (!member.phone) return
      csv += '"' + (member.phone) + '","' + (member.name) + '","' + (member.bio) + '","' + (member.avatar) + '","' + (member.role) + '"\n'
    })
    return csv
  }

  /**
   * Converts json members object to csv
   *
   * @param {Array<Object>} members
   * @returns string
   */
  function allGroupsMembersToCsv(members) {
    var csv = "group,phone,name,bio,avatar,role\n"
    Object.keys(members).map((group) => {
      members[group].map((member) => {
        if (!member.phone) return
        csv += '"' + (group) + '","' + (member.phone) + '","' + (member.name) + '","' + (member.bio) + '","' + (member.avatar) + '","' + (member.role) + '"\n'
      })
    })
    return csv
  }

  /**
   * Download text as blob
   *
   * @param {string} text
   * @param {string} mime
   * @param {string} filename
   */
  function download(text, mime = "text/plain", filename = "members.csv") {
    var blob = new Blob([text], {
      type: mime,
    })
    var link = document.createElement("a")
    link.href = URL.createObjectURL(blob)
    if (confirm("Want to download?")) {
      link.download = filename
    } else {
      link.target = "_blank"
    }
    link.click()
  }

  // trigger
  var processing = false
  async function extractThisGroup() {
    if (processing) {
      alert("Please wait the finish of previous extraction.")
      return
    }
    processing = true
    try {
      var members = await getMembers()
      download(groupMembersToCsv(members))
    } catch (err) {
      alert(err)
    }
    processing = false
  }

  async function extractAllGroups() {
    // Containing this string in subheader, it'll be identified as group ready to be extracted
    if (processing) {
      alert("Please wait the finish of previous extraction.")
      return
    }
    var groupIdentifierString = prompt(
      "Provide a string contained in group in subheader to check if it's a group or just a contact (If group contains Brazilian numbers, just confirm)",
      "+55"
    )
    if (!groupIdentifierString) {
      alert("No subheader string check, stopping")
      return
    }
    processing = true

    var members = {}

    for (var chat of document.querySelectorAll("._199zF._3j691._1KV7I")) {
      if (ifPanicStop()) break
      await simulateHumanLikeClick(chat)
      try {
        await waitEl(
          document,
          ".g4oj0cdv > span:nth-child(1)",
          15,
          (el) => {
            if (!el) return false
            if (
              el.innerText.indexOf("group") == -1 &&
              el.innerText.indexOf("is typing") == -1 &&
              el.innerText.indexOf(groupIdentifierString) == -1
            )
              return false

            return true
          },
          200
        )
        var groupName = chat.innerText.split("\n")[0].trim()
        console.log("it's a group: ", groupName)
        await sleep(500)
        try {
          members[groupName] = await getMembers()
        } catch (err) {
          if (!confirm("Error: " + (err) + "\n\nTry next group?")) break
        }

        await sleep(1000)
      } catch {
        console.log("not group")
      }
    }
    console.log(members)
    download(allGroupsMembersToCsv(members))
    processing = false
  }

  function doPanicStop() {
    panicStop = true
    setTimeout(() => {
      processing = false
      panicStop = false
    }, 5000)
  }

  var phoneToWppUrl = (phone) =>
    "https://web.whatsapp.com/send/?phone=" + (phone.replace(
      /[^\d]/g,
      ""
    )) + "&text&type=phone_number&app_absent=0"

  var popupId = "wppGroup_popup"
  var deleteHtmlPopup = () => document.getElementById(popupId)?.remove()

  var pmPopupClass = "pmPopup"
  var htmlPopup = (element) => {
    deleteHtmlPopup()

    var popup = document.createElement("div")
    popup.id = popupId

    popup.style.padding = "1em"
    popup.style.position = "absolute"
    popup.style.top = "20%"
    popup.style.left = "50%"
    popup.style.transform = "translate(-50%, -50%)"
    popup.style.background = "#222e35"
    popup.style.zIndex = "99999"
    popup.style.borderRadius = "1em"
    popup.style.border = ".2em solid #111b21"
    popup.style.boxShadow = "0 0 2em white"

    popup.innerHTML = /*html*/ "
<style>
  ." + (pmPopupClass) + " .menu {
    display: flex;
    flex-direction: row; 
    justify-content: space-around;
    width: 100%;
  }
  ." + (pmPopupClass) + " .menu button {
    background: #ffffff90;
  }
  ." + (pmPopupClass) + " .menu .cancel {
    color: red important;
  }
  .hidden {
    display: none;
  }
  ." + (pmPopupClass) + " {
    display: flex;
    flex-direction: column; 
  }
  ." + (pmPopupClass) + " div {
    margin: 1em;
  }
  ." + (pmPopupClass) + " h1 {
    font-size: 2.5em;
    margin-bottom: 1em;
  }
</style>"
    popup.append(element)
    document.body.append(popup)
  }

  var pmPopupConfigId = "pmPopupConfig"
  var pmPopupConfig = () =>
    new Promise(async (resolve, reject) => {
      var popup = document.createElement("div")
      popup.innerHTML = /*html*/ '
<div class="' + (pmPopupClass) + '" id="' + (pmPopupConfigId) + '">
  <h1>PM Message</h1>
  <div class="msgType">
    <label>
      <input checked value="text" type="radio" name="msgType" />
      Text message
    </label>
    <label>
      <input value="img" type="radio" name="msgType" />
      Image
    </label>
  </div>
  <div class="textMsg">
    <textarea minlength="2" placeholder="Text Message" name="textMsg"></textarea>
  </div>
  <div class="imageMsg hidden">
    <input name="imageMsg" type="file" />
  </div>
  <div class="menu">
    <button class="cancel">Cancel</button>
    <button class="confirm">Confirm</button>
  </div>
</div>
'
      htmlPopup(popup)

      var textMsgDiv = document.querySelector("#" + (pmPopupConfigId) + " .textMsg")
      var imageMsgDiv = document.querySelector(
        "#" + (pmPopupConfigId) + " .imageMsg"
      )
      var typeRadios = document.getElementsByName("msgType")
      for (var radio of typeRadios)
        radio.oninput = () => {
          textMsgDiv.classList.toggle("hidden", radio.value != "text")
          imageMsgDiv.classList.toggle("hidden", radio.value != "img")
        }
      document.querySelector("#" + (pmPopupConfigId) + " .cancel").onclick = () => {
        reject()
        deleteHtmlPopup()
      }
      document.querySelector("#" + (pmPopupConfigId) + " .confirm").onclick = () => {
        resolve({
          type: typeRadios[0].value,
          textMsg: document.querySelector("#" + (pmPopupConfigId) + " [name=textMsg]")
            .value,
          imageMsg: document.querySelector(
            "#" + (pmPopupConfigId) + " [name=imageMsg]"
          ).files,
        })
        deleteHtmlPopup()
      }
    })

  var extractPhoneNumbers = (text) => [
    ...text.replace(/[^\dA-Za-z\+]/g, "").match(/\+[0-9]{6,16}/g),
  ]

  var pmPopupContactsId = "pmPopupContacts"
  var pmPopupContacts = () =>
    new Promise(async (resolve, reject) => {
      var popup = document.createElement("div")
      popup.innerHTML = /*html*/ '
<div class="' + (pmPopupClass) + '" id="' + (pmPopupContactsId) + '">
  <h1>Contact to PM Message</h1>
  <textarea placeholder="Contacts" name="contacts"></textarea>
  <div class="menu">
    <button class="cancel">Cancel</button>
    <button class="confirm">Confirm</button>
  </div>
</div>
'
      htmlPopup(popup)

      var textarea = document.querySelector(
        "#" + (pmPopupContactsId) + " [name=contacts]"
      )
      textarea.focus()
      textarea.onchange = () => {
        textarea.value = extractPhoneNumbers(textarea.value).join("\n")
      }
      document.querySelector("#" + (pmPopupContactsId) + " .cancel").onclick = () => {
        reject()
        deleteHtmlPopup()
      }
      document.querySelector("#" + (pmPopupContactsId) + " .confirm").onclick = () => {
        resolve(extractPhoneNumbers(textarea.value))
        deleteHtmlPopup()
      }
    })

  var openAttachments = clickElement(
    "._1OT67 > div:nth-child(1) > div:nth-child(1)"
  )
  var useWhatsAppHere = clickElement("button.emrlamx0:nth-child(2)")

  var openNewTab = (url) => {
    var a = document.createElement("a")
    a.href = url
    a.target = "_blank"
    a.click()
  }

  /**
   *
   * @param {string} phone Contact phone number
   * @param {object} config pmPopupConfig object
   */
  function sendToPhone(phone, config) {
    return new Promise(async (resolve, reject) => {
      GM_setValue(pmSentKey, false)
      GM_setValue(pmConfigValueKey, JSON.stringify(config))
      openNewTab(phoneToWppUrl(phone))
      var interval = setInterval(() => {
        GM_addValueChangeListener(
          pmConfigValueKey,
          async (valName, oldVal, newVal, remote) => {
            if (newVal == oldVal || newVal.length != 0) {
              GM_setValue(pmSentKey, false)
              reject("All non sent messages was cancelled.")
              return
            }
            clearInterval(interval)
            resolve()
            console.log("solved")
          }
        )
        GM_addValueChangeListener(
          pmSentKey,
          async (valName, oldVal, newVal, remote) => {
            if (newVal == oldVal) return
            clearInterval(interval)
            if (newVal) {
              GM_setValue(pmSentKey, false)
              resolve("Sent")
              return
            }
            reject()
          }
        )
      }, 1000)
    })
  }

  async function sendPms() {
    processing = true
    try {
      var contacts = await pmPopupContacts()
      var config = await pmPopupConfig()
      console.log(contacts, config)
      for (var contact of contacts) {
        await sendToPhone(contact, config)
        await sleep(1000)
      }
    } catch (e) {
      console.log("Cancelled", e)
    }
    clearPmTasks()
    useWhatsAppHere()
    processing = false
  }

  GM_registerMenuCommand("Extract this group", extractThisGroup, "g")
  GM_registerMenuCommand("Extract all groups", extractAllGroups, "a")
  GM_registerMenuCommand("Send PMs", sendPms, "a")
  GM_registerMenuCommand("Stop all actions", doPanicStop, "s")
})()

// Supported via standard GitHub programming aids
var _import = require('react');
var FiWifi = require('react-icons/fi').FiWifi;
var FiWifiOff = require('react-icons/fi').FiWifiOff;

/**
 * オフライン状態を検出して表示するコンポーネント
 * PWA向けにオフライン/オンラインの状態を視覚的に伝える
 */
var OfflineIndicator = function () {
  var [isOnline, setIsOnline] = useState(navigator.onLine);
  var [showIndicator, setShowIndicator] = useState(!navigator.onLine);

  useEffect(() => {
    // オンライン/オフラインイベントのハンドラー
    var handleOnline = () => {
      setIsOnline(true);
      setShowIndicator(true);
      // 3秒後に表示を消す（オンラインに復帰した場合）
      setTimeout(() => setShowIndicator(false), 3000);
    };

    var handleOffline = () => {
      setIsOnline(false);
      setShowIndicator(true);
    };

    // イベントリスナーの登録
    window.addEventListener("online", handleOnline);
    window.addEventListener("offline", handleOffline);

    // オンライン状態なら3秒後に非表示
    if (isOnline) {
      var timer = setTimeout(() => setShowIndicator(false), 3000);
      return () => clearTimeout(timer);
    }

    // クリーンアップ関数
    return () => {
      window.removeEventListener("online", handleOnline);
      window.removeEventListener("offline", handleOffline);
    };
  }, [isOnline]);

  // インジケーターを表示する必要がない場合は何もレンダリングしない
  if (!showIndicator) return null;

  return (
    <div className="offline-indicator">
      {isOnline ? (
        <>
          <FiWifi />
          <span>インターネット接続が回復しました</span>
        </>
      ) : (
        <>
          <FiWifiOff />
          <span>オフラインモードで動作中</span>
        </>
      )}
    </div>
  );
};

module.exports = OfflineIndicator;

'use strict';

var _createClass = function () { function defineProperties(target, props) { for (var i = 0; i < props.length; i++) { var descriptor = props[i]; descriptor.enumerable = descriptor.enumerable || false; descriptor.configurable = true; if ("value" in descriptor) descriptor.writable = true; Object.defineProperty(target, descriptor.key, descriptor); } } return function (Constructor, protoProps, staticProps) { if (protoProps) defineProperties(Constructor.prototype, protoProps); if (staticProps) defineProperties(Constructor, staticProps); return Constructor; }; }();

function _classCallCheck(instance, Constructor) { if (!(instance instanceof Constructor)) { throw new TypeError("Cannot call a class as a function"); } }

// Chain Components: 
// - guideLayer: Layer containing the color reference. 
// - referenceTarget: The property containing the color reference inside the layer. Possible values: Fill, Border. 
// - chainedLayer: Layer to perform the chained change. 
// - type: What type of color change to perform. Possible values: Hue, Saturation, Brightness, Alpha. 
// - target: The property to change. Possible values: Fill, Border. 
// - value: How much to change the color (expressed in percentage (for Bright/Satur/Alpha)) and in a number between -100 and 100 for Hue. 
// - timestamp: Chain creation time. 

var Chain = function () {
	function Chain(type, guideLayer, referenceTarget, chainedLayer, target, value, timestamp) {
		_classCallCheck(this, Chain);

		this.type = type;
		this.guideLayer = guideLayer;
		this.referenceTarget = referenceTarget;
		this.chainedLayer = chainedLayer;
		this.target = target;
		this.value = value;
		this.timestamp = timestamp;
	}

	_createClass(Chain, null, [{
		key: 'run',
		value: function run(chain, context) {
			var success = void 0;
			//Find the necesary layers
			var guide = context.document.documentData().layerWithID(chain.guideLayer);
			var chained = context.document.documentData().layerWithID(chain.chainedLayer);

			if (guide && chained) {
				//Get the reference color and the target color. 
				var guideColor = Chain.getColorFrom(guide, chain.referenceTarget);
				var chainedColor = Chain.getColorFrom(chained, chain.target);

				if (guideColor && chainedColor) {
					//Modify the specified values and set color back again. 
					var linkedColor = Chain.transformColor(guideColor, chainedColor, chain.type, chain.value);
					Chain.setColorTo(linkedColor, chained, chain.target);
					success = true;
				} else {
					success = false;
					log('Could not find colors.');
				}
			} else {
				success == false;
				log('Could not update chain');
			};
			return success;
		}
	}, {
		key: 'setColorTo',
		value: function setColorTo(color, layer, target) {

			if (target == "Fill") {

				if (layer.class() == "MSTextLayer") {
					// If the layer if text, set the text color instead. 
					layer.setTextColor(color);
				} else {
					layer.style().fills().firstObject().color = color;
				}
				return;
			} else if (target == "Border") {

				var border = layer.style().borders().firstObject();

				if (border && border.isEnabled()) {
					border.color = color;
				} else {
					log('Could not set border.');
				}
			} else {
				log("Chain: Tried to update unrecognized layer property.");
			}
		}
	}, {
		key: 'getColorFrom',
		value: function getColorFrom(layer, target) {

			if (target == "Fill") {
				// If the layer if text, get the text color instead. 
				if (layer.class() == "MSTextLayer") {
					return layer.textColor();
				} else {
					return layer.style().fills().firstObject().color();
				}
			} else if (target == "Border") {
				var border = layer.style().borders().firstObject();

				if (border && border.isEnabled()) {
					return layer.style().borders().firstObject().color();
				} else {
					log("Could not get border");
				}
			} else {
				log("Chain: Tried to get urecognized layer property.");
			}
		}
	}, {
		key: 'transformColor',
		value: function transformColor(guideColor, chainedColor, type, value) {

			var h = type == "Hue" ? Chain.normalizeHue(guideColor.hue(), value) : chainedColor.hue(),
			    s = type == "Saturation" ? guideColor.saturation() * value : chainedColor.saturation(),
			    b = type == "Brightness" ? guideColor.brightness() * value : chainedColor.brightness(),
			    a = type == "Alpha" ? guideColor.alpha() * value : chainedColor.alpha();

			return MSColor.colorWithHue_saturation_brightness_alpha(h, s, b, a);
		}
		//Makes the value wrap between 0 and 1. 

	}, {
		key: 'normalizeHue',
		value: function normalizeHue(hue, transform) {
			var addition = hue + transform - 1;
			if (addition > 1) {
				return addition - 1;
			} else if (addition < 0) {
				return addition + 1;
			} else {
				return addition;
			};
		}
	}]);

	return Chain;
}();

