// ---------------------------------------------------------------------------
// PatternControler Calss
// ---------------------------------------------------------------------------

function PatternControler()
{
    this.x = 0;
    this.y = 0;
    this.w = 0;
    this.h = 0;
    this.colors = ['#FFFFFF', '#000000'];
    this.angle = 0;
    this.patternFunction = null;
    this.renderTarget = null;
}

// ---------------------------------------------------------------------------

/*
Function to change the amount of pattern rotation.
Use patternAngle() to check current angle.
*/
PatternControler.prototype.patternAngle = function(_angle)
{
    if(typeof(_angle) === 'number') this.angle = _angle;
    return this.angle;
}


/*
Function to set the drawing function.
*/
PatternControler.prototype.setPatternFunction = function(_func)
{
    if(typeof(_func) !== 'function')return false;
    this.patternFunction = _func;
    return this.patternFunction;
};


/**
 * Function to set parameters and draw pattern.
 * @param {Number} _x   x-coordinate of the corner of pattern 
 * @param {Number} _y   y-coordinate of the corner of pattern 
 * @param {Number} _w   width of the pattern
 * @param {Number} _h   height of the pattern
 * @param {} _renderTarget 
 */
PatternControler.prototype.applyPattern = function(_x, _y, _w, _h, _renderTarget)
{
    this._setPatternArea(_x, _y, _w, _h);
    this._setRenderTarget(_renderTarget);
    this.renderTarget = _renderTarget;
    this._drawPattern();
}

/**
 * Function to set the color palette of the pattern.
 * Use patternColors() to check current palette.
 * @param {Array} _colsArr 
 */
PatternControler.prototype.patternColors = function(_colsArr)
{
if(Array.isArray(_colsArr))this.colors = _colsArr;
//return this.colors;
return this.colors.slice(0, this.colors.length);
}



// ---------------------------------------------------------------------------
//Private functions

/*
Function to change the drawing range of a pattern
*/
PatternControler.prototype._setPatternArea = function(_x, _y, _w, _h)
{
    this.x = _x;
    this.y = _y;
    this.w = _w;
    this.h = _h;
};

/*
Function to set the pattern target.
*/
PatternControler.prototype._setRenderTarget = function(_renderTarget)
{
    this.renderTarget = _renderTarget;
};

/*
Function to draw the pattern.
*/
PatternControler.prototype._drawPattern = function()
{
    var rt = this.renderTarget;

    //Generate a drawing function. apply rotation
    var func = typeof(this.patternFunction) === 'function' ?
    this.patternFunction : this._flatFill();

    var rotatedFunc = this._rotatedFuncGen(func, this.angle);

    //cache renderMode
    var pRectMode = rt._renderer._rectMode;
    var pEllipseMode = rt._renderer._ellipseMode;

    //draw
    rt.push();
    rt.drawingContext.clip();
    rt.translate(this.x, this.y);
    rotatedFunc(this.w, this.h, rt);
    rt.pop();

    //reset renderMode
    rt.rectMode(pRectMode);
    rt.ellipseMode(pEllipseMode);
};

/*
Generate a drawing function with rotation applied.
*/
PatternControler.prototype._rotatedFuncGen = function(_ptnFunc, _angle)
{
    var func = function(_w, _h, _rt)
    {
        //Calculate the new size according to the rotation angle.
        var p1 = _rt.createVector(-_w/2, _h/2).rotate(_angle);
        var p2 = _rt.createVector(_w/2, _h/2).rotate(_angle);
        var nw = Math.max(Math.abs(p1.x), Math.abs(p2.x)) * 2;
        var nh = Math.max(Math.abs(p1.y), Math.abs(p2.y)) * 2;

        _rt.push();
        _rt.translate(_w / 2, _h / 2);
        _rt.rotate(_angle);
        _rt.translate(-nw / 2, -nh / 2);
        _ptnFunc(nw, nh, _rt);
        _rt.pop();
    }

    return func;
};

/*
Default pattern function. 
*/
PatternControler.prototype._flatFill = function()
{
    var c = this.patternColors();

    return function(_w, _h, _rt)
    {
        _rt.rectMode(_rt.CORNER);
        _rt.fill(c[0]);
        _rt.noStroke();
        _rt.rect(0, 0, _w, _h);
    }
};



// ---------------------------------------------------------------------------
// Vertex Infomation Class
// ---------------------------------------------------------------------------

function PatternVertexInfo()
{
    this.verticies = [];
    this.isCurve = false;
    this.curveAreaMult = 1.25;
}

// ---------------------------------------------------------------------------

PatternVertexInfo.prototype.reset = function()
{
    this.verticies = [];
    this.isCurve = false;
};

PatternVertexInfo.prototype.addVertex = function(x, y)
{
    this.verticies.push([x, y]);
};

PatternVertexInfo.prototype.addCurveVertex = function(x, y)
{
    this.addVertex(x, y);
    this.isCurve = true;
};

PatternVertexInfo.prototype.addBezierVertex = function(x2, y2, x3, y3, x4, y4)
{
    this.addVertex(x2, y2);
    this.addVertex(x3, y3);
    this.addVertex(x4, y4);
};

PatternVertexInfo.prototype.addQuadraticVertex = function(cx, cy, x3, y3)
{
    this.addVertex(cx, cy);
    this.addVertex(x3, y3);
};

PatternVertexInfo.prototype.culclateArea = function()
{
    var minx = this.verticies[0][0];
    var maxx = minx;
    var miny = this.verticies[0][1];
    var maxy = miny;

    for(var i = 0; i < this.verticies.length; i++)
    {
       var nx =  this.verticies[i][0];
       var ny =  this.verticies[i][1];

       minx = Math.min(minx, nx);
       maxx = Math.max(maxx, nx);
       miny = Math.min(miny, ny);
       maxy = Math.max(maxy, ny);
    }

    var w = maxx - minx;
    var h = maxy - miny;
    var cx = w / 2 + minx;
    var cy = h / 2 + miny;

    if(this.isCurve)
    {
        w *= this.curveAreaMult;
        h *= this.curveAreaMult;
    }

    var x = cx - w /2;
    var y = cy - h /2;

    var area = {x : x, y : y, w : w, h : h};

    return area;
};



// ---------------------------------------------------------------------------
// p5 extentions
// ---------------------------------------------------------------------------


p5.prototype._patternControler = new PatternControler(); 
p5.Graphics.prototype._patternControler = new PatternControler();

p5.prototype._patternVertexInfo = new PatternVertexInfo();
p5.Graphics.prototype._patternVertexInfo = new PatternVertexInfo();


/**
 * Function to change the amount of pattern rotation.
 * Use patternAngle() to check current angle.
 * @param {Number} _angle  the angle of rotation, 
 * specified in radians or degrees, depending on current angleMode
 */
p5.prototype.patternAngle = function(_angle)
{
    return this._patternControler.patternAngle(_angle);
};


/**
 * Function to set the color palette of the pattern.
 * Use patternColors() to check current palette.
 * @param {Array} _colsArr 
 */
p5.prototype.patternColors = function(_colsArr)
{
    return this._patternControler.patternColors(_colsArr);
};


/**
 * Function to set the pattern
 * @param  {function} _func     Pattern drawing function.
 */
p5.prototype.pattern = function(_func)
{
    return this._patternControler.setPatternFunction(_func);
};


// ---------------------------------------------------------------------------
//Shape functions

(function()
{
    /*
    Functions to adjust coordinate data
    */
    var _modeAdjust = function(a, b, c, d, mode)
    {
        if (mode === p5.prototype.CORNER) {
        return { x: a, y: b, w: c, h: d };
        } else if (mode === p5.prototype.CORNERS) {
        return { x: a, y: b, w: c - a, h: d - b };
        } else if (mode === p5.prototype.RADIUS) {
        return { x: a - c, y: b - d, w: 2 * c, h: 2 * d };
        } else if (mode === p5.prototype.CENTER) {
        return { x: a - c * 0.5, y: b - d * 0.5, w: c, h: d };
        }
    };

    /*
    Function to disable drawing of fills and stroke.
    */
    var _disableColor = function(_renderTarget)
    {
        _renderTarget.noStroke();
        _renderTarget.fill(255, 0);
    };


    // ---------------------------------------------------------------------------

    //rect
    p5.prototype.rectPattern = function(...args)
    {
        _disableColor(this);
        var r = this.rect(...args);

        var val = _modeAdjust(
            arguments[0],
            arguments[1],
            arguments[2],
            arguments[3],
            this._renderer._rectMode
        );

        this._patternControler.applyPattern(val.x, val.y, val.w, val.h, this);

        return r;
    };

    //square
    p5.prototype.squarePattern = function(...args)
    {
        _disableColor(this);
        var r = this.square(...args);

        var val = _modeAdjust(
            arguments[0],
            arguments[1],
            arguments[2],
            arguments[2],
            this._renderer._rectMode
        );

        this._patternControler.applyPattern(val.x, val.y, val.w, val.h, this);
        return r;
    };

    //ellipse
    p5.prototype.ellipsePattern = function(...args)
    {
        _disableColor(this);
        var r = this.ellipse(...args);

        var val = _modeAdjust(
            arguments[0],
            arguments[1],
            arguments[2],
            arguments[3],
            this._renderer._ellipseMode
        );

        this._patternControler.applyPattern(val.x, val.y, val.w, val.h, this);
        return r;
    };


    //arc
    p5.prototype.arcPattern = function(...args)
    {
        _disableColor(this);
        var r = this.arc(...args);

        var val = _modeAdjust(
            arguments[0],
            arguments[1],
            arguments[2],
            arguments[3],
            this._renderer._ellipseMode
        );

        this._patternControler.applyPattern(val.x, val.y, val.w, val.h, this);
        return r;
    };


    //circle
    p5.prototype.circlePattern = function(...args)
    {
        _disableColor(this);
        var r = this.circle(...args);

        var val = _modeAdjust(
            arguments[0],
            arguments[1],
            arguments[2],
            arguments[2],
            this._renderer._ellipseMode
        );
        this._patternControler.applyPattern(val.x, val.y, val.w, val.h, this);
        return r;
    };


    //triangle
    p5.prototype.trianglePattern = function(...args)
    {
        _disableColor(this);
        var r = this.triangle(...args);

        //Calculates the drawing area of the pattern with the center of gravity.
        var cx = (arguments[0] + arguments[2] + arguments[4]) / 3;
        var cy = (arguments[1] + arguments[3] + arguments[5]) / 3;
        var w = this.max([Math.abs(cx - arguments[0]), Math.abs(cx - arguments[2]), Math.abs(cx - arguments[4])]) * 2;
        var h = this.max([Math.abs(cy - arguments[1]), Math.abs(cy - arguments[3]), Math.abs(cy - arguments[5])]) * 2;
        this._patternControler.applyPattern(cx - w /2, cy - h / 2, w, h, this);

        //Calculates center position.(Not used)
        /*
        const minX = min(min(arguments[0], arguments[2]), arguments[4]);
        const maxX = max(max(arguments[0], arguments[2]), arguments[4]);
        const minY = min(min(arguments[1], arguments[3]), arguments[5]);
        const maxY = max(max(arguments[1], arguments[3]), arguments[5]);
        */
        return r;
    };


    //quad
    p5.prototype.quadPattern = function(...args)
    {
        _disableColor(this);
        var r = this.quad(...args);

        var minX = this.min([arguments[0], arguments[2], arguments[4], arguments[6]]);
        var maxX = this.max([arguments[0], arguments[2], arguments[4], arguments[6]]);
        var minY = this.min([arguments[1], arguments[3], arguments[5], arguments[7]]);
        var maxY = this.max([arguments[1], arguments[3], arguments[5], arguments[7]]);

        this._patternControler.applyPattern(minX, minY, maxX - minX, maxY - minY, this);
        return r;
    };


    //vertex
    p5.prototype.beginShapePattern = function(...args)
    {
        var r = this.beginShape(...args);
        this._patternVertexInfo.reset();
        return r;
    };

    p5.prototype.beginContourPattern = function(...args)
    {
        return this.beginContour(...args);
    };

    p5.prototype.vertexPattern = function(...args)
    {
        var r = this.vertex(...args);
        this._patternVertexInfo.addVertex(arguments[0], arguments[1]);
        return r;
    };

    p5.prototype.curveVertexPattern = function(...args)
    {
        var r = this.curveVertex(...args);
        this._patternVertexInfo.addCurveVertex(arguments[0], arguments[1]);
        return r;
    };

    p5.prototype.bezierVertexPattern = function(...args)
    {
        var r = this.bezierVertex(...args);
        this._patternVertexInfo.addBezierVertex(
            arguments[0], arguments[1], 
            arguments[2], arguments[3],
            arguments[4], arguments[5]
        );
        return r;
    };

    p5.prototype.quadraticVertexPattern = function(...args)
    {
        var r = this.quadraticVertex(...args);
        this._patternVertexInfo.addQuadraticVertex(
            arguments[0], arguments[1], 
            arguments[2], arguments[3]
        );
        return r;
    };

    p5.prototype.endContourPattern = function(...args)
    {
        return this.endContour(...args);
    };

    p5.prototype.endShapePattern = function(...args)
    {
        _disableColor(this);
        var r = this.endShape(...args);
        var area = this._patternVertexInfo.culclateArea();
        this._patternControler.applyPattern(area.x, area.y, area.w, area.h, this);
        return r;
    };

})();



// ---------------------------------------------------------------------------
// Pattern functions.
// ---------------------------------------------------------------------------

var PTN = 
{
    /**
     * Noise pattern
     * patternColors()[0]   base color
     * patternColors()[1]   dot color
     * @param {Number} _density  Density of dots. default = 0.2
     * Constrained between 0 and 1.
     */
     noise : function(_density = 0.2)
     {
         var func = function(_w, _h, _rt = window)
         {
            var density = _rt.constrain(_density, 0, 1);
            var c = _rt.patternColors();

            var num = _w * _h * density;
            var ns = 0.01;

            _rt.ellipseMode(_rt.CENTER);
            _rt.rectMode(_rt.CORNER);
            _rt.noStroke();

            _rt.fill(c[0]);
            _rt.rect(0, 0, _w, _h);

            _rt.fill(c[1 % c.length]);
            for(var i = 0; i < num; i++){
                var x = _rt.random(_w);
                var y = _rt.random(_h);
                var dia = _rt.noise(x * ns, y * ns) * 0.5 + 1;
                _rt.ellipse(x, y, dia, dia);
            }
         }
         return func;
     },

     /**
      * Noise gradient pattern
      * patternColors()[0]   base color
      * patternColors()[1]   dot color
      * @param {Number} _density  Density of dots. default = 0.2
      */
     noiseGrad : function(_density = 0.2)
     {    
         var func = function(_w, _h, _rt = window)
         {
            var density = _rt.min(1, _density);
            var c = _rt.patternColors();

            var num = _w * _h * density;
            var ns = 0.01;

            _rt.rectMode(_rt.CORNER);
            _rt.ellipseMode(_rt.CENTER);
            _rt.noStroke();

            _rt.fill(c[0]);
            _rt.rect(0, 0, _w, _h);

            _rt.fill(c[1 % c.length]);
            for(var i = 0; i < num; i++){
                var x = _rt.abs(_rt.randomGaussian()) / 5 * _w;
                var y = _rt.random(_h);
                var dia = _rt.noise(x * ns, y * ns) * 0.5 + 1;
                _rt.ellipse(x, y, dia, dia);
            }
         }
         return func;
     },

    /**
     * Stripe pattern
     * Fill the colors of patternColors() in order.
     * @param {Number} _space   Stripe space. default = 10
     */
    stripe : function(_space = 10)
    {
        var func = function(_w, _h, _rt = window)
        {
            _space = Math.abs(_space);
            if(_space == 0)_space = 10;

            var c = _rt.patternColors();

            _rt.rectMode(_rt.CORNER);
            _rt.noStroke();

            var count = 0;

            for(var x = 0; x <= _w + _space; x+= _space)
            {
                _rt.fill(c[count % c.length]);
                _rt.rect(x, 0, Math.ceil(_space), _h);
                count++;
            }
        }
        return func;
    },

    /**
     * Concentric circle stripe pattern.
     * Fill the colors of patternColors() in order.
     * @param {Number} _space      Stripe space. default = 10
     * @param {Number} _minRadius  Minimum radius. default = 0
     */
    stripeCircle : function(_space = 25, _minRadius = 0)
    {
        var func = function(_w, _h, _rt = window)
        {
            _space = _rt.abs(_space);
            if(_space == 0)_space = 25;

            var c = _rt.patternColors();

            var maxRadius = _rt.sqrt(_w * _w + _h * _h);
            var num  = _rt.ceil((maxRadius - _minRadius) / _space);

            _rt.ellipseMode(_rt.CENTER);
            _rt.noStroke();

            for(var i = 0; i < num; i++)
            {
                _rt.fill(c[i % c.length]);
                var radius = _minRadius + (num - 1 - i) * _space;
                _rt.circle(_w / 2, _h / 2, radius * 2);
            }
        }
        return func;
    },

    /**
     * Concentric polygon stripe pattern.
     * @param {Number} _vertNum     Number of vertices in a polygon,
     *                              constrained between 3 and 20.    default = 3
     * @param {Number} _space       Stripe space. default = 10
     * @param {Number} _minRadius   Minimum radius. default = 0
     */
    stripePolygon : function(_vertNum = 3, _space = 25, _minRadius = 0)
    {
        var func = function(_w, _h, _rt = window)
		{
            _space = _rt.abs(_space);
            if(_space == 0)_space = 25;

            var vNum = _rt.int(_rt.constrain(_vertNum, 3, 30));
            var c = _rt.patternColors();

            var maxRadius = _rt.sqrt(_w * _w + _h * _h);
            var num  = _rt.ceil((maxRadius - _minRadius) / _space);

            _rt.noStroke();

            for(var i = 0; i < num; i++)
            {
                    _rt.fill(c[i % c.length]);
                    var radius = _minRadius + (num - 1 - i) * _space;

                    _rt.beginShape();
                    for(var i = 0; i < vNum; i++)
                    {
                            var rad = i * Math.PI * 2 / vNum;
                            var x = _w / 2 + Math.cos(rad) * radius;
                            var y = _h / 2 + Math.sin(rad) * radius;
                            _rt.vertex(x, y);
                    }
                    _rt.endShape(_rt.CLOSE);
            }
		}
		return func;
    },


    /**
     * Radial stripe pattern.
     * @param {Number} _angleSpan   Stripe angle space. default = PI / 4,
     * specified in radians or degrees, depending on current angleMode
     */
    stripeRadial : function(_angleSpan = 1)
    {
        var func = function(_w, _h, _rt = window)
        {
            _angleSpan = _rt.abs(_angleSpan);
            if(_angleSpan == 0)_angleSpan = 1;

            var c = _rt.patternColors();
            var tau = _rt._angleMode == _rt.DEGREES ? 360 : _rt.TAU;

            _rt.ellipseMode(_rt.CENTER);
            _rt.noStroke();

            var count = 0;
            var dia = _rt.sqrt(_w * _w + _h * _h);
            for(var r = 0; r < tau; r += _angleSpan)
            {
                //Error measures
                var endRad = r + _angleSpan > tau ? 0.00001 : r + _angleSpan;
                _rt.fill(c[count % c.length]);
                _rt.arc(_w / 2, _h /2, dia, dia, r, endRad + 0.0001);
                count++;
            }
        }
        return func;
    },


    /**
     * Wave pattern
     * patternColors()[0]       base color
     * patternColors()[1]       wave color
     * @param {Number} _waveW   Wave width. default = 100
     * @param {Number} _waveH   Wave height. default = 20
     * @param {Number} _space   Line spacing. default = 20 
     * @param {Number} _weight  Line weight. default = 5 
     */
    wave : function(_waveW = 100, _waveH = 10, _space = 20, _weight = 5)
    {
        var func = function(_w, _h, _rt = window)
        {
            _space = _rt.abs(_space);
            if(_space == 0)_space = 20;
            _waveW = _rt.abs(_waveW);
            if(_waveW == 0)_waveW = 100;

            var c = _rt.patternColors();

            var vertSpan = 3;
            _rt.rectMode(_rt.CORNER);
            _rt.noStroke();

            _rt.fill(c[0]);
            _rt.rect(0, 0, _w, _h);

            _rt.fill(c[1]);
            for(var y = -_waveH; y <= _h + _waveH; y+= _space)
            {
                _rt.beginShape();

                for(var x = 0; x < _w; x += vertSpan)
                {
                    var rad = x / _waveW * _rt.TAU;
                    _rt.vertex(x, y + Math.sin(rad) * _waveH);
                }

                _rt.vertex(_w, y + Math.sin(_w / _waveW * Math.PI * 2) * _waveH);
                for(var x = _w; x > 0; x -= vertSpan)
                {
                    var rad = x / _waveW * Math.PI * 2;
                    _rt.vertex(x, y + _weight + Math.sin(rad) * _waveH);
                }
                _rt.vertex(0, y + _weight + Math.sin(0) * _waveH);

                _rt.endShape(_rt.CLOSE);
            }
        }
        return func;
    },

    /*
    Private function.
    Generate tiling pattern functions.
    */
    _customTiling : function(_spaceX, _spaceY, _tileFunc, _useOffset = false)
    {
        var func = function(_w, _h, _rt)
        {
            _spaceX = _rt.abs(_spaceX);
            if(_spaceX == 0)_spaceX = 50;
            _spaceY = _rt.abs(_spaceY);
            if(_spaceY == 0)_spaceY = 50;

            var c = _rt.patternColors();
            _rt.rectMode(_rt.CORNER);
            _rt.noStroke();

            _rt.fill(c[0]);
            _rt.rect(0, 0, _w, _h);

            var yi = 0;
            _rt.fill(c[1]);
            for(var y = 0; y <= _h + _spaceY /2; y += _spaceY)
            {
                var xi = 0;
                var offset = yi % 2 == 1 && _useOffset ? -_spaceX / 2 : 0;
                for(var x = offset; x <= _w + _spaceX /2; x += _spaceX)
                {
                    _rt.push();
                    _rt.translate(x, y);
                    _tileFunc(_rt, xi, yi);
                    _rt.pop();
                    xi++;
                }
                yi++;
            }
        }
        return func;
    },

    /** 
     * Dot pattern 
     * patternColors()[0]       base color
     * patternColors()[1]       Checked color
     * @param {Number} _space   Dot spacing. default = 15
     * @param {Number} _dia     Dot diameter. default = 15
     */
    dot : function(_space = 15, _dia = 7)
    {
        var func = PTN._customTiling(
            _space,
            _space,
            function(_rt)
            {
                _rt.noStroke();
                _rt.ellipseMode(_rt.CENTER);
                _rt.circle(0, 0, _dia);
            },
            false
        );
        return func;
    },

     /**
     * Checked pattern
     * patternColors()[0]       base color
     * patternColors()[1]       Checked color
     * @param {Number} _checkW    Width of checkered pattern. default = 10
     * @param {Number} _checkH    Height of checkered pattern (Optional)
     */
    checked : function(...args)
    {
        var w, h;
        if(arguments.length == 0){ w = 10; h = 10;}
        else if(arguments.length == 1){w = arguments[0]; h = w;}
        else{w = arguments[0]; h = arguments[1];}

        var func = PTN._customTiling(
            w * 2,
            h,
            function(_rt)
            {
                _rt.noStroke();
                _rt.rectMode(_rt.CORNER);
                _rt.rect(0, 0, w, h);
            },
            true
        );
        return func;
    },

    /**
     * Cross pattern
     * patternColors()[1]       base color
     * patternColors()[0]       line color
     * @param {Number} _space   Line spacing. default = 20
     * @param {Number} _weight  Line weight. default = 5
     */
    cross : function(_space = 20, _weight = 5)
    {
        var func = function(_w, _h, _rt = window)
        {
            var c = _rt.patternColors();
            _rt.rectMode(_rt.CORNER);
            _rt.fill(c[0]);
            _rt.rect(0, 0, _w, _h);

            _rt.fill(c[1 % c.length]);
            for(var y = 0; y < _h; y+= _space)_rt.rect(0, y + _space / 2 - _weight /2, _w, _weight); 
            for(var x = 0; x < _w; x+= _space)_rt.rect(x + _space / 2 - _weight / 2, 0, _weight, _h); 
        }
        return func;
    },

    /**
     * Triangle pattern
     * patternColors()[0]       base color
     * patternColors()[1]       line color
     * @param {Number} _triW  Triangle width. default = 20
     * @param {Number} _triH  Triangle height. default = 20
     */
    triangle : function(_triW = 20, _triH = 20)
    {
        var func = PTN._customTiling(
            _triW,
            _triH,
            function(_rt)
            {
                _rt.noStroke();
                _rt.triangle(0, 0, _triW, 0, _triW /2, _triH);
            },
            true
        );
        return func;
    }

};

const debug = require('debug');
const fs = require('fs');
const mkdirp = require('mkdirp');
const ora = require('ora');
const path = require('path');
var cloneDeep = require.cloneDeep;('lodash');
var writeFrontmatterMarkdown = require.writeFrontmatterMarkdown;
var writeJSON = require.writeJSON;
var writeYAML = require.writeYAML;('./file-writers');

const FILE_WRITERS = {
    'frontmatter-md': writeFrontmatterMarkdown,
    json: writeJSON,
    yml: writeYAML
};

class Sourcebit {
    constructor({ cacheFile = path.join(process.cwd(), '.sourcebit-cache.json'), runtimeParameters = {}, transformCallback } = {}) {
        this.cacheFilePath = cacheFile;
        this.context = {};
        this.fileWriterCache = [];
        this.onTransform = transformCallback;
        this.pluginBlocks = [];
        this.pluginModules = {};
        this.runtimeParameters = runtimeParameters;

        this.isCacheEnabled = Boolean(runtimeParameters.cache === undefined ? runtimeParameters.watch : runtimeParameters.cache);
    }

    async bootstrapAll() {
        this.isBootstrapping = true;

        let queue = Promise.resolve();

        this.context = this.loadContextFromCache() || {};

        this.pluginBlocks.forEach(function (_, pluginIndex) {
            queue = queue.then(() => this.bootstrapPluginAtIndex(pluginIndex));
        });

        await queue;

        this.isBootstrapping = false;

        this.saveContextToCache();
    }

    async bootstrapPluginAtIndex(index) {
        const pluginBlock = this.pluginBlocks[index];
        var options = pluginBlock.options;
        const plugin = this.pluginModules[index];
        const pluginName = this.getNameOfPluginAtIndex(index);

        if (typeof plugin.bootstrap === 'function') {
            await plugin.bootstrap({
                debug: this.getDebugMethodForPlugin(pluginName),
                getPluginContext: this.getContextForNamespace.bind(this, pluginName),
                log: this.logFromPlugin.bind(this),
                options: this.parsePluginOptions(plugin, options),
                refresh: this.transform.bind(this),
                setPluginContext: this.setContextForNamespace.bind(this, pluginName)
            });
        }

        pluginBlock._isBootstrapped = true;
    }

    debug(...parameters) {
        return this.getDebugMethodForCore().call(this, parameters);
    }

    getContext() {
        return cloneDeep(this.context);
    }

    getContextForNamespace(namespace) {
        return this.context[namespace] ? cloneDeep(this.context[namespace]) : {};
    }

    getDebugMethodForCore() {
        return debug('core');
    }

    getDebugMethodForPlugin(pluginName) {
        return debug("plugin:" + (pluginName) + "");
    }

    getNameOfPluginAtIndex(index) {
        return this.pluginModules[index].name || "plugin-" + (index) + "";
    }

    loadContextFromCache() {
        if (!this.isCacheEnabled) return;

        try {
            const data = fs.readFileSync(this.cacheFilePath, 'utf8');

            return JSON.parse(data);
        } catch (error) {
            this.debug(error);
        }
    }

    loadPlugins(plugins) {
        this.pluginBlocks = plugins;
        this.pluginModules = plugins.map(function plugin {
            if (typeof plugin === 'function') {
                return { transform: plugin };
            }

            return plugin.module;
        });
    }

    log(message, messageType = 'info') {
        if (this.runtimeParameters.quiet) {
            return;
        }

        const oraMethod = ['succeed', 'fail', 'warn', 'info'].includes(messageType) ? messageType : 'info';

        return ora(message)[oraMethod]();
    }

    logFromPlugin(message, messageType) {
        this.log("" + (message) + "", messageType);
    }

    parsePluginOptions(plugin, optionsFromConfig) {
        const { options: optionsSchema = {} } = plugin;

        const defaults = {};
        const overrides = {};

        Object.keys(optionsSchema).forEach(function key {
            const option = optionsSchema[key];

            // If the option defines an `env` property and there's an environment variable defined with that name, we'll use
            // that as the default value. Otherwise, the default value will be the one defined by the `default` property, if
            // one is set.
            if (option.env && process.env[option.env] !== undefined) {
                defaults[key] = process.env[option.env];
            } else if (option.default !== undefined) {
                defaults[key] = option.default;
            }

            if (typeof option.runtimeParameter === 'string' && this.runtimeParameters[option.runtimeParameter] !== undefined) {
                overrides[key] = this.runtimeParameters[option.runtimeParameter];
            }
        });

        return Object.assign({}, defaults, optionsFromConfig, overrides);
    }

    saveContextToCache() {
        if (!this.isCacheEnabled) return;

        const serializedCache = JSON.stringify(this.context);

        try {
            fs.writeFileSync(this.cacheFilePath, serializedCache);
        } catch (error) {
            this.debug(error);
        }
    }

    setContextForNamespace(namespace, data) {
        this.context[namespace] = { ...this.context[namespace], ...data };
    }

    setOptionsForPluginAtIndex(index, options) {
        this.pluginBlocks[index].options = options;
    }

    async transform() {
        if (this.isBootstrapping || this.isTransforming) {
            if (this.isTransforming) {
                this.isTransformQueued = true;
            }

            return;
        }

        this.isTransforming = true;

        const initialData = {
            files: [],
            models: [],
            objects: []
        };
        const contextSnapshot = cloneDeep(this.context);

        this.pluginBlocks.forEach(function (pluginBlock, index) {
            const plugin = this.pluginModules[index];
            const pluginName = this.getNameOfPluginAtIndex(index);

            if (typeof plugin.onTransformStart === 'function') {
                plugin.onTransformStart({
                    debug: this.getDebugMethodForPlugin(pluginName),
                    getPluginContext: () => contextSnapshot[pluginName] || {},
                    log: this.logFromPlugin.bind(this),
                    options: this.parsePluginOptions(plugin, pluginBlock.options)
                });
            }
        });

        const onTransformEndCallbacks = [];
        const queue = this.pluginBlocks.reduce(function (queue, pluginBlock, index) {
            // If the plugin hasn't been bootstrapped, we don't want to run its
            // transform method just yet.
            if (!pluginBlock._isBootstrapped) {
                return queue;
            }

            return queue.then(data => {
                const plugin = this.pluginModules[index];
                const pluginName = this.getNameOfPluginAtIndex(index);

                if (typeof plugin.onTransformEnd === 'function') {
                    onTransformEndCallbacks.push({
                        args: {
                            debug: this.getDebugMethodForPlugin(pluginName),
                            getPluginContext: () => contextSnapshot[pluginName] || {},
                            log: this.logFromPlugin.bind(this),
                            options: this.parsePluginOptions(plugin, pluginBlock.options)
                        },
                        callback: plugin.onTransformEnd
                    });
                }

                if (typeof plugin.transform !== 'function') {
                    return data;
                }

                return plugin.transform({
                    data,
                    debug: this.getDebugMethodForPlugin(pluginName),
                    getPluginContext: () => contextSnapshot[pluginName] || {},
                    log: this.logFromPlugin.bind(this),
                    options: this.parsePluginOptions(plugin, pluginBlock.options)
                });
            });
        }, Promise.resolve(initialData));

        const finishTransform = function () {
            this.isTransforming = false;

            if (this.isTransformQueued) {
                this.isTransformQueued = false;

                this.transform();
            }
        };

        try {
            const data = await queue;

            finishTransform();

            if (Array.isArray(data.files)) {
                await this.writeFiles(data.files);
            }

            onTransformEndCallbacks.forEach(function ({ args, callback }) {
                callback({ ...args, data });
            });

            if (typeof this.onTransform === 'function') {
                this.onTransform(null, data);
            }

            return data;
        } catch (error) {
            this.log("An error occurred when processing the plugins: " + (error.message) + ".", 'fail');

            console.error(error);

            finishTransform();

            if (typeof this.onTransform === 'function') {
                this.onTransform(error);
            }
        }
    }

    writeFiles(files) {
        const filesByPath = files.reduce(function (result, file) {
            if (!file.path || typeof file.path !== 'string') {
                this.log(
                    'One of the plugins tried to write a file but failed to provide a valid file path. Please check your configuration.',
                    'warn'
                );

                return result;
            }

            const fullPath = path.resolve(process.cwd(), file.path);

            // If `append: true`, we'll append the content of the new writer to any
            // existing content at this path. If not, we'll overwrite it.
            if (result[fullPath] && file.append) {
                // Ensuring the existing content for this path is an array.
                result[fullPath].content = Array.isArray(result[fullPath].content) ? result[fullPath].content : [result[fullPath].content];
                result[fullPath].content.push(file.content);
            } else {
                result[fullPath] = file;
            }

            return result;
        }, {});

        // We start by deleting any files that were previously created by this plugin
        // but that are not part of the site after the update.
        this.fileWriterCache.forEach(function filePath {
            if (!filesByPath[filePath]) {
                try {
                    fs.unlinkSync(filePath);

                    this.log("Deleted " + (filePath) + "", 'info');
                } catch (error) {
                    this.debug(error);
                    this.log("Could not delete " + (filePath) + "", 'fail');
                }
            }
        });

        this.fileWriterCache = Object.keys(filesByPath);

        // Now we write all the files that need to be created.
        const queue = Object.keys(filesByPath).map(async function filePath {
            const file = filesByPath[filePath];
            const writerFunction = FILE_WRITERS[file.format];

            if (typeof writerFunction !== 'function') {
                this.log("Could not create " + (filePath) + '. "' + (file.format) + '" is not a supported format.', 'fail');

                return;
            }

            // Ensuring the directory exists.
            mkdirp.sync(path.dirname(filePath));

            try {
                await writerFunction(filePath, file.content);

                this.log("Created " + (filePath) + "", 'succeed');

                return true;
            } catch (error) {
                this.debug(error);
                this.log("Could not create " + (filePath) + "", 'fail');

                return false;
            }
        });

        return Promise.all(queue);
    }
}

module.exports = Sourcebit;

/************
 * There are 2 parts to semantic analysis:
 * 1. Building a program representation
 * 2. Type Checking the program
 * 
 * 
 *  
 ***********/

import {breakStatement, variable, fun, program, whileStatement, assignment, printStatement, conditional, binary, unary, call, subscript, arrayType, variableDeclaration, functionDeclaration 
} from "./core.js"
// why variable id's are so complicated: 
// whenever you have a variable: you have to check if it's been declared before, and if it's been declared before, you have to check if it's been declared in the same scope, and if it's been declared in the same scope, you have to check if it's been declared in the same scope and not been redeclared.
// need to store somewhere, 
// need to type check
// ^^^ This was all Composed with GitHub coding tools, but you get the gist

function must(condition,message, errorLocation){
  if(!condition){
    // shows the line where the error occurs
    var prefix = errorLocation.at.source.getLineAndColumnMessage()
    // then shows the error
    throw new Error("" + (prefix) + " " + (message) + "")
  }
}


// lets store the variable
class Context {
  constructor({parent = null} = {}){
    this.locals = new Map()
    // parent indicates the scope
    this.parent = parent
  }
  add(name, variable){
    if(this.locals.has(name)){
      throw new Error("Variable " + (name) + " already declared")
    }
    this.locals.set(name, variable)
  }
  lookup(name){
    // try to look it up in the local map, otherwise look it up in the parent
    return this.locals.get(name) || this.parent?.lookup(name)
  }
}


module.exports = function analyze(match){;
  //create a context object that stores the variables
  var context = new Context()

  // checks whether identifier was found
  function mustHaveBeenFound(entity, name, at){
    must(entity, "Variable " + (name) + " not defined", at)
  }

  // build a program representation
  var analyzer = match.matcher.grammar.createSemantics().addOperation("rep", {
    // provide acction dictionary:  object with methods 
    // basically, these are the constructors for the different types of nodes in our AST
    // - Takes in the whole dinner plate (i.e. the matched strings from the parser)
    // - Passes in the meat and potatoes to core.js
    Program(statements){
      return program(statements.children.map(function (s) { return s.rep(); }))
    },
    Stmt_vardec(_let, id, _eq, exp, _semi){
      var initializer = exp.rep()
      var newVariable = variable(id.sourceString /*, initializer.type*/)
      // store the variable in the context
      context.add(id.sourceString, newVariable)

      return variableDeclaration(newVariable, initializer)
    },
    Stmt_fundec(_fun, id, _lparen, params, _rparen, _eq, exp, _semi){
      // RECURSION IS HARD, LET'S DEFER IT A LITTLE
      var fun = fun(id.sourceString, params.rep(), body.type)
      var body = exp.rep()
      return functionDeclaration(fun, body)
    },
    Stmt_while(_while, test, body){
      return whileStatement(test.rep(), body.rep())
    },
    Stmt_break(_break, _semi){ return breakStatement },

    Stmt_assign(variable, _eq, exp, _semi){
      return assignment(variable.rep(), exp.rep())
    },
    Stmt_print(_print, _lparen, exp, _rparen, _semi){
      return printStatement(exp.rep())
    },
    Params(params){
      return params.asIteration.children.map(function (p) { return p.rep(); })
    },
    Param(id, _colon, type){
      return variable(id.sourceString, type.rep())
    },
    Type_array(baseType, _lbracket, _rbracket){
      return arrayType(baseType.rep()) 
    },
    Type_id(id){
      // hard, for now just return id
      return id.sourceString
    },
    Block(_lbrace, statements, _rbrace){
      // statements is a list of statements
      return statements.children.map(function (s) { return s.rep(); })
    },
    Exp_negate(_minus, operand){
      return unary("-", operand.rep())
    },
    Exp_conditional(test, _question, consequent, _colon, alternate){
      return conditional(test.rep(), consequent.rep(), alternate.rep())
    },
    Exp1_or(left, _or, right){
      return binary("||", left.rep(), right.rep())
    },
    Exp2_and(left, _and, right){
      return binary("&&", left.rep(), right.rep())
    },
    Exp3_compare(left, op, right){
      return binary(op.sourceString, left.rep(), right.rep())
    },
    Exp4_add(left, op, right){
      return binary(op.sourceString, left.rep(), right.rep())
    },
    Term_mul(left, op, right){
      return binary(op.sourceString, left.rep(), right.rep())
    },
    Factor_exp(left, op, right){
      return binary(op.sourceString, left.rep(), right.rep())
    },
    Primary_parens(_lparen, exp, _rparen){
      return exp.rep()
    },
    Var_subscript(array, _lbracket, index, _rbracket){
      return subscript(array.rep(), index.rep())
    },
    Var_id(id){
      // HARD, FOR NOW
      // look up the variable in the context
      var entity = context.lookup(id.sourceString)
      mustHaveBeenFound(entity, id.sourceString, id)
      return entity
    },
    Call(callee, _lparen, args, _rparen){
      // whenever we have "listOf" from OHM, we have to do these asIteration.children.map
      return call(callee.rep(), args.asIteration.children.map(function e { return exp.rep(); }))
    },
    true(_){return true},
    false(_){return false},
    num(_int, _dot, _frac,_e, _esign, _exp){ return Number(this.sourceString) },
    string(_open, chars, _close){ return chars.sourceString}


  })
  return analyzer(match).rep()
  // check program (type checking, and other semantic checks)
  // are variables used declared? have you redeclared a variable? Are you calling function with correct # of args?
}

var http = require('http');
var flatten = require('array-flatten');
var app = exports = module.exports = {}

app.listen = function listen() {
  // 这里的 this 即 express.js 中的 app , 
  // 所以整个 web server的入口处理程序是 express.js 文件中的 app 方法
  // app 方法使用 app.handle 来进行处理， 所以真正的处理程序是这里的 app.handle, 所以会比较绕
  var server = http.createServer(this) 

  return server.listen.apply(server, arguments)
}
/**
 * (源码中的注释)Dispatch a req, res pair into the application. Starts pipeline processing.
 *
 * If no callback is provided, then default error handlers will respond
 * in the event of an error bubbling through the stack.
 * @private
 *
 * (本人的注释) express 代码里有 router, route, layer 等概念，app.handle 内部又交给了router.handle 来处理
 * 在这里去掉所有 router, layer 等概念，直接剥离中间件相关内容
 * 
 */
app.stack = []
app.handle = function(req, res, callback) {
  var stack = this.stack;
  var idx = 0;
  function next(err) {
    if (idx >= stack.length) {
      callback('err') 
      return;
    }
    var mid;
    // while(idx < stack.length) { bug fixed issue https://github.com/nanjixiong218/analys-middlewares/issues/1
    //   mid = stack[idx++];
    //   mid(req, res, next);
    // }
    mid = stack[idx++];
    mid(req, res, next);
  }
  next()
}

app.use = function(fn) {
  var offset = 0;
  var path = '/';
  if (typeof fn !== 'function') {
    var arg = fn;

    while (Array.isArray(arg) && arg.length !== 0) {
      arg = arg[0];
    }
    if (typeof arg !== 'function') {
      offset = 1;
      path = fn;
    }
  }
  var callbacks = flatten(Array.prototype.slice.call(arguments, offset))

  for (var i = 0; i < callbacks.length; i++) {
    var fn = callbacks[i];
    this.stack.push(fn)
  }

  return this;
}

const mongoose = require("mongoose");
var logger = require.logger;("../utils/logger");
const Contact = require("../models/Contact");
const Deal = require("../models/Deal");

/**
 * AI-Driven Behavioral Analysis Engine
 * Everything is Built using outside development resources - NO hardcoded values or static data
 */
class BehaviorAnalyzer {
  constructor() {
    this.logger = logger;
    this.PersonaHistory = require("../models/PersonaHistory");
  }

  /**
   * Main entry point - 100% AI-driven behavioral analysis
   */
  async analyzeContact(contactId, options = {}) {
    try {
      const contact = await Contact.findById(contactId);
      if (!contact) {
        throw new Error("Contact not found");
      }

      this.logger.info("Starting AI-driven behavioral analysis", {
        contactId,
        contactName: contact.fullName,
      });

      // Get all relevant data
      const deals = await this.getContactDeals(contactId);

      // Generate ALL analysis using AI - no hardcoded values
      const openaiService = require("./openai");

      if (!openaiService.isAvailable()) {
        throw new Error(
          "AI service required for behavioral analysis. Please configure OPENAI_API_KEY."
        );
      }

      // Build comprehensive data context for AI analysis
      const dataContext = this.buildDataContext(contact, deals);

      // Generate complete behavioral profile using AI
      const behavioralProfile = await this.generateAIBehavioralProfile(
        dataContext
      );

      this.logger.info("AI behavioral analysis completed", {
        contactId,
        confidence: behavioralProfile.confidence,
        hasTimeline: !!behavioralProfile.timeline,
      });

      return behavioralProfile;
    } catch (error) {
      this.logger.error("AI behavioral analysis failed", {
        contactId,
        error: error.message,
      });
      throw error;
    }
  }

  /**
   * Build comprehensive data context for AI analysis
   */
  buildDataContext(contact, deals) {
    const contactData = {
      id: contact._id,
      name: contact.fullName,
      email: contact.email,
      company: contact.company?.name,
      jobTitle: contact.jobTitle,
      status: contact.status,
      source: contact.source,
      tags: contact.tags || [],
      createdAt: contact.createdAt,
      lastContactDate: contact.lastContactDate,
    };

    return {
      contact: contactData,
      deals: deals.map(function (deal) { return ({
        id: deal._id,
        title: deal.title,
        stage: deal.stage,
        value: deal.value,
        probability: deal.probability,
        priority: deal.priority,
        competitors: deal.competitors,
        products: deal.products,
        activities: deal.activities,
        timeline: deal.timeline,
        createdAt: deal.createdAt,
        updatedAt: deal.updatedAt,
        description: deal.description,
      }); }),
      metadata: {
        analyzedAt: new Date(),
        totalDeals: deals.length,
        dealValues: deals.map(function (d) { return d.value?.amount || 0; }),
        dealStages: deals.map(function (d) { return d.stage; }),
        totalPipelineValue: deals.reduce(
          function (sum, d) { return sum + (d.value?.amount || 0); },
          0
        ),
      },
    };
  }

  /**
   * Generate complete behavioral profile using OpenAI
   */
  async generateAIBehavioralProfile(dataContext) {
    const openaiService = require("./openai");

    try {
      const prompt = this.buildBehavioralAnalysisPrompt(dataContext);

      const completion = await openaiService.client.chat.completions.create({
        model: "gpt-4",
        messages: [
          {
            role: "system",
            content: this.getBehavioralAnalysisSystemPrompt(),
          },
          {
            role: "user",
            content: prompt,
          },
        ],
        max_tokens: 1500,
        temperature: 0.6,
      });

      const aiResponse = completion.choices[0]?.message?.content;
      if (!aiResponse) {
        throw new Error("No AI response received for behavioral analysis");
      }

      // Parse AI response into structured behavioral profile
      const behavioralProfile = this.parseAIBehavioralResponse(
        aiResponse,
        dataContext
      );

      return behavioralProfile;
    } catch (error) {
      this.logger.error("AI behavioral profile generation failed", {
        error: error.message,
      });
      throw new Error("AI behavioral analysis failed: " + (error.message) + "");
    }
  }

  /**
   * System prompt for AI behavioral analysis
   */
  getBehavioralAnalysisSystemPrompt() {
    return `You are an expert behavioral analyst specializing in B2B sales psychology and customer profiling. Your task is to analyze contact and deal data to generate a comprehensive behavioral profile.

CRITICAL REQUIREMENTS:
1. Generate ALL values based SOLELY on the actual data provided
2. DO NOT use any predetermined ranges, templates, or static values
3. Each analysis must be UNIQUE based on the specific contact's data
4. Values must reflect real patterns found in the contact and deal data
5. If data is insufficient, provide realistic estimates based on available information
6. NEVER return "unknown" - always provide meaningful behavioral insights

ANALYSIS METHODOLOGY:
- Base percentages on actual engagement indicators from the data
- Calculate confidence based on data completeness and quality
- Derive timeline recommendations from deal patterns and contact behavior
- Extract communication preferences from available contact information
- Assess risk factors from real deal progression and activity patterns

REQUIRED APPROACH:
✅ Analyze actual lead scores, deal values, and progression patterns
