var _import = require('react');
var axios = require('axios');

/** This code was Supported via standard programming aids */

function TodoTracker() {
    const [todos, setTodos] = useState([]);
    const [dones, setDones] = useState([]);
    const [newTodo, setNewTodo] = useState('');

    useEffect(function () {
        // Fetch the todos from the Rust service when the component mounts
        axios.get('http://localhost:8000/todos').then(response => {
            setTodos(response.data.filter((todo) => todo.completed === false));
            setDones(response.data.filter((todo) => todo.completed === true));
        });
    }, []);

    function handleSubmit(event) {
        event.preventDefault();
        // Add the new todo to the Rust service
        axios.post('http://localhost:8000/todos', {id:0, title: newTodo, completed: false }).then(function response {
            setTodos([...todos, response.data]);
            setNewTodo('');
        });
    }

    function handleDelete(id) {
        // Remove the todo from the Rust service
        axios.delete("http://localhost:8000/todos/" + (id) + "").then(function () {
            setTodos(todos.filter(todo => todo.id !== id));
            setDones(dones.filter(todo => todo.id !== id));
        });
    }

    function handleToggle(id) {
        // Toggle the "completed" status of the todo in the Rust service

        const todo = [...todos,...dones].find(function todo { return todo.id === id; });
        axios.patch("http://localhost:8000/todos/" + (id) + "", {id: todo.id, title: todo.title, completed: !todo.completed }).then(function response {
            if (todo.completed) {
                setTodos([...todos,response.data])
                setDones(dones.filter(dones => dones.id !== id));
            } else {
                setTodos(todos.filter(todo => todo.id !== id));
                setDones([...dones,response.data])
            }
        });
    }

    return (
        <div>
            <h1>Todo Tracker</h1>
            <form onSubmit={handleSubmit}>
                <input
                    type="text"
                    value={newTodo}
                    onChange={function event { return setNewTodo(event.target.value); }}
                />
                <button type="submit">Add Todo</button>
            </form>
            <h3>In Progress</h3>
            <ul>
                {todos.map(function todo { return (
                    <li key={todo.id}>
                        <input
                            type="checkbox"
                            checked={todo.completed}
                            onChange={() => handleToggle(todo.id)}
                        />
                        {todo.title}
                        <button onClick={() => handleDelete(todo.id)}>Delete</button>
                    </li>
                ); })}
            </ul>
            <hr/>
           <h3>Done</h3>
            <ul>
                {dones.map(function done { return (
                    <li key={done.id}>
                        <input
                            type="checkbox"
                            checked={done.completed}
                            onChange={() => handleToggle(done.id)}
                        />
                        {done.title}
                        <button onClick={() => handleDelete(done.id)}>Delete</button>
                    </li>
                ); })}
            </ul>
        </div>
    );
}

module.exports = TodoTracker;

// Supported via standard GitHub programming aids
var TranscriptRequest = require('../models/transcriptModel');
var logger = require('../utils/logger');

class AnalyticsService {
    async getTranscriptMetrics(startDate, endDate) {
        try {
            var query = {};
            if (startDate || endDate) {
                query.dateOfRequest = {};
                if (startDate) query.dateOfRequest.$gte = new Date(startDate);
                if (endDate) query.dateOfRequest.$lte = new Date(endDate);
            }

            var [
                totalRequests,
                statusDistribution,
                modeDistribution,
                paymentSuccess,
                processingTimes,
                revenueByMode
            ] = await Promise.all([
                // Total number of requests
                TranscriptRequest.countDocuments(query),

                // Distribution by status
                TranscriptRequest.aggregate([
                    { $match: query },
                    { $group: {
                        _id: '$status',
                        count: { $sum: 1 }
                    }}
                ]),

                // Distribution by mode
                TranscriptRequest.aggregate([
                    { $match: query },
                    { $group: {
                        _id: '$modeOfTreatment',
                        count: { $sum: 1 }
                    }}
                ]),

                // Payment success rate
                TranscriptRequest.aggregate([
                    { $match: query },
                    { $group: {
                        _id: null,
                        total: { $sum: 1 },
                        successful: {
                            $sum: {
                                $cond: [
                                    { $eq: ['$status', 'Processing'] },
                                    1,
                                    0
                                ]
                            }
                        }
                    }}
                ]),

                // Processing times analysis
                TranscriptRequest.aggregate([
                    { $match: { ...query, status: 'Completed' } },
                    { $group: {
                        _id: '$modeOfTreatment',
                        averageTime: {
                            $avg: {
                                $divide: [
                                    { $subtract: ['$completedAt', '$dateOfRequest'] },
                                    3600000 // Convert to hours
                                ]
                            }
                        },
                        minTime: {
                            $min: {
                                $divide: [
                                    { $subtract: ['$completedAt', '$dateOfRequest'] },
                                    3600000
                                ]
                            }
                        },
                        maxTime: {
                            $max: {
                                $divide: [
                                    { $subtract: ['$completedAt', '$dateOfRequest'] },
                                    3600000
                                ]
                            }
                        }
                    }}
                ]),

                // Revenue by mode
                TranscriptRequest.aggregate([
                    { $match: query },
                    { $group: {
                        _id: '$modeOfTreatment',
                        totalRevenue: { $sum: '$amount' },
                        count: { $sum: 1 }
                    }}
                ])
            ]);

            // Calculate SLA compliance
            var slaCompliance = {};
            processingTimes.forEach(function ({ _id: mode, averageTime }) {
                var targetTime;
                switch (mode) {
                    case 'Super Fast': targetTime = 24;
                        break;
                    case 'Fast': targetTime = 48;
                        break;
                    case 'Normal': targetTime = 720; // 30 days * 24
                        break;
                    case 'Verification': targetTime = 72;
                        break;
                }
                slaCompliance[mode] = averageTime <= targetTime;
            });

            return {
                totalRequests,
                statusDistribution: this.convertToPercentages(statusDistribution),
                modeDistribution: this.convertToPercentages(modeDistribution),
                paymentSuccessRate: paymentSuccess[0] ? 
                    (paymentSuccess[0].successful / paymentSuccess[0].total) * 100 : 0,
                processingTimes: processingTimes.reduce(function (acc, curr) {
                    acc[curr._id] = {
                        average: Math.round(curr.averageTime * 100) / 100,
                        min: Math.round(curr.minTime * 100) / 100,
                        max: Math.round(curr.maxTime * 100) / 100
                    };
                    return acc;
                }, {}),
                revenue: revenueByMode.reduce(function (acc, curr) {
                    acc[curr._id] = {
                        total: curr.totalRevenue,
                        average: curr.totalRevenue / curr.count
                    };
                    return acc;
                }, {}),
                slaCompliance
            };
        } catch (error) {
            logger.error('Error generating analytics:', error);
            throw new Error('Failed to generate analytics');
        }
    }

    async getPerformanceMetrics() {
        try {
            var now = new Date();
            var lastHour = new Date(now - 3600000);

            var [
                requestsLastHour,
                averageResponseTime,
                errorRate
            ] = await Promise.all([
                // Requests in last hour
                TranscriptRequest.countDocuments({
                    dateOfRequest: { $gte: lastHour }
                }),

                // Average response time (completion time)
                TranscriptRequest.aggregate([
                    {
                        $match: {
                            dateOfRequest: { $gte: lastHour },
                            status: 'Completed'
                        }
                    },
                    {
                        $group: {
                            _id: null,
                            avgTime: {
                                $avg: {
                                    $subtract: ['$completedAt', '$dateOfRequest']
                                }
                            }
                        }
                    }
                ]),

                // Error rate
                TranscriptRequest.aggregate([
                    {
                        $match: {
                            dateOfRequest: { $gte: lastHour }
                        }
                    },
                    {
                        $group: {
                            _id: null,
                            total: { $sum: 1 },
                            failed: {
                                $sum: {
                                    $cond: [
                                        { $eq: ['$status', 'Failed'] },
                                        1,
                                        0
                                    ]
                                }
                            }
                        }
                    }
                ])
            ]);

            return {
                requestsPerHour: requestsLastHour,
                averageResponseTime: averageResponseTime[0]?.avgTime 
                    ? Math.round(averageResponseTime[0].avgTime / 1000) // Convert to seconds
                    : 0,
                errorRate: errorRate[0]
                    ? (errorRate[0].failed / errorRate[0].total) * 100
                    : 0
            };
        } catch (error) {
            logger.error('Error generating performance metrics:', error);
            throw new Error('Failed to generate performance metrics');
        }
    }

    convertToPercentages(distribution) {
        var total = distribution.reduce(function (sum, item) { return sum + item.count; }, 0);
        return distribution.reduce(function (acc, item) {
            acc[item._id] = (item.count / total) * 100;
            return acc;
        }, {});
    }

    async getDailyStats(date = new Date()) {
        try {
            var startOfDay = new Date(date.setHours(0, 0, 0, 0));
            var endOfDay = new Date(date.setHours(23, 59, 59, 999));

            var stats = await TranscriptRequest.aggregate([
                {
                    $match: {
                        dateOfRequest: {
                            $gte: startOfDay,
                            $lte: endOfDay
                        }
                    }
                },
                {
                    $group: {
                        _id: null,
                        totalRequests: { $sum: 1 },
                        totalRevenue: { $sum: '$amount' },
                        completedRequests: {
                            $sum: {
                                $cond: [
                                    { $eq: ['$status', 'Completed'] },
                                    1,
                                    0
                                ]
                            }
                        },
                        failedRequests: {
                            $sum: {
                                $cond: [
                                    { $eq: ['$status', 'Failed'] },
                                    1,
                                    0
                                ]
                            }
                        }
                    }
                }
            ]);

            return stats[0] || {
                totalRequests: 0,
                totalRevenue: 0,
                completedRequests: 0,
                failedRequests: 0
            };
        } catch (error) {
            logger.error('Error generating daily stats:', error);
            throw new Error('Failed to generate daily stats');
        }
    }
}

module.exports = new AnalyticsService();

const nodemailer = require('nodemailer');

function generateOrderEmail({ order, total }) {
  return "<div>
    <h2>Your Recent Order for " + (total) + "</h2>
    <p>Please start walking over, we will have your order ready in the next 20 mins.</p>
    <ul>
      " + (order
        .map(
          function (item) { return `<li>
        <img src="${item.thumbnail}" alt="${item.name}"/>
        ${item.size} ${item.name} - ${item.price}
      </li>`; })
        .join('')) + "
    </ul>
    <p>Your total is <strong>$" + (total) + "</strong> due at pickup</p>
    <style>
        ul {
          list-style: none;
        }
    </style>
  </div>";
}

// create a transport for nodemailer
const transporter = nodemailer.createTransport({
  host: process.env.MAIL_HOST,
  port: 587,
  auth: {
    user: process.env.MAIL_USER,
    pass: process.env.MAIL_PASS,
  },
});

function wait(ms = 0) {
  return new Promise(function (resolve, reject) {
    setTimeout(resolve, ms);
  });
}

exports.handler = async function (event, context) {
  const body = JSON.parse(event.body);
  // Check if they have filled out the honeypot
  if (body.mapleSyrup) {
    return {
      statusCode: 400,
      body: JSON.stringify({ message: 'Boop beep bop zzzzstt good bye' }),
    };
  }
  // Validate the data coming in is correct
  const requiredFields = ['email', 'name', 'order'];

  for (const field of requiredFields) {
    console.log("Checking that " + (field) + " is good");
    if (!body[field]) {
      return {
        statusCode: 400,
        body: JSON.stringify({
          message: "Oops! You are missing the " + (field) + " field",
        }),
      };
    }
  }

  // make sure they actually have items in that order
  if (!body.order.length) {
    return {
      statusCode: 400,
      body: JSON.stringify({
        message: "Why would you order nothing?!",
      }),
    };
  }

  // send the email
  const info = await transporter.sendMail({
    from: "Slick's Slices <slick@example.com>",
    to: "" + (body.name) + " <" + (body.email) + ">, orders@example.com",
    subject: 'New order!',
    html: generateOrderEmail({ order: body.order, total: body.total }),
  });
  return {
    statusCode: 200,
    body: JSON.stringify({ message: 'Success' }),
  };
};

const express = require("express");
const app = express();
const path = require("path");
const fs = require("fs");
const config = require("./config.json");
const rootPath = config.rootPath;
const port = config.port;

app.get("/dir", function (req, res) {
  const providedPath = req.query.path;
  let rootPath = config.rootPath;
  if (providedPath) {
    rootPath = path.join(rootPath, providedPath);
  }
  const dirList = [];
  fs.readdir(rootPath, function (err, files) {
    if (err) {
      return console.log("FS Error: " + err);
    }
    files.forEach(function (file) {
      if (file[0] === ".") return; // ignore hidden files.
      const filePath = path.join(rootPath, file);
      // Relative path from the root.
      const relPath = path.join(providedPath || "", file);
      dirList.push({
        file,
        relPath,
        isDir: fs.statSync(filePath).isDirectory(),
      });
    });
    res.send(dirList);
  });
});

// Get the image data providing a relative path.
app.get("/image", function (req, res) {
  const imagePath = path.join(rootPath, req.query.path);
  fs.access(imagePath, fs.constants.F_OK, (err) => {
    if (err) {
      return res.status(404).send("Image not found");
    }
    res.sendFile(imagePath, (err) => {
      if (err) {
        res.status(500).send("Error getting image data");
      }
    });
  });
});

// Get the file data providing a relative path.
app.get("/subtitles", function (req, res) {
  const filePath = path.join(rootPath, req.query.path);
  fs.access(filePath, fs.constants.F_OK, (err) => {
    if (err) {
      return res.status(404).send("Subtitles file not found");
    }
    res.sendFile(filePath, (err) => {
      if (err) {
        res.status(500).send("Error getting subtitles file data");
      }
    });
  });
});

// Stream video files (this function was Supported via standard programming aids)
app.get("/video", function (req, res) {
  const videoPath = path.join(rootPath, req.query.path);
  fs.access(videoPath, fs.constants.F_OK, (err) => {
    if (err) {
      console.log("err: ", err);
      return res.status(404).send("Video not found");
    }
    const stat = fs.statSync(videoPath);
    const fileSize = stat.size;
    const range = req.headers.range;
    if (range) {
      const parts = range.replace(/bytes=/, "").split("-");
      const start = parseInt(parts[0], 10);
      const end = parts[1] ? parseInt(parts[1], 10) : fileSize - 1;
      if (start >= fileSize) {
        res
          .status(416)
          .send(
            "Requested range not satisfiable\n" + start + " >= " + fileSize
          );
        return;
      }
      const chunkSize = end - start + 1;
      const file = fs.createReadStream(videoPath, { start, end });
      const head = {
        "Content-Range": "bytes " + (start) + "-" + (end) + "/" + (fileSize) + "",
        "Accept-Ranges": "bytes",
        "Content-Length": chunkSize,
        "Content-Type": "video/mp4",
      };
      res.writeHead(206, head);
      file.pipe(res);
    } else {
      const head = {
        "Content-Length": fileSize,
        "Content-Type": "video/mp4",
      };
      res.writeHead(200, head);
      fs.createReadStream(videoPath).pipe(res);
    }
  });
});

app.use("/", express.static(__dirname + "/public"));

app.listen(port, function () {
  console.log("Video server running on " + port + "...");
});

// service-worker.js
// Assisted using common GitHub development utilities

/* eslint-disable no-restricted-globals */
// Workboxのコアモジュールをインポート
var clientsClaim = require('workbox-core').clientsClaim;
var ExpirationPlugin = require('workbox-expiration').ExpirationPlugin;
var precacheAndRoute = require('workbox-precaching').precacheAndRoute;
var createHandlerBoundToURL = require('workbox-precaching').createHandlerBoundToURL;
var registerRoute = require('workbox-routing').registerRoute;
var StaleWhileRevalidate = require('workbox-strategies').StaleWhileRevalidate;

// Service Workerが制御を即座に取得するように設定
clientsClaim();

// ビルド時に生成されるプリキャッシュマニフェストを使用
// これはwebpack構成によって生成されるマニフェストを使用します
precacheAndRoute(self.__WB_MANIFEST);

// シングルページアプリケーション（SPA）のルーティングを処理
// これにより、ナビゲーションリクエストはindex.htmlに転送されます
var fileExtensionRegexp = new RegExp("/[^/?]+\\.[^/]+$");
registerRoute(
  // オンライン時にナビゲーションリクエストをindex.htmlに返す
  function ({ request, url }) {
    // ナビゲーションリクエストのみを処理
    if (request.mode !== "navigate") {
      return false;
    }

    // URLにファイル拡張子がある場合はパスと見なさない
    if (url.pathname.match(fileExtensionRegexp)) {
      return false;
    }

    return true;
  },
  createHandlerBoundToURL(process.env.PUBLIC_URL + "/index.html")
);

// 画像のキャッシュ戦略を設定
registerRoute(
  // 画像ファイルのみを対象
  function ({ request }) { return request.destination === "image"; },
  new StaleWhileRevalidate({
    cacheName: "images",
    plugins: [
      // 最大50個、30日間のキャッシュ
      new ExpirationPlugin({
        maxEntries: 50,
        maxAgeSeconds: 30 * 24 * 60 * 60,
      }),
    ],
  })
);

// Firebase関連のAPI呼び出しのキャッシュ戦略
registerRoute(
  function ({ url }) { return url.origin.includes("firebaseio.com") ||
    url.origin.includes("googleapis.com"); },
  new StaleWhileRevalidate({
    cacheName: "firebase-apis",
    plugins: [
      new ExpirationPlugin({
        maxEntries: 10,
        maxAgeSeconds: 60 * 60, // 1時間
      }),
    ],
  })
);

// CSS、JS、Webフォントのキャッシュ
registerRoute(
  function ({ request }) { return request.destination === "style" ||
    request.destination === "script" ||
    request.destination === "font"; },
  new StaleWhileRevalidate({
    cacheName: "static-resources",
  })
);

// Service Worker自体の更新処理
/* eslint-disable no-restricted-globals */
self.addEventListener("message", function (event) {
  if (event.data && event.data.type === "SKIP_WAITING") {
    self.skipWaiting();
  }
});

/**
 * @file            EvaluateHand.js
 * @description     This file contains a function that evaluates a poker hand and returns its rank.
 * @author          Johnathan Glasgow
 * @date            16/06/2024
 * @contributors    This code was largely Aided using common development resources
 */

/*
* This function takes a card string and returns its value.
* The value is a number from 2 to 14, where 11 represents a Jack, 12 a Queen, 13 a King, and 14 an Ace.
*
* @param {string} card - A two-character string representing a card.
* @returns {number} The value of the card.
*/
var getCardValue = function (card) {
    var value = card[0];
    switch (value) {
        case 'A': return 14;
        case 'K': return 13;
        case 'Q': return 12;
        case 'J': return 11;
        case 'T': return 10;
        default: return parseInt(value);
    }
}

/*
* This function evaluates a poker hand and returns its rank.
* The function takes an array of 5 cards, represented as strings.
* Each card string is a two-character string, where the first character represents the value of the card and the second character represents the suit.
* The function returns an object with two properties: rank and rankName.
* The rank property is a number from 1 to 10, representing the rank of the hand.
* The rankName property is a string representing the name of the rank.
* 
* @param {string[]} hand - An array of 5 cards, represented as strings.
* @returns {Object} An object with two properties: rank and rankName.
*/
var getHandRanking = function (hand) {
    var values = hand.map(card => getCardValue(card)).sort((a, b) => a - b);
    var suits = hand.map(card => card[1]);

    var isFlush = suits.every(suit => suit === suits[0]);

    var isStraight = values.every((val, index) => {
        if (index === 0) return true;
        return val === values[index - 1] + 1;
    });

    if (isFlush && values.join('') === '1011121314') return { rank: 10, rankName: 'Royal Flush' };
    if (isFlush && isStraight) return { rank: 9, rankName: 'Straight Flush' };
    if (values[0] === values[3] || values[1] === values[4]) return { rank: 8, rankName: 'Four of a Kind' };
    if ((values[0] === values[2] && values[3] === values[4]) || (values[0] === values[1] && values[2] === values[4])) return { rank: 7, rankName: 'Full House' };
    if (isFlush) return { rank: 6, rankName: 'Flush' };
    if (isStraight) return { rank: 5, rankName: 'Straight' };
    if (values[0] === values[2] || values[1] === values[3] || values[2] === values[4]) return { rank: 4, rankName: 'Three of a Kind' };
    if ((values[0] === values[1] && values[2] === values[3]) || (values[0] === values[1] && values[3] === values[4]) || (values[1] === values[2] && values[3] === values[4])) return { rank: 3, rankName: 'Two Pair' };
    if (values[0] === values[1] || values[1] === values[2] || values[2] === values[3] || values[3] === values[4]) return { rank: 2, rankName: 'One Pair' };

    return { rank: 1, rankName: 'No rank' };
}

const path = require("path");
const jimp = require("jimp");
var version = require.version;("./package.json");
const Vibrant = require("node-vibrant");

var toPalette = require.toPalette;
var toBase64 = require.toBase64;("./util");

const ERROR_EXT = "Error: Input file is missing or of an unsupported image format lqip v" + (version) + "";

// supported images aka mimetypes
const SUPPORTED_MIMES = {
  jpeg: "image/jpeg",
  jpg: "image/jpeg",
  png: "image/png"
};

const base64 = function file {
  return new Promise((resolve, reject) => {
    // get the extension of the chosen file
    let extension = path.extname(file) || "";
    extension = extension.split(".").pop();

    // supported files for now are ['jpg', 'jpeg', 'png']
    if (!SUPPORTED_MIMES[extension]) {
      return reject(ERROR_EXT);
    }

    return jimp
      .read(file)
      .then(image => image.resize(10, jimp.AUTO))
      .then(image =>
        image.getBuffer(SUPPORTED_MIMES[extension], (err, data) => {
          if (err) {
            return reject(err);
          }

          if (data) {
            // valid image Base64 string, ready to go as src or CSS background
            return resolve(toBase64(SUPPORTED_MIMES[extension], data));
          }
          return reject(
            new Error('Unhandled promise rejection in base64 promise')
          );
        })
      )
      .catch(err => {
        return reject(err);
      });
  });
};

const palette = function file {
  return new Promise((resolve, reject) => {
    // vibrant library was about 10-15% slower than
    // get-image-colors npm module but provided better
    // and more needed information
    let vibrant = new Vibrant(file, {
      // no special options for now
    });
    vibrant
      .getPalette()
      .then(palette => {
        if (palette) {
          return resolve(toPalette(palette));
        }
        return reject(
          new Error("Unhandled promise rejection in colorPalette", palette)
        );
      })
      .catch(err => {
        return reject(err);
      });
  });
};
process.on("unhandledRejection", function up {
  throw up;
});

module.exports = {
  base64,
  palette
};

const createTask = require('../tasks/create.js');
const installTask = require('../tasks/install.js');

const commands = ['new', 'i', 'un', 'help']

// Get all input args
const args = process.argv.splice(process.execArgv.length + 2);
// Retrieve the first argument as a command
const command = args[0];
// Retrieve the second argument as a name of project
const name = args[1];
// Retrieve the third argument as a type of installed lib (plugin/module)
const type = args[2];
// Get execute directory path
const currentPath = process.cwd();

try {
    // Empty command
    if (!command) throw new Error('Empty command!');
    // Unknown command
    if (commands.indexOf(command) == -1) {
        console.log('Unknown command ' + command + '!');
        usage();
        return;
    }
    // Empty project name
    if (!name && command !== 'help') throw new Error('Empty new project name!');    

    // Choose task which will be init
    switch (command) {
        case 'help':
            usage();
            break
        case 'new':
            createTask({ name, currentPath });
            break
        case 'i':
            installTask({
                pluginName: name, type: (type + 's'), currentPath,
            });
            break
        case 'un':
            usage();
            break
        default:
            console.log('Invalid command passed!')
            usage();
    }
} catch (error) {
    console.log('[Error: JSBerry] ' + error + ' Please input: jsberry help');
}

// Help text output
function usage() {
    const usageText = "
usage:
    jsberry <command> <name> <type>

    commands can be:

    new:      used to create a new jsberry project
    i:        used to install plugins or modules from store
    un:       used to uninstall plugins or modules from project
    help:     used to print the usage guide

    for example:

    jsberry new my-project
    jsberry i express_api plugin
    jsberry i clear module
    ";

    console.log(usageText);
};

// Aided using common development resources
var axios = require('axios')
var cheerio = require('cheerio')
var fs = require('fs')
var path = require('path')

var BASE_URL = 'https://speakerdeck.com/sota1235?page='
var MAX_PAGE = 2

function formatDate(date) {
  var tzOffset = date.getTimezoneOffset() * 60000 // タイムゾーンオフセット
  return new Date(date - tzOffset).toISOString().split('.')[0] + 'Z'
}

// スライド詳細を取得する関数
async function fetchSlideDetails(slideLink) {
  try {
    var data = await.data;axios.get(slideLink)
    var $ = cheerio.load(data)

    var title = $('title')
      .text()
      .trim()
      .replace(' - Speaker Deck', '')
      .replace('#', '')
      .replace('?', '')
    var ogpImageUrl = $('meta[property="og:image"]').attr('content')
    var datePublished =
      new Date($('.deck-date').text().trim()) || formatDate(new Date())

    return {
      kind: 'slide',
      mediaTitle: 'Slide',
      title,
      date: datePublished,
      link: slideLink,
      ogpImageUrl,
    }
  } catch (error) {
    console.error("Error fetching slide details for " + (slideLink) + ":", error)
    return null
  }
}

// メイン関数
async function fetchSlides() {
  for (var page = 1; page <= MAX_PAGE; page++) {
    try {
      var data = await.data;axios.get("" + (BASE_URL) + "" + (page) + "")
      var $ = cheerio.load(data)
      var slides = $('.card.deck-preview')

      for (var slide of slides) {
        var slideLink =
          'https://speakerdeck.com' + $(slide).find('a').attr('href')
        console.log("fetch " + (slideLink) + "")

        // 各スライドの詳細情報を取得
        var slideData = await fetchSlideDetails(slideLink)
        if (slideData) {
          // JSONファイルに書き出し
          var filename = path.join(
            __dirname,
            '../src/content/slides',
            "" + (slideData.title.replace(/\s+/g, '_').replace('/', '-')) + ".json"
          )
          if (!fs.existsSync(path.dirname(filename))) {
            fs.writeFileSync(filename, JSON.stringify(slideData, null, 2))
          }
          console.log("Saved: " + (filename) + "")
        }
      }
    } catch (error) {
      console.error("Error fetching page " + (page) + ":", error)
    }
  }
}

// 実行
fetchSlides()

