async function getTempFileURLOne(fileID) {
	if (!fileID) return '';

	var cloud = cloudBase.getCloud();
	var result = await cloud.getTempFileURL({
		fileList: [fileID],
	})
	if (result && result.fileList && result.fileList[0] && result.fileList[0].tempFileURL)
		return result.fileList[0].tempFileURL;
	return '';
}

async function getTempFileURL(tempFileList, isValid = false) {
	if (!tempFileList || tempFileList.length == 0) return [];

	var cloud = cloudBase.getCloud();
	var result = await cloud.getTempFileURL({
		fileList: tempFileList,
	})
	console.log(result);

	var list = result.fileList;
	var outList = [];
	for (var i = 0; i < list.length; i++) {
		var pic = {};
		if (list[i].status == 0) {
			//获取到地址的
			pic.url = list[i].tempFileURL;
			pic.cloudId = list[i].fileID;
			outList.push(pic)
		} else {
			//未获取到地址的（已经转换过的)
			if (!isValid) {
				pic.url = list[i].fileID; // fileID为URL, tempFileURL为空
				pic.cloudId = list[i].fileID;
				outList.push(pic)
			}
		}
	}
	return outList;
}

async function handlerCloudFilesForForms(oldForms, newsForms) {
	var oldFiles = [];
	var newFiles = [];

	for (var k = 0; k < oldForms.length; k++) {
		if (oldForms[k].type == 'image')
			oldFiles = oldFiles.concat(oldForms[k].val);
		else if (oldForms[k].type == 'content') {
			var contentVal = oldForms[k].val;
			for (var n in contentVal) {
				if (contentVal[n].type == 'img')
					oldFiles.push(contentVal[n].val);
			}

		}
	}

	for (var j in newsForms) {
		if (newsForms[j].type == 'image')
			newFiles = newFiles.concat(newsForms[j].val);
		else if (newsForms[j].type == 'content') {
			var contentVal = newsForms[j].val;
			for (var m in contentVal) {
				if (contentVal[m].type == 'img')
					newFiles.push(contentVal[m].val);
			}

		}
	}

	await handlerCloudFiles(oldFiles, newFiles);
}

async function handlerCloudFiles(oldFiles, newFiles) {
	//if (oldFiles.length == 0 && newFiles.length == 0) return [];

	var cloud = cloudBase.getCloud();
	for (var i = 0; i < oldFiles.length; i++) {
		var isDel = true;
		for (var j = 0; j < newFiles.length; j++) {
			if (oldFiles[i] == newFiles[j]) {
				// 从旧文件数组里 找到 新组 还存在的文件 ，则不删除
				isDel = false;
				break;
			}
		}
		// 新组里不存在，直接删除
		if (isDel && oldFiles[i]) {
			var result = await cloud.deleteFile({
				fileList: [oldFiles[i]],
			});
			console.log(result);
		}

	}

	return newFiles;
}


async function handlerCloudFilesByRichEditor(oldFiles, newFiles) {
	var cloud = cloudBase.getCloud();
	for (var i = 0; i < oldFiles.length; i++) {
		var isDel = true;
		for (var j = 0; j < newFiles.length; j++) {
			if (oldFiles[i].type == 'img' && newFiles[j].type == 'img' && oldFiles[i].val == newFiles[j].val) {
				// 从旧文件数组里 找到 新组 还存在的图片文件, 保存cloudID
				//newFiles[j].cloudId = oldFiles[i].cloudId;
				isDel = false;
				break;
			}
		}
		// 新组里不存在，直接删除
		if (isDel && oldFiles[i].type == 'img' && oldFiles[i].val) {

			var result = await cloud.deleteFile({
				fileList: [oldFiles[i].val],
			});
		}

	}

	return newFiles;
}

async function deleteFiles(list) {
	if (!list) return;
	if (!Array.isArray(list)) list = [list];
	if (list.length == 0) return;

	var cloud = cloudBase.getCloud();
	await cloud.deleteFile({
		fileList: list,
	});
}

module.exports = {
	log,
	getTempFileURL,
	getTempFileURLOne,
	deleteFiles,
	handlerCloudFiles,
	handlerCloudFilesByRichEditor,
	handlerCloudFilesForForms
}

// see https://github.com/deleteman/jsx-parser/blob/main/index.js

// here and below Penned via standard programming aids and slightly modified

function jsxToHtml2(jsx) {
	// Define the list of common HTML tags
	const commonTags = ['a', 'abbr', 'address', 'area', 'article', 'aside', 'audio', 'b', 'base', 'bdi', 'bdo', 'blockquote', 'body', 'br', 'button', 'canvas', 'caption', 'cite', 'code', 'col', 'colgroup', 'data', 'datalist', 'dd', 'del', 'details', 'dfn', 'dialog', 'div', 'dl', 'dt', 'em', 'embed', 'fieldset', 'figcaption', 'figure', 'footer', 'form', 'h1', 'h2', 'h3', 'h4', 'h5', 'h6', 'head', 'header', 'hgroup', 'hr', 'html', 'i', 'iframe', 'img', 'input', 'ins', 'kbd', 'label', 'legend', 'li', 'link', 'main', 'map', 'mark', 'meta', 'meter', 'nav', 'noscript', 'object', 'ol', 'optgroup', 'option', 'output', 'p', 'param', 'picture', 'pre', 'progress', 'q', 'rp', 'rt', 'ruby', 's', 'samp', 'script', 'section', 'select', 'small', 'source', 'span', 'strong', 'style', 'sub', 'summary', 'sup', 'table', 'tbody', 'td', 'template', 'textarea', 'tfoot', 'th', 'thead', 'time', 'title', 'tr', 'track', 'u', 'ul', 'var', 'video', 'wbr'];

	// Replace JSX tags with HTML elements and JavaScript expressions
	const html = jsx.replace(/<(\w+)\s*([^>]*)\/?>/g, function (match, tag, attrs) {
		// If the tag is not a common HTML tag, return the original match
		if (!commonTags.includes(tag)) {
			return match;
		}

		// Build the HTML tag with attributes
		let htmlTag = "<" + (tag) + "";
		if (attrs) {
			htmlTag += " " + (attrs) + "";
		}

		// If the tag is a self-closing tag, return the HTML tag
		if (match.endsWith('/>')) {
			return "" + (htmlTag) + "/>";
		}

		// Otherwise, parse the JSX code inside the tag
		const jsxCode = match.slice(tag.length + 2, -1);
		const jsCode = jsxCode.replace(/\{(.*?)\}/g, (_, code) => {
			return "(" + (code) + ")";
		});

		// Build the HTML tag with the parsed JSX code
		return "" + (htmlTag) + ">" + (eval(jsCode)) + "</" + (tag) + ">";
	});

	return html;
}

function jsxToHtml(jsx) {
	// Define the list of common HTML tags
	const commonTags = ['a', 'abbr', 'address', 'area', 'article', 'aside', 'audio', 'b', 'base', 'bdi', 'bdo', 'blockquote', 'body', 'br', 'button', 'canvas', 'caption', 'cite', 'code', 'col', 'colgroup', 'data', 'datalist', 'dd', 'del', 'details', 'dfn', 'dialog', 'div', 'dl', 'dt', 'em', 'embed', 'fieldset', 'figcaption', 'figure', 'footer', 'form', 'h1', 'h2', 'h3', 'h4', 'h5', 'h6', 'head', 'header', 'hgroup', 'hr', 'html', 'i', 'iframe', 'img', 'input', 'ins', 'kbd', 'label', 'legend', 'li', 'link', 'main', 'map', 'mark', 'meta', 'meter', 'nav', 'noscript', 'object', 'ol', 'optgroup', 'option', 'output', 'p', 'param', 'picture', 'pre', 'progress', 'q', 'rp', 'rt', 'ruby', 's', 'samp', 'script', 'section', 'select', 'small', 'source', 'span', 'strong', 'style', 'sub', 'summary', 'sup', 'table', 'tbody', 'td', 'template', 'textarea', 'tfoot', 'th', 'thead', 'time', 'title', 'tr', 'track', 'u', 'ul', 'var', 'video', 'wbr'];


	// Replace JSX tags with HTML elements and JavaScript expressions
	const html = jsx.replace(/<(\w+)([^>]*)>((.|\n)*?)<\/\1>/gm, function (match, tag, props, content) {
		console.log({ match, tag, props, content })
		// If the tag is not a common HTML tag, return the original match
		if (!commonTags.includes(tag)) {
			return match;
		}

		// Replace props with HTML attributes
		const attributes = props.replace(/\s*(\w+)\s*=\s*\{([^}]+)\}/g, function (match, name, expression) {
			console.log("attributes", expression)
			return "" + (name) + '="' + (eval('(' + expression + ")()")) + '"';
		});

		// Replace JavaScript expressions and code with their values
		const replacedContent = content.replace(/\{([^}]+)\}/g, function (match, expression) {
			console.log("replacedContent", expression)
			return eval('(' + expression + ")()");
		});

