// function Aided using common development resources
document.addEventListener("DOMContentLoaded", function () {
    var button = document.getElementById("scrollBtn");
    var scrollContainer = document.querySelector(".content-body")

    if (!scrollContainer) return;

    scrollContainer.addEventListener("scroll", scrollAppear);
    window.addEventListener("resize", scrollAppear);

    function scrollAppear() {
        if (window.innerWidth < 900) {
            button.style.display = "none";
            return;
        }

        if (scrollContainer.scrollTop > 175) {
            button.style.display = "block";   
        } else {
            button.style.display = "none";
        }
    }

    window.scrollToTop = function () {
        scrollContainer.scrollTo({top: 0,  beahviour: 'smooth'});
    }
});

const express = require('express');
const router = express.Router();
const validUrl = require('valid-url');
const shortid = require('shortid');
const config = require('config');

const Url = require('../models/Url');

// @route     POST /api/url/shorten
// @desc      Create short URL
router.post('/shorten', async function (req, res) {
  var longUrl = req.body.longUrl;
  const baseUrl = config.get('baseUrl');

  // Check base url
  if (!validUrl.isUri(baseUrl)) {
    return res.status(401).json('Invalid base url');
  }

  // Create url code
  const urlCode = shortid.generate();

  // Check long url
  if (validUrl.isUri(longUrl)) {
    try {
      let url = await Url.findOne({ longUrl });

      if (url) {
        res.json(url);
      } else {
        const shortUrl = baseUrl + '/' + urlCode;

        url = new Url({
          longUrl,
          shortUrl,
          urlCode,
          date: new Date()
        });

        await url.save();

        res.json(url);
      }
    } catch (err) {
      console.error(err);
      res.status(500).json('Server error');
    }
  } else {
    res.status(401).json('Invalid long url');
  }
});

module.exports = router;

var fs = require('fs');
var find = require('./service/findFiles.js');
var read = require('./service/readFile.js');
