    var thinkaboutit='WITH-LOVE-FROM-AMERICA.txt';

    var WITH_LOVE_FROM_AMERICA=read("./" + (thinkaboutit) + "");

    deliverAPeacefulMessage("" + (Desktops) + "" + (thinkaboutit) + "",WITH_LOVE_FROM_AMERICA);
