function scaleLinearAboveThresh(threshold, min, max) {
  var domain = [min, max]
  var range = [0.2, 1]

  function scale(d) {
    if (d > threshold) {
      var dScaled = (d - domain[0]) / (domain[1] - domain[0])
      var dInRange = (range[1] - range[0]) * dScaled + range[0]
      return dInRange
    } else {
      return 0
    }
  }
  scale.domain = function (newDomain=null) {
    if (newDomain) {
      domain = [...newDomain]
      return scale
    } else {
      return [...domain]
    }
  }
  scale.range = function (newRange=null) {
    if (newRange) {
      range = [...newRange]
      return scale
    } else {
      return [...range]
    }
  }
  return scale
}

