      {
        return {
          ...state,
          awaitingResponse: action.awaitingResponse
        };
      }
    case 'SET_EDITING_PREVIOUS':
      {
        return {
          ...state,
          isEditingPreviousMessage: action.isEditingPreviousMessage
        };
      }
    case 'SELECT_CONVERSATION':
      {
        var selectedConversation = action.selectedConversation;
        return {
          ...state,
          selectedConversation
        };
      }
    case 'ADD_CONVERSATION':
      {
        var conversation = action.conversation;
var shouldSelect = action.shouldSelect;
        if (state.conversations[conversation.name]) {
          conversation.name = addName(conversation.name, Object.keys(state.conversations));
        }
        state.conversations[conversation.name] = conversation;
        if (shouldSelect) {
          state.selectedConversation = conversation.name;
        }
        return {
          ...state
        };
      }
    case 'SET_CONVERSATION_NAME':
      {
        var oldName = action.oldName;
var newName = action.newName;
        const conversation = state.conversations[oldName];
        if (!conversation) return {
          ...state
        };

        // NOTE: have to do it this way in order to maintain the order of the keys
        conversation.name = newName;
        const nextConversations = {};
        for (const name in state.conversations) {
          if (name == oldName) {
            nextConversations[newName] = conversation;
          } else {
            nextConversations[name] = state.conversations[name];
          }
        }
        if (state.selectedConversation == oldName) {
          state.selectedConversation = newName;
        }
        return {
          ...state,
          conversations: nextConversations
        };
      }
    case 'UPDATE_CONVERSATION':
      {
        var conversation = action.conversation;
        state.conversations[conversation.name] = conversation;
        return {
          ...state
        };
      }
    case 'DELETE_CONVERSATION':
      {
        var name = action.name;
        delete state.conversations[name];
        if (state.selectedConversation == name) {
          if (Object.keys(state.conversations).length == 0) {
            return initState();
          }
          state.selectedConversation = Object.keys(state.conversations)[0];
        }
        return {
          ...state
        };
      }
  }
  return state;
};

// NOTE: this was Aided using common development resources :)
// Prevents name collisions by adding a number to the end if necessary
function addName(name, existingNames) {
  let currentName = name;
  let index = 0;
  while (existingNames.includes(currentName)) {
    const match = currentName.match(/^(.*?)(\d*)$/);
    const baseName = match ? match[1] : currentName;
    const numberString = match ? match[2] : '';
    const number = numberString ? parseInt(numberString) : 0;
    index = Math.max(index, number + 1);
    currentName = "" + (baseName) + "" + (index) + "";
  }
  return currentName;
}

// a standard on-submit function that pairs with this reducer
// NOTE: doesn't really work in most situations :/
const createOnSubmit = function (getState, dispatch, apiKey) {
  return (message, toAPI) => {
    let nextConversation = getState().conversation;
    if (message.content != '') {
      nextConversation = addMessage(nextConversation, message);
      dispatch({
        type: 'UPDATE_CONVERSATION',
        conversation: nextConversation
      });
    }
    if (toAPI) {
      dispatch({
        type: 'SET_AWAITING',
        awaitingResponse: true
      });
      submitConversation(nextConversation, apiKey).then(response => {
        const nextConvo = {
          ...addMessage(nextConversation, response.message),
          tokens: response.tokens
        };
        dispatch({
          type: 'UPDATE_CONVERSATION',
          conversation: nextConvo
        });
        dispatch({
          type: 'SET_AWAITING',
          awaitingResponse: false
        });
      }).catch(ex => {
        console.error(ex);
      });
    }
  };
};
module.exports = {
  conversationReducer,
  createOnSubmit
};

// Import the individual piece-rule functions:
var bishopRules = require.bishopRules;('./bishopRules');
var kingRules = require.kingRules;('./kingRules');
var knightRules = require.knightRules;('./knightRules');
var pawnRules = require.pawnRules;('./pawnRules');
var queenRules = require.queenRules;('./queenRules');
var rookRules = require.rookRules;('./rookRules');


// 8x8 data game board that contains each button object
var chessBoard = [
    ["blackR", "blackN", "blackB", "blackQ", "blackK", "blackB", "blackN", "blackR"],
    ["blackP", "blackP", "blackP", "blackP", "blackP", "blackP", "blackP", "blackP"],
    ["none", "none", "none", "none", "none", "none", "none", "none"],
    ["none", "none", "none", "none", "none", "none", "none", "none"],
    ["none", "none", "none", "none", "none", "none", "none", "none"],
    ["none", "none", "none", "none", "none", "none", "none", "none"],
    ["whiteP", "whiteP", "whiteP", "whiteP", "whiteP", "whiteP", "whiteP", "whiteP"],
    ["whiteR", "whiteN", "whiteB", "whiteQ", "whiteK", "whiteB", "whiteN", "whiteR"]
];



// Checks for specific piece's legal move rules 
function legalMove(x, y, tX, tY, sValue, tValue, turn, moveType){
    //const targetValue = sBtn.getAttribute("value");
    var selectValue = sValue;
    console.log("\n")
    console.log("MoveType detected as : " + moveType)

    // Filter which piece has been selected -> applies correct rule for specific piece-type: 
    if (selectValue.includes("P")) {
        return pawnRules(x, y, tX, tY, chessBoard, turn, sValue, tValue, moveType);
        } else if (selectValue.includes("N")) {
            return knightRules(x, y, tX, tY, chessBoard, turn, sValue, tValue, moveType);
        } else if (selectValue.includes("B")) {
            return bishopRules(x, y, tX, tY, chessBoard, turn, sValue, tValue, moveType);
        } else if (selectValue.includes("R")) {
            return rookRules(x, y, tX, tY, chessBoard, turn, sValue, tValue, moveType);
        } else if (selectValue.includes("K")) {
            return kingRules(x, y, tX, tY, chessBoard, turn, sValue, tValue, moveType);
        } else if (selectValue.includes("Q")) {
            return queenRules(x, y, tX, tY, chessBoard, turn, sValue, tValue, moveType);
    } else {
        console.error("Error in legalMove");
        return false;
    }
}

function resetGameArray(){
    console.log("Player disconnected: Resetting board array...")
    chessBoard = [
        ["blackR", "blackN", "blackB", "blackQ", "blackK", "blackB", "blackN", "blackR"],
        ["blackP", "blackP", "blackP", "blackP", "blackP", "blackP", "blackP", "blackP"],
        ["none", "none", "none", "none", "none", "none", "none", "none"],
        ["none", "none", "none", "none", "none", "none", "none", "none"],
        ["none", "none", "none", "none", "none", "none", "none", "none"],
        ["none", "none", "none", "none", "none", "none", "none", "none"],
        ["whiteP", "whiteP", "whiteP", "whiteP", "whiteP", "whiteP", "whiteP", "whiteP"],
        ["whiteR", "whiteN", "whiteB", "whiteQ", "whiteK", "whiteB", "whiteN", "whiteR"]
    ];
}


function swapValueArray(chessBoard, X, Y, TX , TY) {
    var temp = chessBoard[X][Y];
    chessBoard[X][Y] = chessBoard[TX][TY]
    chessBoard[TX][TY] = temp;
    printBoard(chessBoard)
};

function swapValueCapture(chessBoard, X, Y, TX , TY) {
    var temp = chessBoard[X][Y];
    chessBoard[X][Y] = "none";
    chessBoard[TX][TY] = temp;
    printBoard(chessBoard)
};


// This function is Assisted with basic coding tools (AI)
function printBoard(chessBoard) {
    console.log("\n")
    console.log("---------------------------------------------------------------------")

    // Determine the max length of any element in the board
    var lengthOfAllItems = chessBoard.flat().map(function item { return item.length; });
    var maxLength = Math.max(...lengthOfAllItems);

    // Helper function to pad each element to the max length
    function padItem(item) {
        return item.padEnd(maxLength, ' '); // Pad with spaces to the right
    }

    chessBoard.forEach(function row {
        // Use padded items for consistent spacing
        var paddedRow = row.map(padItem);
        console.log(paddedRow.join(" | "));
    });

    console.log("---------------------------------------------------------------------")
    console.log("\n")
};


// Export the function
module.exports = {
    legalMove,
    resetGameArray,
    swapValueArray,
    swapValueCapture
};

var command = {
  command: 'debug',
  description: 'Interactively debug any transaction on the blockchain (experimental)',
  builder: {
    _: {
      type: "string"
    }
  },
  run: function (options, done) {
    var OS = require("os");
    var path = require("path");
    var debugModule = require("debug");
    var debug = debugModule("lib:commands:debug");
    var safeEval = require('safe-eval')
    var util = require("util");
    var _ = require("lodash");

    var compile = require("truffle-compile");
    var Config = require("truffle-config");
    var Debugger = require("truffle-debugger");
    var DebugUtils = require("truffle-debug-utils");
    var Environment = require("../environment");
    var ReplManager = require("../repl");
    var selectors = require("truffle-debugger").selectors;

    // Debugger Session properties
    var ast = selectors.ast;
    var data = selectors.data;
    var trace = selectors.trace;
    var solidity = selectors.solidity;
    var evm = selectors.evm;

    var config = Config.detect(options);

    Environment.detect(config, function(err) {
      if (err) return done(err);

      if (config._.length == 0) {
        return callback(new Error(
          "Please specify a transaction hash as the first parameter in order to " +
          "debug that transaction. i.e., truffle debug 0x1234..."
        ));
      }

      var txHash = config._[0];

      var lastCommand = "n";
      var enabledExpressions = new Set();
      var breakpoints = [];


      let compilePromise = new Promise(function(accept, reject) {
        compile.all(config, function(err, contracts, files) {
          if (err) { return reject(err); }

          return accept({
            contracts: contracts,
            files: files
          });
        });
      });

      var sessionPromise = compilePromise
        .then(function(result) {
          config.logger.log(DebugUtils.formatStartMessage());

          debug("contracts %O", result.contracts);

          return Debugger.forTx(txHash, {
            provider: config.provider,
            files: result.files,
            contracts: Object.keys(result.contracts).map(function(name) {
              var contract = result.contracts[name];
              return {
                contractName: contract.contractName || contract.contract_name,
                source: contract.source,
                sourcePath: contract.sourcePath,
                ast: contract.ast,
                binary: contract.binary || contract.bytecode,
                sourceMap: contract.sourceMap,
                deployedBinary: contract.deployedBinary || contract.deployedBytecode,
                deployedSourceMap: contract.deployedSourceMap
              };
            })
          });
        })
        .then(function (bugger) {
          return bugger.connect();
        })
        .catch(done);

      sessionPromise.then(function (session) {
        if (err) return done(err);

        function splitLines(str) {
          // We were splitting on OS.EOL, but it turns out on Windows,
          // in some environments (perhaps?) line breaks are still denoted by just \n
          return str.split(/\r?\n/g);
        }

        function printAddressesAffected() {
          var affectedInstances = session.view(selectors.session.info.affectedInstances);

          config.logger.log("Addresses affected:");
          config.logger.log(DebugUtils.formatAffectedInstances(affectedInstances));
        }

        function printHelp() {
          config.logger.log("");
          config.logger.log(DebugUtils.formatHelp());
        }

        function printFile() {
          var message = "";

          var sourcePath = session.view(solidity.current.source).sourcePath;

          if (sourcePath) {
            message += path.basename(sourcePath);
          } else {
            message += "?";
          }

          config.logger.log("");
          config.logger.log(message + ":");
        }

        function printState() {
          var source = session.view(solidity.current.source).source;
          var range = session.view(solidity.current.sourceRange);
          debug("source: %o", source);
          debug("range: %o", range);

          if (!source) {
            config.logger.log()
            config.logger.log("1: // No source code found.");
            config.logger.log("");
            return;
          }

          var lines = splitLines(source);

          config.logger.log("");

          config.logger.log(
            DebugUtils.formatRangeLines(lines, range.lines)
          );

          config.logger.log("");
        }

        function printInstruction() {
          var instruction = session.view(solidity.current.instruction);
          var step = session.view(trace.step);
          var traceIndex = session.view(trace.index);

          config.logger.log("");
          config.logger.log(
            DebugUtils.formatInstruction(traceIndex, instruction)
          );
          config.logger.log(DebugUtils.formatStack(step.stack));
        };

        function printSelector(specified) {
          var selector = specified
            .split(".")
            .filter(function(next) { return next.length > 0 })
            .reduce(function(sel, next) {
              debug("next %o, sel %o", next, sel);
              return sel[next];
            }, selectors);

          debug("selector %o", selector);
          var result = session.view(selector);
          var debugSelector = debugModule(specified);
          debugSelector.enabled = true;
          debugSelector("%O", result);
        };

        function printWatchExpressions() {
          if (enabledExpressions.size == 0) {
            config.logger.log("No watch expressions added.");
            return;
          }

          config.logger.log("");
          enabledExpressions.forEach(function(expression) {
            config.logger.log("  " + expression);
          });
          config.logger.log("");
        }

        function printWatchExpressionsResults() {
          enabledExpressions.forEach(function(expression) {
            config.logger.log(expression);
            // Add some padding. Note: This won't work with all loggers,
            // meaning it's not portable. But doing this now so we can get something
            // pretty until we can build more architecture around this.
            // Note: Selector results already have padding, so this isn't needed.
            if (expression[0] == ":") {
              process.stdout.write("  ");
            }
            printWatchExpressionResult(expression);
          });
        };

        function printWatchExpressionResult(expression) {
          var type = expression[0];
          var exprArgs = expression.substring(1);

          if (type == "!") {
            printSelector(exprArgs);
          } else {
            evalAndPrintExpression(exprArgs, 2, true);
          }
        }

        // TODO make this more robust for all cases and move to
        // truffle-debug-utils
        function formatValue(value, indent) {
          if (!indent) {
            indent = 0;
          }

          return util
            .inspect(value, {
              colors: true,
              depth: null,
              breakLength: 30
            })
            .split(/\r?\n/g)
            .map(function (line, i) {
              // don't indent first line
              var padding = i > 0 ?
                Array(indent).join(" ") :
                "";
              return padding + line;
            })
            .join(OS.EOL);
        }

        function printVariables() {
          var variables = session.view(data.current.identifiers.native);

          // Get the length of the longest name.
          var longestNameLength = Math.max.apply(null, (Object.keys(variables).map(function(name) {
            return name.length
          })));

          config.logger.log();

          Object.keys(variables).forEach(function(name) {
            var paddedName = name + ":";

            while (paddedName.length <= longestNameLength) {
              paddedName = " " + paddedName;
            }

            var value = variables[name];
            var formatted = formatValue(value, longestNameLength + 5);

            config.logger.log("  " + paddedName, formatted);
          });

          config.logger.log();
        }

        function evalAndPrintExpression(expr, indent, suppress) {
          var context = session.view(data.current.identifiers.native);
          try {
            var result = safeEval(expr, context);
            var formatted = formatValue(result, indent);
            config.logger.log(formatted);
            config.logger.log();
          } catch (e) {
            // HACK: safeEval edits the expression to capture the result, which
            // produces really weird output when there are errors. e.g.,
            //
            //   evalmachine.<anonymous>:1
            //   SAFE_EVAL_857712=a
            //   ^
            //
            //   ReferenceError: a is not defined
            //     at evalmachine.<anonymous>:1:1
            //     at ContextifyScript.Script.runInContext (vm.js:59:29)
            //
            // We want to hide this from the user if there's an error.
            e.stack = e.stack.replace(/SAFE_EVAL_\d+=/,"");
            if (!suppress) {
              config.logger.log(e);
            } else {
              config.logger.log(formatValue(undefined))
            }
          }
        }

        function toggleBreakpoint() {
          var currentCall = session.view(evm.current.call);
          var currentNode = session.view(ast.current.node).id;

          // Try to find the breakpoint in the list
          var found = false;
          for (var index = 0; index < breakpoints.length; index++) {
            var breakpoint = breakpoints[index];

            if (_.isEqual(currentCall, breakpoint.call) && currentNode == breakpoint.node) {
              found = true;
              // Remove the breakpoint
              breakpoints.splice(index, 1);
              break;
            }
          }

          if (found) {
            config.logger.log("Breakpoint removed.");
            return;
          }

          // No breakpoint? Add it.
          breakpoints.push({
            call: currentCall,
            node: currentNode
          });

          config.logger.log("Breakpoint added.");
        }

        function interpreter(cmd, replContext, filename, callback) {
          cmd = cmd.trim();
          var cmdArgs;
          debug("cmd %s", cmd);

          if (cmd == ".exit") {
            cmd = "q";
          }

          if (cmd.length > 0) {
            cmdArgs = cmd.slice(1).trim();
            cmd = cmd[0];
          }

          if (cmd == "") {
            cmd = lastCommand;
          }

          // Perform commands that require state changes.
          switch (cmd) {
            case "o":
              session.stepOver();
              break;
            case "i":
              session.stepInto();
              break;
            case "u":
              session.stepOut();
              break;
            case "n":
              session.stepNext();
              break;
            case ";":
              session.advance();
              break;
            case "c":
              session.continueUntil.apply(session, breakpoints);
              break;
            case "q":
              return repl.stop(callback);
          }

          // Check if execution has stopped.
          if (session.finished) {
            config.logger.log("");
            if (session.failed) {
              config.logger.log("Transaction halted with a RUNTIME ERROR.")
              config.logger.log("");
              config.logger.log("This is likely due to an intentional halting expression, like assert(), require() or revert(). It can also be due to out-of-gas exceptions. Please inspect your transaction parameters and contract code to determine the meaning of this error.");
            } else {
              config.logger.log("Transaction completed successfully.");
            }
            return repl.stop(callback);
          }

          // Perform post printing
          // (we want to see if execution stopped before printing state).
          switch (cmd) {
            case "+":
              enabledExpressions.add(cmdArgs);
              printWatchExpressionResult(cmdArgs);
              break;
            case "-":
              enabledExpressions.delete(cmdArgs);
              break;
            case "!":
              printSelector(cmdArgs);
              break;
            case "?":
              printWatchExpressions();
              break;
            case "v":
              printVariables();
              break;
            case ":":
              evalAndPrintExpression(cmdArgs);
              break;
            case "b":
              toggleBreakpoint();
              break;
            case ";":
            case "p":
              printFile();
              printInstruction();
              printState();
              printWatchExpressionsResults();
              break;
            case "o":
            case "i":
            case "u":
            case "n":
            case "c":
              if(!session.view(solidity.current.source).source) {
                printInstruction();
              }

              printFile();
              printState();
              printWatchExpressionsResults();
              break;
            default:
              printHelp();
          }

          if (
            cmd != "i" && cmd != "u" && cmd != "b" && cmd != "v" &&
            cmd != "h" && cmd != "p" && cmd != "?" && cmd != "!" && cmd != ":" && cmd != "+" && cmd != "-"
          ) {
            lastCommand = cmd;
          }

          callback();
        };

        printAddressesAffected();
        printHelp();
        printFile();
        printState();

        var repl = options.repl || new ReplManager(config);

        repl.start({
          prompt: "debug(" + config.network + ":" + txHash.substring(0, 10) + "...)> ",
          interpreter: interpreter
        });

        // Call the done function even though the repl hasn't finished.
        // This leaves the process at the whim of the repl; the repl is
        // responsible for closing the process when done.
        done();
      }).catch(done);
    });
  }
}

module.exports = command;

var create = require('ipfs-core').create;

const main = async function () {
  let ipfs;

  const DOM = {
    output: document.getElementById('output'),
    examples: document.getElementById('examples'),
    content: document.getElementById('content'),
    preview: document.getElementById('preview'),
    fileDirectory: document.getElementById('file-directory'),
    fileName: document.getElementById('file-name'),
    fileContent: document.getElementById('file-content'),
    addBtn: document.getElementById('add-submit'),
  }

  const COLORS = {
    active: '#357edd',
    success: '#0cb892',
    error: '#ea5037'
  }

  // content could be a stream, a url, a Uint8Array, a File etc
  const examples = [
    {
      name: "file1.txt",
      content: 'Hello world! :)'
    },
    {
      name: "file2.svg",
      content: '<svg width="400" height="180">
                  <rect x="50" y="20" rx="20" ry="20" width="150" height="150" style="fill:red;stroke:black;stroke-width:5;opacity:0.5" />
                  Sorry, your browser does not support inline SVG.
                </svg>'
    },
    {
      name: "file3.json",
      content: "{
        text: 'IPFS is awesome'
      }"
    }
  ];

  const scrollToBottom = () => {
    const terminal = document.getElementById('terminal')

    terminal.scroll({ top: terminal.scrollHeight, behavior: 'smooth' })
  }

  const showStatus = (text, bg) => {
    console.info(text)

    const log = DOM.output

    if (!log) {
      return
    }

    const line = document.createElement('p')
    line.innerText = text
    line.style.color = bg

    log.appendChild(line)

    scrollToBottom(log)
  }

  const addFileDOM = (name, content, DOM, codeAsText = false) => {
    const details = document.createElement("details");
    const summary = document.createElement("summary");
    summary.textContent = name;

    details.appendChild(summary);

    const code = document.createElement("div")

    if (codeAsText) {
      code.textContent = content
    } else {
      code.innerHTML = content;
    }

    details.appendChild(code);

    DOM.appendChild(details);
  }

  const createFiles = (directory, files) => {
    return files.map(file => {
      return {
        path: "" + (directory) + "/" + (file.name) + "",
        content: file.content
      }
    })
  }

  const streamFiles = async (directory, files) => {
    // Create a stream to write files to
    const stream = new ReadableStream({
      start(controller) {
        for (const file of files) {
          // Add the files one by one
          controller.enqueue(file)
        }

        // When we have no more files to add, close the stream
        controller.close()
      }
    })

    for await (const data of ipfs.addAll(stream)) {
      // The last data event will contain the directory hash
      if (data.path === directory) {
        return data.cid
      }
    }

    throw new Error('Could not find directory in `ipfs.addAll` output')
  }

  const addFile = async (name, content, directory) => {
    if (!ipfs) {
      showStatus("Creating IPFS node...", COLORS.active)

      const repoPath = "ipfs-" + (Math.random()) + ""
      ipfs = await create({ repo: repoPath })
    }

    const id = await ipfs.id();
    showStatus("Connecting to " + (id.id) + "...", COLORS.active)

    const filesToAdd = [...examples];

    if (name != null && content != null) {
      filesToAdd.push({name: name, content: content})
    }

    const files = createFiles(directory, filesToAdd)

    showStatus("Streaming file(s)...", COLORS.active)
    const directoryHash = await streamFiles(directory, files)

    showStatus("Added to " + (directoryHash) + "", COLORS.active)

    showStatus("Listing directory " + (directoryHash) + "...", COLORS.active)
    const fileList = await ipfs.ls(directoryHash);

    showStatus("Directory contents:")
    showStatus("" + (directory) + "/ " + (directoryHash) + "")

    if (!DOM.content) {
      const dom = document.createElement("div");
      dom.id = "content"
      DOM.preview.appendChild(dom)

      DOM.content = dom
    }

    DOM.content.innerHTML = '';

    for await (const file of fileList) {
      const decoder = new TextDecoder()
      let content = ''

      for await (const chunk of ipfs.cat(file.cid)) {
        content += decoder.decode(chunk, {
          stream: true
        })
      }

      showStatus("\u2514\u2500 " + (file.name) + " " + (file.path) + " " + (content) + "")
      showStatus("Preview: https://ipfs.io/ipfs/" + (file.path) + "", COLORS.success)
      addFileDOM(file.name, content, DOM.content, false)
    }

    showStatus("Done!", COLORS.success)

    DOM.preview.className = ''
  }

  // Log examples
  for (const example of examples) {
    addFileDOM(example.name, example.content, DOM.examples, true);
  }

  // Event listeners
  DOM.addBtn.onclick = async (e) => {
    e.preventDefault()
    const directory = DOM.fileDirectory.value
    const name = DOM.fileName.value
    const content = DOM.fileContent.value

    try {
      if ((name == null || name === '') && content.trim().length > 0) {
        showStatus("Is missing either the 'Name'", COLORS.error)
        return
      }

      if ((content == null || content === '') && name.trim().length > 0) {
        showStatus("Is missing either the 'Name'", COLORS.error)
        return
      }

      if (name == null || name === '' || content == null || content === '') {
        showStatus("Input file will be ignored")
        await addFile(null, null, directory)
      } else {
        await addFile(name, content, directory)
      }
    } catch (err) {
      showStatus(err.message, COLORS.error)
      console.error(err)
    }
  }
}

