    console.log("decoded token in modules" + req.user.role + " " + req.user.school_id);
  });

  let schoolId = req.get('schoolid');

  // 2) If no header, try the logged‑in user
  if (!schoolId && req.user) {
    schoolId = String(req.user.school_id);
  }

