  if (!schoolId) {
    return res.status(400).json({ error: 'Missing schoolid header and no authenticated user' });
  }
  const query = "
  SELECT 
    m.module_id,
    m.module_name,
    m.module_date,
    m.module_start_time,
    m.module_end_time,
    m.course_id,
    m.teacher_id,
    c.course_name,
    c.school_id
  FROM modules m
  LEFT JOIN courses c ON m.course_id = c.course_id
  WHERE c.school_id = ?
";


  db.query(query,[schoolId], (err, results) => {
