function testRunner(totalTests) {
  totalTests -= 1; // remove one for the main test runner
  var count = -1;

  return function (go, test) {
    if (!go) {
      return;
    }

    if (test != null) {
      count += 1;
      test();
    }
    else {
      console.log("");
      console.log("");

      if (count === totalTests) {
        console.log("All tests were executed.");
      }
      else {
        console.log((totalTests - count) + " of " + totalTests + " tests were not executed.");
      }
    }
  }
}

var fs = require('fs-extra');
var resolveApp = require('./utils/path').resolveApp;
var merge = require('lodash.merge');
var parseArgs = require('minimist');
var cosmiconfig = require('cosmiconfig');
var log = require('./utils/logger').configLogger;
var printLines = require('./utils/logger').printLines;

function run(runners = [], value, extra) {
  if (!Array.isArray(runners)) {
    runners = [runners];
  }

  runners.forEach(function runner {
    value = runner(value, extra);
  });

  return value;
}

function getOptions(rawArgs, env = null) {
  const childPackage = fs.readJsonSync(resolveApp("package.json"));

  const types = {
    srcDirectory: {
      type: String,
      default: "src"
    },
    distDirectory: {
      type: String,
      default: "dist"
    },
    languages: {
      type: Array,
      subtype: String,
      default: ["javascript"]
    },
    bundles: {
      type: Array,
      subtype: Object,
      default: function ({ options: { languages } }) { return [
        {
          entry: [
            "index." +
              (languages.length === 1 && languages[0] === "typescript"
                ? "ts"
                : "js")
          ],
          output: "index.js"
        }
      ]; },
      run: function bundles { return bundles.map(bundle => ({
          ...bundle,
          entry: Array.isArray(bundle.entry) ? bundle.entry : [bundle.entry]
        })); }},
    startFile: {
      type: String,
      default: function ({ options, childPackage }) { return resolveApp(
          childPackage.main ? "" : options.distDirectory,
          childPackage.main || options.bundles[0].output
        ); },
      run: function (startFile, { options }) { return resolveApp(options.distDirectory, startFile); }},
    shebang: {
      type: Boolean,
      default: function ({ childPackage }) { return childPackage.bin !== undefined; }},
    sourcemap: {
      type: Boolean,
      default: true
    },
    runOnWatch: {
      type: Boolean,
      default: true
    },
    minify: {
      type: Boolean,
      default: false
    },
    includeExternal: {
      type: Boolean,
      default: false
    },
    name: {
      type: String,
      default: function ({ childPackage }) { return childPackage.name; }},
    buildThreads: {
      type: Number,
      integer: true,
      min: 1,
      default: 3
    },
    static: {
      type: Object,
      default: {}
    },
    globals: {
      type: Object,
      default: {}
    },
    targets: {
      type: Object,
      default: {
        node: true
      }
    },
    debug: {
      type: Boolean,
      default: false
    },
    babel: {
      type: Object,
      default: {}
    },
    inspect: {
      type: Boolean,
      default: false
    },
    inspectChrome: {
      type: Number,
      default: false
    },
    target: {
      type: String,
      default: "node",
      choices: ["node", "web"]
    },
    runtime: {
      type: String,
      default: function ({ childPackage }) { return Object.keys(childPackage.dependencies || {}).includes(
          "@noderize/runtime"
        )
          ? "noderize"
          : "include"; },
      choices: ["noderize", "include", "polyfill", "none"]
    },
    env: {
      type: Object,
      default: {
        production: {
          sourcemap: false,
          targets: {}
        },
        test: {},
        development: {}
      },
      merge: true,
      notArg: true
    }
  };

  const boleans = Object.keys(types).filter(
    function type { return types[type].type === Boolean; });

  // Parse args
  const args = parseArgs(rawArgs || [], {
    boolean: boleans,
    string: Object.keys(types).filter(
      function type { return types[type].type === String || types[type].type === Object; }),
    default: boleans.reduce(function (total, bool) { return ({ ...total, [bool]: null }); }, {})
  });

  let options = {};
  try {
    // Load from "noderize" key in package.json, .noderizerc, or noderize.config.js
    const results = cosmiconfig("noderize").searchSync();

    if (results) {
      const configOptions = results.config || {};
      Object.keys(configOptions).forEach(function configOptionKey {
        if (types[configOptionKey] !== undefined) {
          const type = types[configOptionKey];
          let value = configOptions[configOptionKey];
          if (type.type === Array && !Array.isArray(value)) {
            value = [value];
          }
          value = run(type.run, value, { options });
          options[configOptionKey] = value;
        } else {
          log.warn("Config key '" + (configOptionKey) + "' doesn't do anything.");
        }
      });
    }
  } catch (error) {
    log.error("Could not read Noderize configuration.");
    log.error(error);
  }

  function parseArgType(arg, type, value) {
    switch (type.type) {
      case Boolean:
      case String:
        return type.type(value);
      case Number:
        const number = parseFloat(value);
        if (isNaN(number)) {
          log.error("Argument '" + (arg) + "' is not a number.");
          break;
        } else {
          return number;
        }
      case Object:
        try {
          return JSON.parse(value);
        } catch (error) {
          log.error("Could not parse JSON for argument '" + (arg) + "'.");
          log.error(error.message);

          break;
        }
      case Array:
        if (!Array.isArray(value)) {
          value = [value];
        }
        return value.map(function value { return parseArgType(arg, { type: type.subtype }, value); });
    }
  }

  Object.keys(args)
    .filter(function arg { return Object.keys(types).includes(arg); })
    .filter(function arg { return !types[arg].notArg; })
    .forEach(function arg {
      const type = types[arg];
      let argValue = args[arg];
      if (argValue !== null) {
        let value = parseArgType(arg, type, argValue);
        if (value !== undefined) {
          value = run(type.run, value, { options });

          options[arg] = value;
        }
      }
    });

  Object.keys(types).forEach(function typeName {
    const value = options[typeName];
    let type = types[typeName];
    if (value === undefined || type.merge) {
      let defaultValue = type.default;
      if (defaultValue instanceof Function) {
        defaultValue = defaultValue({ options, childPackage });
      }
      if (type.merge) {
        options[typeName] = merge({}, defaultValue, options[typeName]);
      } else {
        options[typeName] = defaultValue;
      }
    }
  });

  // Checks
  Object.keys(options).forEach(function option {
    const value = options[option];
    const type = types[option];
    if (type.type === Number) {
      if (type.integer && !Number.isInteger(value)) {
        log.error("Option '" + (option) + "' is not an integer.");
      }
      if (type.min !== undefined && value < type.min) {
        log.error("Option '" + (option) + "' is under minimum (" + (type.min) + ").");
      }
      if (type.max !== undefined && value > type.max) {
        log.error("Option '" + (option) + "' is over maximum (" + (type.max) + ").");
      }
    }
    if (type.choices !== undefined) {
      if (!type.choices.includes(value)) {
        log.error("Invalid choice for " + (option) + ": '" + (value) + "'.");
      }
    }
  });

  const languageList = options.languages;

  options.languages = { javascript: false, typescript: false };
  languageList.forEach(function language {
    if (options.languages[language] !== undefined) {
      options.languages[language] = true;
    } else {
      log.warn("Unknown language '" + (language) + "'");
    }
  });

