// --------------------------------------------------------------------------------------
app.get('/projects', function (req, res) {
    var projectsPerPage = 3;
    var page = req.query.page ? parseInt(req.query.page) : 1;
    var offset = (page - 1) * projectsPerPage;

    // Retrive the total amout of projects to be abel to calculate the pages needed
    db.get("SELECT COUNT(*) as total FROM projects", function (error, result) {
        if (error) {
            console.log("ERROR fetching total projects:", error);
            res.redirect('/');
        } else {
            var totalProjects = result.total;
            var totalPages = Math.ceil(totalProjects / projectsPerPage);

            db.all("SELECT * FROM projects LIMIT ? OFFSET ?", [projectsPerPage, offset], (err, projects) => {
                if (err) {
                    console.log("ERROR fetching projects:", err);
                    res.redirect('/');
                } else {
                    var model = {
                        projects: projects,
                        currentPage: page,
                        totalPages: totalPages,
                        isAdmin: req.session.isAdmin
                    };
                    res.render('projects.handlebars', model);
                }
            });
        }
    });
});

