var _import = require('react');

var NewBook = function ({ addBook }) {
    var [title, setTitle] = useState('');
    var [author, setAuthor] = useState('');

    var handleSubmit = (e) => {
        e.preventDefault();
        addBook({ title, author });
        setTitle('');
        setAuthor('');
    };

    return (
        <form onSubmit={handleSubmit}>
            <div>
                <label>Title:</label>
                <input 
                    type="text" 
                    value={title} 
                    onChange={(e) => setTitle(e.target.value)} 
                    required 
                />
            </div>
            <div>
                <label>Author:</label>
                <input 
                    type="text" 
                    value={author} 
                    onChange={(e) => setAuthor(e.target.value)} 
                    required 
                />
            </div>
            <button type="submit">Add Book</button>
        </form>
    );
};

module.exports = NewBook;

// Code Assisted with basic coding tools

/**
 * Format a post's creation time to a human-readable format.
 *
 * Examples:
 *  - Less than a minute ago: "Just now"
 *  - 1 minute ago: "1m"
 *  - 1 hour ago: "1h"
 *  - 1 day ago: "1d"
 *  - More than 1 day ago: "MMM D" (e.g. "Jan 24")
 *
 * @param {string} createdAt - The post's creation time as a string
 * @returns {string} The formatted date
 */
var formatPostDate = function (createdAt) {
  var currentDate = new Date();
  var createdAtDate = new Date(createdAt);

  var timeDifferenceInSeconds = Math.floor(
    (currentDate - createdAtDate) / 1000
  );
  var timeDifferenceInMinutes = Math.floor(timeDifferenceInSeconds / 60);
  var timeDifferenceInHours = Math.floor(timeDifferenceInMinutes / 60);
  var timeDifferenceInDays = Math.floor(timeDifferenceInHours / 24);

  if (timeDifferenceInDays > 1) {
    return createdAtDate.toLocaleDateString("en-US", {
      month: "short",
      day: "numeric",
    });
  } else if (timeDifferenceInDays === 1) {
    return "1d";
  } else if (timeDifferenceInHours >= 1) {
    return "" + (timeDifferenceInHours) + "h";
  } else if (timeDifferenceInMinutes >= 1) {
    return "" + (timeDifferenceInMinutes) + "m";
  } else {
    return "Just now";
  }
};

/**
 * Format a user's join date to a human-readable format.
 *
 * @param {string} createdAt - The user's join date as a string
 * @returns {string} The formatted date
 */
var formatMemberSinceDate = function (createdAt) {
  var date = new Date(createdAt);
  var months = [
    "January",
    "February",
    "March",
    "April",
    "May",
    "June",
    "July",
    "August",
    "September",
    "October",
    "November",
    "December",
  ];
  var month = months[date.getMonth()];
  var year = date.getFullYear();
  return "Joined " + (month) + " " + (year) + "";
};

var createWatcher = require('../src').createWatcher;

const MKR_TOKEN = '0xaaf64bfcc32d0f15873a02163e7e500671a4ffcd';
const MKR_WHALE = '0xdb33dfd3d61308c33c63209845dad3e6bfb2c674';
const MKR_FISH = '0x2dfcedcb401557354d0cf174876ab17bfd6f4efd';
const PRICE_FEED_ETH = '0xa5aA4e07F5255E14F02B385b1f04b35cC50bdb66';

// Preset can be 'mainnet', 'kovan', 'rinkeby', 'goerli' or 'xdai'
// var config = { preset: 'kovan' };

// Alternatively the rpcUrl and multicallAddress can be specified manually
const config = {
  rpcUrl: 'wss://kovan.infura.io/ws/v3/58073b4a32df4105906c702f167b91d2',
  multicallAddress: '0x2cc8688c5f75e365aaeeb4ea8d6a480405a48d2a',
  interval: 1000
};

(async function () {
  const watcher = createWatcher(
    [
      {
        call: [
          'getEthBalance(address)(uint256)',
          '0x72776bb917751225d24c07d0663b3780b2ada67c'
        ],
        returns: [['ETH_BALANCE', val => val / 10 ** 18]]
      },
      {
        target: MKR_TOKEN,
        call: ['balanceOf(address)(uint256)', MKR_WHALE],
        returns: [['BALANCE_OF_MKR_WHALE', val => val / 10 ** 18]]
      },
      {
        target: PRICE_FEED_ETH,
        call: ['peek()(uint256,bool)'],
        returns: [
          ['PRICE_FEED_ETH_PRICE', val => val / 10 ** 18],
          ['PRICE_FEED_ETH_SET']
        ]
      }
    ],
    config
  );

  watcher.subscribe(update => {
    console.log("Update: " + (update.type) + " = " + (update.value) + "");
  });

  watcher.batch().subscribe(updates => {
    // Handle batched updates here
  });

  watcher.onNewBlock(blockNumber => {
    console.log("New block: " + (blockNumber) + "");
  });

  setTimeout(async () => {
    watcher.start();

    await watcher.awaitInitialFetch();

    console.log('Initial fetch completed');

    // Update the calls
    setTimeout(() => {
      console.log('Updating calls...');
      const fetchWaiter = watcher.tap(calls => [
        ...calls,
        {
          target: MKR_TOKEN,
          call: ['balanceOf(address)(uint256)', MKR_FISH],
          returns: [['BALANCE_OF_MKR_FISH', val => val / 10 ** 18]]
        }
      ]);
      fetchWaiter.then(() => {
        console.log('Initial fetch completed');
      });
    }, 1000);

    // Recreate watcher (useful if network has changed)
    setTimeout(() => {
      console.log('Recreating with new calls and config...');
      const fetchWaiter = watcher.recreate(
        [
          {
            target: MKR_TOKEN,
            call: ['balanceOf(address)(uint256)', MKR_WHALE],
            returns: [['BALANCE_OF_MKR_WHALE', val => val / 10 ** 18]]
          }
        ],
        config
      );
      fetchWaiter.then(() => {
        console.log('Initial fetch completed');
      });
    }, 2000);

  }, 1);

  // When subscribing to state updates, previously cached values will be returned immediately
  // setTimeout(() => {
  //   console.log(
  //     'Subscribing to updates much later (will immediately return cached values)'
  //   );
  //   watcher.subscribe(update => {
  //     console.log(
  //       `Update (2nd subscription): ${update.type} = ${update.value}`
  //     );
  //   });
  //   watcher.onNewBlock(blockNumber => {
  //     console.log(`New block (2nd subscription): ${blockNumber}`);
  //   });
  // }, 15000);
})();

